insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-abraham_stars-4','picture',1,17,5,5,'Genesis 17:5',1,'What new name did God give Abram?',null,'["Peter", "Abraham", "Isaac", "Israel"]'::jsonb,1,'God said, "Thy name shall be Abraham; for a father of many nations have I made thee."','Read Genesis 17:5.','abraham_stars','An old man outside a desert tent gazing up at a sky full of stars.','KJV',array['abraham_stars','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Neither shall thy name any more be called Abram, but thy name shall be Abraham; for a father of many nations have I made thee.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-abraham_stars-5','picture',1,21,2,3,'Genesis 21:2-3',1,'Which wife of Abraham bore him Isaac in his old age?',null,'["Rebekah", "Sarah", "Rachel", "Leah"]'::jsonb,1,'Sarah conceived and bare Abraham a son in his old age, and Abraham called his name Isaac.','Read Genesis 21:2-3.','abraham_stars','An old man outside a desert tent gazing up at a sky full of stars.','KJV',array['abraham_stars','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'For Sarah conceived, and bare Abraham a son in his old age, at the set time of which God had spoken to him. And Abraham called the name of his son that was born unto him, whom Sarah bare to him, Isaac.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-joseph_coat-1','picture',1,37,3,3,'Genesis 37:3',1,'Which son received a special coat from his father Jacob (Israel)?',null,'["Samuel", "David", "Benjamin", "Joseph"]'::jsonb,3,'Israel loved Joseph more than his other children and made him a coat of many colours.','Read Genesis 37:3.','joseph_coat','A young man in a colourful coat stands in a field while older brothers watch from a distance.','KJV',array['joseph_coat','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-joseph_coat-2','picture',1,37,28,28,'Genesis 37:28',2,'To whom did Joseph''s brothers sell him?',null,'["A company of Ishmeelite merchants", "Roman traders", "Egyptian priests", "Philistine soldiers"]'::jsonb,0,'The brothers drew Joseph out of the pit and sold him to the Ishmeelites, who took him to Egypt.','Read Genesis 37:28.','joseph_coat','A young man in a colourful coat stands in a field while older brothers watch from a distance.','KJV',array['joseph_coat','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt.',null) on conflict (id) do nothing;
