insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-joseph_coat-4','picture',1,37,7,7,'Genesis 37:7',2,'In Joseph''s first dream, what made obeisance to his sheaf?',null,'["The sun and the moon", "Seven ears of corn", "Eleven stars", "His brothers'' sheaves"]'::jsonb,3,'Joseph dreamed that his brothers'' sheaves stood round about and made obeisance to his sheaf. (The sun, moon and eleven stars came in his second dream.)','Read Genesis 37:7.','joseph_coat','A young man in a colourful coat stands in a field while older brothers watch from a distance.','KJV',array['joseph_coat','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'For, behold, we were binding sheaves in the field, and, lo, my sheaf arose, and also stood upright; and, behold, your sheaves stood round about, and made obeisance to my sheaf.',null) on conflict (id) do nothing;
