insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-solomon_temple-4','picture',11,7,21,21,'1 Kings 7:21',4,'What names were given to the two bronze pillars of Solomon''s temple porch?',null,'["Urim and Thummim", "Jachin and Boaz", "Shem and Japheth", "Ebal and Gerizim"]'::jsonb,1,'The right pillar was called Jachin and the left pillar Boaz.','Read 1 Kings 7:21.','solomon_temple','A king in royal robes before a grand temple with bronze pillars as offerings smoke.','KJV',array['solomon_temple','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he set up the pillars in the porch of the temple: and he set up the right pillar, and called the name thereof Jachin: and he set up the left pillar, and called the name thereof Boaz.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-solomon_temple-5','picture',11,5,6,6,'1 Kings 5:6',3,'What trees did Solomon ask Hiram''s servants to cut from Lebanon?',null,'["Cedar trees", "Palm trees", "Sycamore trees", "Olive trees"]'::jsonb,0,'Solomon asked Hiram to "hew me cedar trees out of Lebanon." (Hiram also supplied fir.)','Read 1 Kings 5:6.','solomon_temple','A king in royal robes before a grand temple with bronze pillars as offerings smoke.','KJV',array['solomon_temple','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now therefore command thou that they hew me cedar trees out of Lebanon; and my servants shall be with thy servants: and unto thee will I give hire for thy servants according to all that thou shalt appoint: for thou knowest that there is not among us any that can skill to hew timber like unto the Sidonians.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-elijah_carmel-1','picture',11,18,36,38,'1 Kings 18:36-38',1,'Which prophet saw fire fall from heaven on Mount Carmel?',null,'["Elisha", "Isaiah", "Jeremiah", "Elijah"]'::jsonb,3,'After Elijah prayed, the fire of the LORD fell and consumed the burnt sacrifice.','Read 1 Kings 18:36-38.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it came to pass at the time of the offering of the evening sacrifice, that Elijah the prophet came near, and said, LORD God of Abraham, Isaac, and of Israel, let it be known this day that thou art God in Israel, and that I am thy servant, and that I have done all these things at thy word. Hear me, O LORD, hear me, that this people may know that thou art the LORD God, and that thou hast turned their heart back again. Then the fire of the LORD fell, and consumed the burnt sacrifice, and the wood, and the stones, and the dust, and licked up the water that was in the trench.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-elijah_carmel-2','picture',11,18,19,19,'1 Kings 18:19',1,'Prophets of which god opposed Elijah on Mount Carmel?',null,'["Dagon", "Chemosh", "Molech", "Baal"]'::jsonb,3,'Elijah asked Ahab to gather the prophets of Baal to Mount Carmel.','Read 1 Kings 18:19.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebel’s table.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-elijah_carmel-3','picture',11,18,19,19,'1 Kings 18:19',3,'How many prophets of Baal were gathered to Mount Carmel?',null,'["Seventy", "Four hundred and fifty", "One hundred and twenty", "Three hundred"]'::jsonb,1,'1 Kings 18:19 lists 450 prophets of Baal (and 400 prophets of the groves).','Read 1 Kings 18:19.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebel’s table.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-elijah_carmel-4','picture',11,18,43,44,'1 Kings 18:43-44',4,'How many times did Elijah send his servant to look toward the sea before a cloud appeared?',null,'["Forty", "Twelve", "Seven", "Three"]'::jsonb,2,'On the seventh time the servant saw a little cloud like a man''s hand.','Read 1 Kings 18:43-44.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And said to his servant, Go up now, look toward the sea. And he went up, and looked, and said, There is nothing. And he said, Go again seven times. And it came to pass at the seventh time, that he said, Behold, there ariseth a little cloud out of the sea, like a man’s hand. And he said, Go up, say unto Ahab, Prepare thy chariot, and get thee down, that the rain stop thee not.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-elijah_carmel-5','picture',11,18,39,39,'1 Kings 18:39',2,'When the fire fell on Mount Carmel, what did the people cry out?',null,'["Hosanna in the highest", "God save the king", "The LORD, he is the God", "Great is our god Baal"]'::jsonb,2,'The people fell on their faces and said, "The LORD, he is the God; the LORD, he is the God."','Read 1 Kings 18:39.','elijah_carmel','Fire falls from a stormy sky onto a stone altar while a prophet stands beside it.','KJV',array['elijah_carmel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And when all the people saw it, they fell on their faces: and they said, The LORD, he is the God; the LORD, he is the God.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-daniel_lions-1','picture',27,6,16,16,'Daniel 6:16',1,'Who was cast into the den of lions?',null,'["Daniel", "Shadrach", "Jeremiah", "Joseph"]'::jsonb,0,'King Darius commanded, and they cast Daniel into the den of lions.','Read Daniel 6:16.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then the king commanded, and they brought Daniel, and cast him into the den of lions. Now the king spake and said unto Daniel, Thy God whom thou servest continually, he will deliver thee.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-daniel_lions-2','picture',27,6,9,9,'Daniel 6:9',2,'Which king signed the decree that led to Daniel being thrown to the lions?',null,'["Nebuchadnezzar", "Darius", "Cyrus", "Belshazzar"]'::jsonb,1,'King Darius signed the writing and the decree.','Read Daniel 6:9.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Wherefore king Darius signed the writing and the decree.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-daniel_lions-3','picture',27,6,10,10,'Daniel 6:10',2,'How many times a day did Daniel kneel to pray?',null,'["Three", "Seven", "Two", "Once"]'::jsonb,0,'Daniel kneeled upon his knees three times a day and prayed.','Read Daniel 6:10.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now when Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-daniel_lions-4','picture',27,6,22,22,'Daniel 6:22',2,'According to Daniel, how was he protected from the lions?',null,'["The king''s guards stood watch", "He hid in a cave", "The lions were already fed", "God sent His angel and shut their mouths"]'::jsonb,3,'Daniel said, "My God hath sent his angel, and hath shut the lions'' mouths."','Read Daniel 6:22.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'My God hath sent his angel, and hath shut the lions’ mouths, that they have not hurt me: forasmuch as before him innocency was found in me; and also before thee, O king, have I done no hurt.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-daniel_lions-5','picture',27,6,18,18,'Daniel 6:18',1,'How did King Darius spend the night while Daniel was in the den of lions?',null,'["He went down into the den", "He passed the night fasting", "He slept soundly", "He held a great feast"]'::jsonb,1,'The king went to his palace and passed the night fasting, and his sleep went from him.','Read Daniel 6:18.','daniel_lions','A calm man in robes stands among resting lions in a dim stone den.','KJV',array['daniel_lions','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then the king went to his palace, and passed the night fasting: neither were instruments of musick brought before him: and his sleep went from him.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-esther_king-1','picture',17,5,2,2,'Esther 5:2',1,'Which queen approached the king uninvited to save her people?',null,'["Vashti", "Jezebel", "Bathsheba", "Esther"]'::jsonb,3,'When the king saw Esther, she obtained favour and he held out the golden sceptre.','Read Esther 5:2.','esther_king','A queen approaches a Persian king on his throne as he extends a golden sceptre.','KJV',array['esther_king','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it was so, when the king saw Esther the queen standing in the court, that she obtained favour in his sight: and the king held out to Esther the golden sceptre that was in his hand. So Esther drew near, and touched the top of the sceptre.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-esther_king-2','picture',17,5,2,2,'Esther 5:2',2,'What did the king hold out to welcome Esther?',null,'["A sword", "His signet ring", "A crown", "The golden sceptre"]'::jsonb,3,'Holding out the golden sceptre meant the visitor would live (Esther 4:11).','Read Esther 5:2.','esther_king','A queen approaches a Persian king on his throne as he extends a golden sceptre.','KJV',array['esther_king','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it was so, when the king saw Esther the queen standing in the court, that she obtained favour in his sight: and the king held out to Esther the golden sceptre that was in his hand. So Esther drew near, and touched the top of the sceptre.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-esther_king-3','picture',17,2,7,7,'Esther 2:7',1,'Who brought up Esther and took her as his own daughter?',null,'["Mordecai, her cousin", "Ezra", "Haman", "Nehemiah"]'::jsonb,0,'Mordecai brought up Esther, "his uncle''s daughter," and took her for his own daughter.','Read Esther 2:7.','esther_king','A queen approaches a Persian king on his throne as he extends a golden sceptre.','KJV',array['esther_king','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-esther_king-4','picture',17,3,6,6,'Esther 3:6',1,'Who plotted to destroy all the Jews in the Persian empire?',null,'["Haman", "Sanballat", "Goliath", "Mordecai"]'::jsonb,0,'Haman sought to destroy all the Jews throughout the kingdom of Ahasuerus.','Read Esther 3:6.','esther_king','A queen approaches a Persian king on his throne as he extends a golden sceptre.','KJV',array['esther_king','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he thought scorn to lay hands on Mordecai alone; for they had shewed him the people of Mordecai: wherefore Haman sought to destroy all the Jews that were throughout the whole kingdom of Ahasuerus, even the people of Mordecai.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-esther_king-5','picture',17,1,1,1,'Esther 1:1',3,'What is the name of the Persian king in the book of Esther (KJV)?',null,'["Darius", "Ahasuerus", "Artaxerxes", "Cyrus"]'::jsonb,1,'The book opens in the days of Ahasuerus, who reigned from India to Ethiopia.','Read Esther 1:1.','esther_king','A queen approaches a Persian king on his throne as he extends a golden sceptre.','KJV',array['esther_king','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now it came to pass in the days of Ahasuerus, (this is Ahasuerus which reigned, from India even unto Ethiopia, over an hundred and seven and twenty provinces:)',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-esther_king-6','picture',17,9,26,26,'Esther 9:26',3,'Which feast commemorates the deliverance in the book of Esther?',null,'["Purim", "Passover", "Pentecost", "Tabernacles"]'::jsonb,0,'"They called these days Purim after the name of Pur."','Read Esther 9:26.','esther_king','A queen approaches a Persian king on his throne as he extends a golden sceptre.','KJV',array['esther_king','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Wherefore they called these days Purim after the name of Pur. Therefore for all the words of this letter, and of that which they had seen concerning this matter, and which had come unto them,',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-nativity-1','picture',42,2,4,7,'Luke 2:4-7',1,'In which town was Jesus born?',null,'["Bethlehem", "Jerusalem", "Nazareth", "Capernaum"]'::jsonb,0,'Joseph and Mary went to Bethlehem, where Mary brought forth her firstborn son and laid him in a manger.','Read Luke 2:4-7.','nativity','A mother and newborn in a manger in a stable at night, with shepherds kneeling.','KJV',array['nativity','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Joseph also went up from Galilee, out of the city of Nazareth, into Judæa, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:) To be taxed with Mary his espoused wife, being great with child. And so it was, that, while they were there, the days were accomplished that she should be delivered. And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn.',null) on conflict (id) do nothing;
