insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-good_samaritan-2','picture',42,10,31,32,'Luke 10:31-32',2,'Which two travellers passed by on the other side?',null,'["Two Roman soldiers", "A priest and a Levite", "A scribe and a lawyer", "Two Pharisees"]'::jsonb,1,'First a priest and then a Levite passed by on the other side.','Read Luke 10:31-32.','good_samaritan','A traveller kneels to bandage a wounded man on a rocky road while two others walk away.','KJV',array['good_samaritan','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And by chance there came down a certain priest that way: and when he saw him, he passed by on the other side. And likewise a Levite, when he was at the place, came and looked on him, and passed by on the other side.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-good_samaritan-3','picture',42,10,30,30,'Luke 10:30',2,'On which road was the man attacked?',null,'["From Jerusalem to Jericho", "From Joppa to Caesarea", "From Nazareth to Cana", "From Jerusalem to Emmaus"]'::jsonb,0,'"A certain man went down from Jerusalem to Jericho, and fell among thieves."','Read Luke 10:30.','good_samaritan','A traveller kneels to bandage a wounded man on a rocky road while two others walk away.','KJV',array['good_samaritan','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Jesus answering said, A certain man went down from Jerusalem to Jericho, and fell among thieves, which stripped him of his raiment, and wounded him, and departed, leaving him half dead.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-good_samaritan-4','picture',42,10,29,29,'Luke 10:29',2,'Which question prompted Jesus to tell this parable?',null,'["\"And who is my neighbour?\"", "\"How often shall I forgive?\"", "\"Why do your disciples not fast?\"", "\"Who is the greatest?\""]'::jsonb,0,'A lawyer, willing to justify himself, asked, "And who is my neighbour?"','Read Luke 10:29.','good_samaritan','A traveller kneels to bandage a wounded man on a rocky road while two others walk away.','KJV',array['good_samaritan','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'But he, willing to justify himself, said unto Jesus, And who is my neighbour?',null) on conflict (id) do nothing;
