insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-paul_ship-3','picture',44,28,3,3,'Acts 28:3',2,'What fastened on Paul''s hand as he gathered sticks on the island?',null,'["A viper", "A crab", "A spider", "A scorpion"]'::jsonb,0,'A viper came out of the heat and fastened on his hand, but he felt no harm.','Read Acts 28:3.','paul_ship','A Roman ship breaks apart on rocks while passengers swim toward an island beach.','KJV',array['paul_ship','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And when Paul had gathered a bundle of sticks, and laid them on the fire, there came a viper out of the heat, and fastened on his hand.',null) on conflict (id) do nothing;
