insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-jonah_fish-8','picture',32,2,10,10,'Jonah 2:10',3,'What did the fish do when the LORD spoke to it?',null,'["Vomited Jonah out upon the dry land", "Swam to Tarshish", "Carried him to Joppa", "Released him in the deep"]'::jsonb,0,'"The LORD spake unto the fish, and it vomited out Jonah upon the dry land."','Read Jonah 2:10.','jonah_fish','Beneath a stormy sea, an enormous fish rises toward a man while a ship tosses above.','KJV',array['jonah_fish','Jonah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And the LORD spake unto the fish, and it vomited out Jonah upon the dry land.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-empty_tomb-5','picture',41,16,4,4,'Mark 16:4',2,'What did the women find had been rolled away?',null,'["The guards", "A curtain", "The stone", "The linen clothes"]'::jsonb,2,'They saw that the stone was rolled away: for it was very great.','Read Mark 16:4.','empty_tomb','Women carrying spices approach a rock-cut tomb whose stone has been rolled away.','KJV',array['empty_tomb','Mark']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And when they looked, they saw that the stone was rolled away: for it was very great.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-empty_tomb-6','picture',40,28,6,6,'Matthew 28:6',1,'What did the angel tell the women about Jesus?',null,'["He is sleeping", "He went to the temple", "He is risen", "He was taken away"]'::jsonb,2,'"He is not here: for he is risen, as he said."','Read Matthew 28:6.','empty_tomb','Women carrying spices approach a rock-cut tomb whose stone has been rolled away.','KJV',array['empty_tomb','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'He is not here: for he is risen, as he said. Come, see the place where the Lord lay.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('pic-empty_tomb-7','picture',43,20,2,4,'John 20:2-4',3,'Who ran with Peter to the tomb and got there first?',null,'["Thomas", "James", "Andrew", "The other disciple, whom Jesus loved"]'::jsonb,3,'The other disciple, whom Jesus loved, did outrun Peter and came first to the sepulchre.','Read John 20:2-4.','empty_tomb','Women carrying spices approach a rock-cut tomb whose stone has been rolled away.','KJV',array['empty_tomb','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then she runneth, and cometh to Simon Peter, and to the other disciple, whom Jesus loved, and saith unto them, They have taken away the Lord out of the sepulchre, and we know not where they have laid him. Peter therefore went forth, and that other disciple, and came to the sepulchre. So they ran both together: and the other disciple did outrun Peter, and came first to the sepulchre.',null) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-noah','whoami',1,6,13,14,'Genesis 6:13-14',1,'Who am I?','["I lived before a great flood.", "God told me to build with gopher wood.", "My sons were Shem, Ham and Japheth.", "I built the ark."]'::jsonb,'["Abraham", "Enoch", "Lot", "Noah"]'::jsonb,3,'God told Noah, "Make thee an ark of gopher wood."','Look in Genesis.',null,null,'KJV',array['noah','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And God said unto Noah, The end of all flesh is come before me; for the earth is filled with violence through them; and, behold, I will destroy them with the earth. Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch.','[[{"ref": "Genesis 7:6", "text": "And Noah was six hundred years old when the flood of waters was upon the earth."}], [{"ref": "Genesis 6:14", "text": "Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch."}], [{"ref": "Genesis 6:10", "text": "And Noah begat three sons, Shem, Ham, and Japheth."}], [{"ref": "Hebrews 11:7", "text": "By faith Noah, being warned of God of things not seen as yet, moved with fear, prepared an ark to the saving of his house; by the which he condemned the world, and became heir of the righteousness which is by faith."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-moses','whoami',2,3,2,4,'Exodus 3:2-4',1,'Who am I?','["As a baby I was hidden in an ark of bulrushes.", "I was raised in Pharaoh''s household.", "I saw a bush burn without being consumed.", "I led Israel out of Egypt."]'::jsonb,'["Moses", "Aaron", "Joseph", "Joshua"]'::jsonb,0,'God called to Moses out of the midst of the burning bush.','Look in Exodus.',null,null,'KJV',array['moses','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed. And Moses said, I will now turn aside, and see this great sight, why the bush is not burnt. And when the LORD saw that he turned aside to see, God called unto him out of the midst of the bush, and said, Moses, Moses. And he said, Here am I.','[[{"ref": "Exodus 2:3", "text": "And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink."}], [{"ref": "Exodus 2:10", "text": "And the child grew, and she brought him unto Pharaoh’s daughter, and he became her son. And she called his name Moses: and she said, Because I drew him out of the water."}], [{"ref": "Exodus 3:2", "text": "And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed."}], [{"ref": "Acts 7:36", "text": "He brought them out, after that he had shewed wonders and signs in the land of Egypt, and in the Red sea, and in the wilderness forty years."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-ruth','whoami',8,1,16,16,'Ruth 1:16',2,'Who am I?','["I was a woman of Moab.", "I told my mother-in-law: whither thou goest, I will go.", "I gleaned in the fields of Boaz.", "I became an ancestor of King David."]'::jsonb,'["Naomi", "Ruth", "Rahab", "Orpah"]'::jsonb,1,'Ruth said to Naomi, "Whither thou goest, I will go."','Look in the books of history.',null,null,'KJV',array['ruth','Ruth']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:','[[{"ref": "Ruth 1:4", "text": "And they took them wives of the women of Moab; the name of the one was Orpah, and the name of the other Ruth: and they dwelled there about ten years."}], [{"ref": "Ruth 1:16", "text": "And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:"}], [{"ref": "Ruth 2:3", "text": "And she went, and came, and gleaned in the field after the reapers: and her hap was to light on a part of the field belonging unto Boaz, who was of the kindred of Elimelech."}], [{"ref": "Ruth 4:13-17", "text": "So Boaz took Ruth, and she was his wife: and when he went in unto her, the LORD gave her conception, and she bare a son. And the women said unto Naomi, Blessed be the LORD, which hath not left thee this day without a kinsman, that his name may be famous in Israel. And he shall be unto thee a restorer of thy life, and a nourisher of thine old age: for thy daughter in law, which loveth thee, which is better to thee than seven sons, hath born him. And Naomi took the child, and laid it in her bosom, and became nurse unto it. And the women her neighbours gave it a name, saying, There is a son born to Naomi; and they called his name Obed: he is the father of Jesse, the father of David."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-samuel','whoami',9,3,10,10,'1 Samuel 3:10',2,'Who am I?','["My mother Hannah prayed for me at Shiloh.", "As a boy I served Eli the priest.", "I heard the LORD call my name in the night.", "I anointed both Saul and David."]'::jsonb,'["Nathan", "Eli", "Gad", "Samuel"]'::jsonb,3,'The LORD came and called, "Samuel, Samuel."','Look in the books of history.',null,null,'KJV',array['samuel','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth.','[[{"ref": "1 Samuel 1:9-11", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD. And she was in bitterness of soul, and prayed unto the LORD, and wept sore. And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head."}, {"ref": "1 Samuel 1:20", "text": "Wherefore it came to pass, when the time was come about after Hannah had conceived, that she bare a son, and called his name Samuel, saying, Because I have asked him of the LORD."}], [{"ref": "1 Samuel 2:11", "text": "And Elkanah went to Ramah to his house. And the child did minister unto the LORD before Eli the priest."}, {"ref": "1 Samuel 3:1", "text": "And the child Samuel ministered unto the LORD before Eli. And the word of the LORD was precious in those days; there was no open vision."}], [{"ref": "1 Samuel 3:10", "text": "And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth."}], [{"ref": "1 Samuel 10:1", "text": "Then Samuel took a vial of oil, and poured it upon his head, and kissed him, and said, Is it not because the LORD hath anointed thee to be captain over his inheritance?"}, {"ref": "1 Samuel 16:13", "text": "Then Samuel took the horn of oil, and anointed him in the midst of his brethren: and the Spirit of the LORD came upon David from that day forward. So Samuel rose up, and went to Ramah."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-samson','whoami',7,16,30,30,'Judges 16:30',1,'Who am I?','["I was a Nazarite from birth.", "I tore a young lion with my bare hands.", "Delilah learned the secret of my strength.", "I pulled down the house where the Philistines gathered."]'::jsonb,'["Samson", "Gideon", "Saul", "Jephthah"]'::jsonb,0,'Samson bowed himself with all his might and the house fell.','Look in Judges.',null,null,'KJV',array['samson','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein. So the dead which he slew at his death were more than they which he slew in his life.','[[{"ref": "Judges 16:17", "text": "That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man."}], [{"ref": "Judges 14:5-6", "text": "Then went Samson down, and his father and his mother, to Timnath, and came to the vineyards of Timnath: and, behold, a young lion roared against him. And the Spirit of the LORD came mightily upon him, and he rent him as he would have rent a kid, and he had nothing in his hand: but he told not his father or his mother what he had done."}], [{"ref": "Judges 16:17-18", "text": "That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother’s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man. And when Delilah saw that he had told her all his heart, she sent and called for the lords of the Philistines, saying, Come up this once, for he hath shewed me all his heart. Then the lords of the Philistines came up unto her, and brought money in their hand."}], [{"ref": "Judges 16:29-30", "text": "And Samson took hold of the two middle pillars upon which the house stood, and on which it was borne up, of the one with his right hand, and of the other with his left. And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein. So the dead which he slew at his death were more than they which he slew in his life."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-gideon','whoami',7,7,7,7,'Judges 7:7',3,'Who am I?','["An angel found me threshing wheat by a winepress.", "I tested God with a fleece.", "My army was reduced to three hundred men.", "We carried trumpets, pitchers and lamps."]'::jsonb,'["Joshua", "Gideon", "Barak", "Ehud"]'::jsonb,1,'The LORD said to Gideon, "By the three hundred men... will I save you."','Look in Judges.',null,null,'KJV',array['gideon','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the LORD said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place.','[[{"ref": "Judges 6:11-12", "text": "And there came an angel of the LORD, and sat under an oak which was in Ophrah, that pertained unto Joash the Abi-ezrite: and his son Gideon threshed wheat by the winepress, to hide it from the Midianites. And the angel of the LORD appeared unto him, and said unto him, The LORD is with thee, thou mighty man of valour."}], [{"ref": "Judges 6:36-40", "text": "And Gideon said unto God, If thou wilt save Israel by mine hand, as thou hast said, Behold, I will put a fleece of wool in the floor; and if the dew be on the fleece only, and it be dry upon all the earth beside, then shall I know that thou wilt save Israel by mine hand, as thou hast said. And it was so: for he rose up early on the morrow, and thrust the fleece together, and wringed the dew out of the fleece, a bowl full of water. And Gideon said unto God, Let not thine anger be hot against me, and I will speak but this once: let me prove, I pray thee, but this once with the fleece; let it now be dry only upon the fleece, and upon all the ground let there be dew. And God did so that night: …"}], [{"ref": "Judges 7:7", "text": "And the LORD said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place."}], [{"ref": "Judges 7:16", "text": "And he divided the three hundred men into three companies, and he put a trumpet in every man’s hand, with empty pitchers, and lamps within the pitchers."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-deborah','whoami',7,4,4,5,'Judges 4:4-5',3,'Who am I?','["I was a prophetess.", "I judged Israel under a palm tree in mount Ephraim.", "I summoned Barak to fight Sisera.", "A song of mine is recorded in Judges 5."]'::jsonb,'["Miriam", "Jael", "Huldah", "Deborah"]'::jsonb,3,'Deborah judged Israel and dwelt under the palm tree of Deborah.','Look in Judges.',null,null,'KJV',array['deborah','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time. And she dwelt under the palm tree of Deborah between Ramah and Beth-el in mount Ephraim: and the children of Israel came up to her for judgment.','[[{"ref": "Judges 4:4", "text": "And Deborah, a prophetess, the wife of Lapidoth, she judged Israel at that time."}], [{"ref": "Judges 4:5", "text": "And she dwelt under the palm tree of Deborah between Ramah and Beth-el in mount Ephraim: and the children of Israel came up to her for judgment."}], [{"ref": "Judges 4:6-7", "text": "And she sent and called Barak the son of Abinoam out of Kedesh-naphtali, and said unto him, Hath not the LORD God of Israel commanded, saying, Go and draw toward mount Tabor, and take with thee ten thousand men of the children of Naphtali and of the children of Zebulun? And I will draw unto thee to the river Kishon Sisera, the captain of Jabin’s army, with his chariots and his multitude; and I will deliver him into thine hand."}], [{"ref": "Judges 5:1", "text": "Then sang Deborah and Barak the son of Abinoam on that day, saying,"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-elisha','whoami',12,2,9,9,'2 Kings 2:9',3,'Who am I?','["I was ploughing with twelve yoke of oxen when I was called.", "I asked for a double portion of my master''s spirit.", "I took up the mantle that fell from Elijah.", "I told Naaman to wash in the Jordan seven times."]'::jsonb,'["Obadiah", "Gehazi", "Elijah", "Elisha"]'::jsonb,3,'Elisha said, "Let a double portion of thy spirit be upon me."','Look in 2 Kings.',null,null,'KJV',array['elisha','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me.','[[{"ref": "1 Kings 19:19", "text": "So he departed thence, and found Elisha the son of Shaphat, who was plowing with twelve yoke of oxen before him, and he with the twelfth: and Elijah passed by him, and cast his mantle upon him."}], [{"ref": "2 Kings 2:9", "text": "And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me."}], [{"ref": "2 Kings 2:13", "text": "He took up also the mantle of Elijah that fell from him, and went back, and stood by the bank of Jordan;"}], [{"ref": "2 Kings 5:10", "text": "And Elisha sent a messenger unto him, saying, Go and wash in Jordan seven times, and thy flesh shall come again to thee, and thou shalt be clean."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-joseph','whoami',1,41,41,41,'Genesis 41:41',1,'Who am I?','["I was my father''s favourite son.", "My brothers sold me into slavery.", "I interpreted Pharaoh''s dreams.", "I was set over all the land of Egypt."]'::jsonb,'["Moses", "Judah", "Joseph", "Benjamin"]'::jsonb,2,'Pharaoh said to Joseph, "I have set thee over all the land of Egypt."','Look in Genesis.',null,null,'KJV',array['joseph','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Pharaoh said unto Joseph, See, I have set thee over all the land of Egypt.','[[{"ref": "Genesis 37:3", "text": "Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours."}], [{"ref": "Genesis 37:26-28", "text": "And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood? Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content. Then there passed by Midianites merchantmen; and they drew and lifted up Joseph out of the pit, and sold Joseph to the Ishmeelites for twenty pieces of silver: and they brought Joseph into Egypt."}], [{"ref": "Genesis 41:25", "text": "And Joseph said unto Pharaoh, The dream of Pharaoh is one: God hath shewed Pharaoh what he is about to do."}], [{"ref": "Genesis 41:41", "text": "And Pharaoh said unto Joseph, See, I have set thee over all the land of Egypt."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-abraham','whoami',1,22,1,2,'Genesis 22:1-2',1,'Who am I?','["I left Ur of the Chaldees.", "God changed my name.", "My wife laughed at God''s promise of a son.", "God tested me in the land of Moriah."]'::jsonb,'["Abraham", "Isaac", "Jacob", "Lot"]'::jsonb,0,'God tempted (tested) Abraham and sent him to the land of Moriah.','Look in Genesis.',null,null,'KJV',array['abraham','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am. And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of.','[[{"ref": "Genesis 11:31", "text": "And Terah took Abram his son, and Lot the son of Haran his son’s son, and Sarai his daughter in law, his son Abram’s wife; and they went forth with them from Ur of the Chaldees, to go into the land of Canaan; and they came unto Haran, and dwelt there."}], [{"ref": "Genesis 17:5", "text": "Neither shall thy name any more be called Abram, but thy name shall be Abraham; for a father of many nations have I made thee."}], [{"ref": "Genesis 18:12", "text": "Therefore Sarah laughed within herself, saying, After I am waxed old shall I have pleasure, my lord being old also?"}], [{"ref": "Genesis 22:1-2", "text": "And it came to pass after these things, that God did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am. And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jacob','whoami',1,32,28,28,'Genesis 32:28',1,'Who am I?','["I was born holding my twin brother''s heel.", "I bought my brother''s birthright with pottage.", "I dreamed of a ladder reaching to heaven.", "God renamed me Israel."]'::jsonb,'["Isaac", "Laban", "Jacob", "Esau"]'::jsonb,2,'"Thy name shall be called no more Jacob, but Israel."','Look in Genesis.',null,null,'KJV',array['jacob','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And he said, Thy name shall be called no more Jacob, but Israel: for as a prince hast thou power with God and with men, and hast prevailed.','[[{"ref": "Genesis 25:26", "text": "And after that came his brother out, and his hand took hold on Esau’s heel; and his name was called Jacob: and Isaac was threescore years old when she bare them."}], [{"ref": "Genesis 25:33-34", "text": "And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob. Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright."}], [{"ref": "Genesis 28:12", "text": "And he dreamed, and behold a ladder set up on the earth, and the top of it reached to heaven: and behold the angels of God ascending and descending on it."}], [{"ref": "Genesis 35:10", "text": "And God said unto him, Thy name is Jacob: thy name shall not be called any more Jacob, but Israel shall be thy name: and he called his name Israel."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-esau','whoami',1,25,30,33,'Genesis 25:30-33',2,'Who am I?','["I was a cunning hunter.", "I was born red and hairy.", "I sold my birthright for a meal.", "I am also called Edom."]'::jsonb,'["Ishmael", "Nimrod", "Jacob", "Esau"]'::jsonb,3,'Esau sold his birthright unto Jacob.','Look in Genesis.',null,null,'KJV',array['esau','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Esau said to Jacob, Feed me, I pray thee, with that same red pottage; for I am faint: therefore was his name called Edom. And Jacob said, Sell me this day thy birthright. And Esau said, Behold, I am at the point to die: and what profit shall this birthright do to me? And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob.','[[{"ref": "Genesis 25:27", "text": "And the boys grew: and Esau was a cunning hunter, a man of the field; and Jacob was a plain man, dwelling in tents."}], [{"ref": "Genesis 25:25", "text": "And the first came out red, all over like an hairy garment; and they called his name Esau."}], [{"ref": "Genesis 25:33-34", "text": "And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob. Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright."}], [{"ref": "Genesis 36:1", "text": "Now these are the generations of Esau, who is Edom."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-joshua','whoami',6,24,15,15,'Joshua 24:15',1,'Who am I?','["I was one of twelve men sent to spy out Canaan.", "I succeeded Moses as leader.", "The walls of Jericho fell when the people shouted.", "I said: As for me and my house, we will serve the LORD."]'::jsonb,'["Joshua", "Caleb", "Gideon", "Aaron"]'::jsonb,0,'Joshua 24:15: "As for me and my house, we will serve the LORD."','Look in the books of history.',null,null,'KJV',array['joshua','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.','[[{"ref": "Numbers 13:2-16", "text": "Send thou men, that they may search the land of Canaan, which I give unto the children of Israel: of every tribe of their fathers shall ye send a man, every one a ruler among them. And Moses by the commandment of the LORD sent them from the wilderness of Paran: all those men were heads of the children of Israel. And these were their names: of the tribe of Reuben, Shammua the son of Zaccur. Of the tribe of Simeon, Shaphat the son of Hori. Of the tribe of Judah, Caleb the son of Jephunneh. Of the tribe of Issachar, Igal the son of Joseph. …"}], [{"ref": "Joshua 1:1-2", "text": "Now after the death of Moses the servant of the LORD it came to pass, that the LORD spake unto Joshua the son of Nun, Moses’ minister, saying, Moses my servant is dead; now therefore arise, go over this Jordan, thou, and all this people, unto the land which I do give to them, even to the children of Israel."}], [{"ref": "Joshua 6:16", "text": "And it came to pass at the seventh time, when the priests blew with the trumpets, Joshua said unto the people, Shout; for the LORD hath given you the city."}, {"ref": "Joshua 6:20", "text": "So the people shouted when the priests blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city."}], [{"ref": "Joshua 24:15", "text": "And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-rahab','whoami',6,2,1,18,'Joshua 2:1-18',2,'Who am I?','["My house was upon the town wall of Jericho.", "I hid two Israelite spies.", "I let them down by a cord through a window.", "A line of scarlet thread marked my home."]'::jsonb,'["Rahab", "Jael", "Deborah", "Ruth"]'::jsonb,0,'The spies told Rahab to bind the scarlet thread in the window.','Look in Joshua.',null,null,'KJV',array['rahab','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot’s house, named Rahab, and lodged there. And it was told the king of Jericho, saying, Behold, there came men in hither to night of the children of Israel to search out the country. And the king of Jericho sent unto Rahab, saying, Bring forth the men that are come to thee, which are entered into thine house: for they be come to search out all the country. And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were: And it came to pass about the time of shutting of the gate, when it was …','[[{"ref": "Joshua 2:15", "text": "Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall."}], [{"ref": "Joshua 2:4", "text": "And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were:"}], [{"ref": "Joshua 2:15", "text": "Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall."}], [{"ref": "Joshua 2:17-21", "text": "And the men said unto her, We will be blameless of this thine oath which thou hast made us swear. Behold, when we come into the land, thou shalt bind this line of scarlet thread in the window which thou didst let us down by: and thou shalt bring thy father, and thy mother, and thy brethren, and all thy father’s household, home unto thee. And it shall be, that whosoever shall go out of the doors of thy house into the street, his blood shall be upon his head, and we will be guiltless: and whosoever shall be with thee in the house, his blood shall be on our head, if any hand be upon him. And if thou utter this our business, then we will be quit of thine oath which thou hast made us to swear. …"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-david','whoami',9,16,23,23,'1 Samuel 16:23',1,'Who am I?','["I was the youngest son of Jesse.", "I played the harp for King Saul.", "I defeated Goliath.", "I became king over Israel."]'::jsonb,'["Saul", "Jonathan", "David", "Solomon"]'::jsonb,2,'David took an harp and played, so Saul was refreshed.','Look in 1 Samuel.',null,null,'KJV',array['david','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And it came to pass, when the evil spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him.','[[{"ref": "1 Samuel 16:11", "text": "And Samuel said unto Jesse, Are here all thy children? And he said, There remaineth yet the youngest, and, behold, he keepeth the sheep. And Samuel said unto Jesse, Send and fetch him: for we will not sit down till he come hither."}], [{"ref": "1 Samuel 16:23", "text": "And it came to pass, when the evil spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him."}], [{"ref": "1 Samuel 17:49-50", "text": "And David put his hand in his bag, and took thence a stone, and slang it, and smote the Philistine in his forehead, that the stone sunk into his forehead; and he fell upon his face to the earth. So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but there was no sword in the hand of David."}], [{"ref": "2 Samuel 5:3", "text": "So all the elders of Israel came to the king to Hebron; and king David made a league with them in Hebron before the LORD: and they anointed David king over Israel."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-saul','whoami',9,9,2,2,'1 Samuel 9:2',2,'Who am I?','["I was of the tribe of Benjamin.", "From my shoulders upward I was higher than any of the people.", "Samuel anointed me as Israel''s first king.", "I consulted a woman at Endor."]'::jsonb,'["Absalom", "Jonathan", "David", "Saul"]'::jsonb,3,'Saul was "higher than any of the people" from his shoulders upward.','Look in 1 Samuel.',null,null,'KJV',array['saul','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And he had a son, whose name was Saul, a choice young man, and a goodly: and there was not among the children of Israel a goodlier person than he: from his shoulders and upward he was higher than any of the people.','[[{"ref": "1 Samuel 9:21", "text": "And Saul answered and said, Am not I a Benjamite, of the smallest of the tribes of Israel? and my family the least of all the families of the tribe of Benjamin? wherefore then speakest thou so to me?"}], [{"ref": "1 Samuel 9:2", "text": "And he had a son, whose name was Saul, a choice young man, and a goodly: and there was not among the children of Israel a goodlier person than he: from his shoulders and upward he was higher than any of the people."}], [{"ref": "1 Samuel 9:17", "text": "And when Samuel saw Saul, the LORD said unto him, Behold the man whom I spake to thee of! this same shall reign over my people."}, {"ref": "1 Samuel 10:1", "text": "Then Samuel took a vial of oil, and poured it upon his head, and kissed him, and said, Is it not because the LORD hath anointed thee to be captain over his inheritance?"}], [{"ref": "1 Samuel 28:7-8", "text": "Then said Saul unto his servants, Seek me a woman that hath a familiar spirit, that I may go to her, and enquire of her. And his servants said to him, Behold, there is a woman that hath a familiar spirit at Endor. And Saul disguised himself, and put on other raiment, and he went, and two men with him, and they came to the woman by night: and he said, I pray thee, divine unto me by the familiar spirit, and bring me him up, whom I shall name unto thee."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-solomon','whoami',11,3,10,12,'1 Kings 3:10-12',1,'Who am I?','["My mother was Bathsheba.", "I asked God for an understanding heart.", "I built the temple in Jerusalem.", "I judged between two women who both claimed one baby."]'::jsonb,'["David", "Rehoboam", "Solomon", "Hezekiah"]'::jsonb,2,'God gave Solomon "a wise and an understanding heart."','Look in 1 Kings.',null,null,'KJV',array['solomon','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the speech pleased the Lord, that Solomon had asked this thing. And God said unto him, Because thou hast asked this thing, and hast not asked for thyself long life; neither hast asked riches for thyself, nor hast asked the life of thine enemies; but hast asked for thyself understanding to discern judgment; Behold, I have done according to thy words: lo, I have given thee a wise and an understanding heart; so that there was none like thee before thee, neither after thee shall any arise like unto thee.','[[{"ref": "2 Samuel 12:24", "text": "And David comforted Bath-sheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him."}], [{"ref": "1 Kings 3:9", "text": "Give therefore thy servant an understanding heart to judge thy people, that I may discern between good and bad: for who is able to judge this thy so great a people?"}], [{"ref": "1 Kings 6:14", "text": "So Solomon built the house, and finished it."}], [{"ref": "1 Kings 3:16-27", "text": "Then came there two women, that were harlots, unto the king, and stood before him. And the one woman said, O my lord, I and this woman dwell in one house; and I was delivered of a child with her in the house. And it came to pass the third day after that I was delivered, that this woman was delivered also: and we were together; there was no stranger with us in the house, save we two in the house. And this woman’s child died in the night; because she overlaid it. And she arose at midnight, and took my son from beside me, while thine handmaid slept, and laid it in her bosom, and laid her dead child in my bosom. And when I rose in the morning to give my child suck, behold, it was dead: but when …"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-elijah','whoami',11,17,1,6,'1 Kings 17:1-6',2,'Who am I?','["I was a Tishbite.", "Ravens fed me by the brook Cherith.", "I challenged the prophets of Baal on Mount Carmel.", "I went up by a whirlwind into heaven."]'::jsonb,'["Jonah", "Elisha", "Elijah", "Amos"]'::jsonb,2,'Ravens brought Elijah bread and flesh morning and evening.','Look in 1 Kings.',null,null,'KJV',array['elijah','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word. And the word of the LORD came unto him, saying, Get thee hence, and turn thee eastward, and hide thyself by the brook Cherith, that is before Jordan. And it shall be, that thou shalt drink of the brook; and I have commanded the ravens to feed thee there. So he went and did according unto the word of the LORD: for he went and dwelt by the brook Cherith, that is before Jordan. And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the …','[[{"ref": "1 Kings 17:1", "text": "And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word."}], [{"ref": "1 Kings 17:1-6", "text": "And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word. And the word of the LORD came unto him, saying, Get thee hence, and turn thee eastward, and hide thyself by the brook Cherith, that is before Jordan. And it shall be, that thou shalt drink of the brook; and I have commanded the ravens to feed thee there. So he went and did according unto the word of the LORD: for he went and dwelt by the brook Cherith, that is before Jordan. And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the …"}], [{"ref": "1 Kings 18:19-24", "text": "Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebel’s table. So Ahab sent unto all the children of Israel, and gathered the prophets together unto mount Carmel. And Elijah came unto all the people, and said, How long halt ye between two opinions? if the LORD be God, follow him: but if Baal, then follow him. And the people answered him not a word. Then said Elijah unto the people, I, even I only, remain a prophet of the LORD; but Baal’s prophets are four hundred and fifty men. Let them therefore give us two bullocks; and let them choose one bullock for themselves, …"}], [{"ref": "2 Kings 2:11", "text": "And it came to pass, as they still went on, and talked, that, behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-daniel','whoami',27,6,23,23,'Daniel 6:23',1,'Who am I?','["I was taken captive to Babylon as a young man.", "I purposed not to defile myself with the king''s meat.", "I read the writing on the wall.", "I was delivered from the den of lions."]'::jsonb,'["Nehemiah", "Ezekiel", "Daniel", "Jeremiah"]'::jsonb,2,'Daniel was taken up out of the den, and no manner of hurt was found upon him.','Look in the Major Prophets.',null,null,'KJV',array['daniel','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Then was the king exceeding glad for him, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no manner of hurt was found upon him, because he believed in his God.','[[{"ref": "Daniel 1:1-6", "text": "In the third year of the reign of Jehoiakim king of Judah came Nebuchadnezzar king of Babylon unto Jerusalem, and besieged it. And the Lord gave Jehoiakim king of Judah into his hand, with part of the vessels of the house of God: which he carried into the land of Shinar to the house of his god; and he brought the vessels into the treasure house of his god. And the king spake unto Ashpenaz the master of his eunuchs, that he should bring certain of the children of Israel, and of the king’s seed, and of the princes; Children in whom was no blemish, but well favoured, and skilful in all wisdom, and cunning in knowledge, and understanding science, and such as had ability in them to stand in the …"}], [{"ref": "Daniel 1:8", "text": "But Daniel purposed in his heart that he would not defile himself with the portion of the king’s meat, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself."}], [{"ref": "Daniel 5:25-28", "text": "And this is the writing that was written, MENE, MENE, TEKEL, UPHARSIN. This is the interpretation of the thing: MENE; God hath numbered thy kingdom, and finished it. TEKEL; Thou art weighed in the balances, and art found wanting. PERES; Thy kingdom is divided, and given to the Medes and Persians."}], [{"ref": "Daniel 6:22-23", "text": "My God hath sent his angel, and hath shut the lions’ mouths, that they have not hurt me: forasmuch as before him innocency was found in me; and also before thee, O king, have I done no hurt. Then was the king exceeding glad for him, and commanded that they should take Daniel up out of the den. So Daniel was taken up out of the den, and no manner of hurt was found upon him, because he believed in his God."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-esther','whoami',17,4,16,16,'Esther 4:16',1,'Who am I?','["I was raised by my cousin Mordecai.", "I became queen in Persia.", "I said: If I perish, I perish.", "The feast of Purim remembers my people''s deliverance."]'::jsonb,'["Deborah", "Esther", "Vashti", "Ruth"]'::jsonb,1,'Esther resolved to go in unto the king, "and if I perish, I perish."','Look in the books of history.',null,null,'KJV',array['esther','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish.','[[{"ref": "Esther 2:7", "text": "And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter."}], [{"ref": "Esther 1:3", "text": "In the third year of his reign, he made a feast unto all his princes and his servants; the power of Persia and Media, the nobles and princes of the provinces, being before him:"}, {"ref": "Esther 2:17", "text": "And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti."}], [{"ref": "Esther 4:16", "text": "Go, gather together all the Jews that are present in Shushan, and fast ye for me, and neither eat nor drink three days, night or day: I also and my maidens will fast likewise; and so will I go in unto the king, which is not according to the law: and if I perish, I perish."}], [{"ref": "Esther 9:22", "text": "As the days wherein the Jews rested from their enemies, and the month which was turned unto them from sorrow to joy, and from mourning into a good day: that they should make them days of feasting and joy, and of sending portions one to another, and gifts to the poor."}, {"ref": "Esther 9:26-28", "text": "Wherefore they called these days Purim after the name of Pur. Therefore for all the words of this letter, and of that which they had seen concerning this matter, and which had come unto them, The Jews ordained, and took upon them, and upon their seed, and upon all such as joined themselves unto them, so as it should not fail, that they would keep these two days according to their writing, and according to their appointed time every year; And that these days should be remembered and kept throughout every generation, every family, every province, and every city; and that these days of Purim should not fail from among the Jews, nor the memorial of them perish from their seed."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-nehemiah','whoami',16,6,15,15,'Nehemiah 6:15',3,'Who am I?','["I was cupbearer to King Artaxerxes.", "I wept over Jerusalem''s broken walls.", "I led the rebuilding of the city wall.", "The wall was finished in fifty-two days."]'::jsonb,'["Nehemiah", "Ezra", "Zerubbabel", "Haggai"]'::jsonb,0,'"So the wall was finished... in fifty and two days."','Look in the books of history.',null,null,'KJV',array['nehemiah','Nehemiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days.','[[{"ref": "Nehemiah 1:11", "text": "O Lord, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king’s cupbearer."}, {"ref": "Nehemiah 2:1", "text": "And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, that wine was before him: and I took up the wine, and gave it unto the king. Now I had not been beforetime sad in his presence."}], [{"ref": "Nehemiah 1:3-4", "text": "And they said unto me, The remnant that are left of the captivity there in the province are in great affliction and reproach: the wall of Jerusalem also is broken down, and the gates thereof are burned with fire. And it came to pass, when I heard these words, that I sat down and wept, and mourned certain days, and fasted, and prayed before the God of heaven,"}], [{"ref": "Nehemiah 2:17-18", "text": "Then said I unto them, Ye see the distress that we are in, how Jerusalem lieth waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach. Then I told them of the hand of my God which was good upon me; as also the king’s words that he had spoken unto me. And they said, Let us rise up and build. So they strengthened their hands for this good work."}], [{"ref": "Nehemiah 6:15", "text": "So the wall was finished in the twenty and fifth day of the month Elul, in fifty and two days."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jonah','whoami',32,1,1,1,'Jonah 1:1',1,'Who am I?','["I was a prophet, the son of Amittai.", "I fled from God''s call on a ship.", "I spent three days inside a great fish.", "I was displeased when Nineveh repented."]'::jsonb,'["Nahum", "Hosea", "Amos", "Jonah"]'::jsonb,3,'The word of the LORD came unto Jonah the son of Amittai.','Look in the Minor Prophets.',null,null,'KJV',array['jonah','Jonah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Now the word of the LORD came unto Jonah the son of Amittai, saying,','[[{"ref": "2 Kings 14:25", "text": "He restored the coast of Israel from the entering of Hamath unto the sea of the plain, according to the word of the LORD God of Israel, which he spake by the hand of his servant Jonah, the son of Amittai, the prophet, which was of Gath-hepher."}], [{"ref": "Jonah 1:3", "text": "But Jonah rose up to flee unto Tarshish from the presence of the LORD, and went down to Joppa; and he found a ship going to Tarshish: so he paid the fare thereof, and went down into it, to go with them unto Tarshish from the presence of the LORD."}], [{"ref": "Jonah 1:17", "text": "Now the LORD had prepared a great fish to swallow up Jonah. And Jonah was in the belly of the fish three days and three nights."}], [{"ref": "Jonah 3:10", "text": "And God saw their works, that they turned from their evil way; and God repented of the evil, that he had said that he would do unto them; and he did it not."}, {"ref": "Jonah 4:1", "text": "But it displeased Jonah exceedingly, and he was very angry."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-isaiah','whoami',23,6,8,8,'Isaiah 6:8',2,'Who am I?','["I saw the Lord high and lifted up in the year King Uzziah died.", "A seraph touched my lips with a live coal.", "I answered: Here am I; send me.", "I prophesied of a child called Immanuel."]'::jsonb,'["Jeremiah", "Isaiah", "Micah", "Ezekiel"]'::jsonb,1,'Isaiah 6:8: "Here am I; send me."','Look in the Major Prophets.',null,null,'KJV',array['isaiah','Isaiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me.','[[{"ref": "Isaiah 6:1", "text": "In the year that king Uzziah died I saw also the Lord sitting upon a throne, high and lifted up, and his train filled the temple."}], [{"ref": "Isaiah 6:6-7", "text": "Then flew one of the seraphims unto me, having a live coal in his hand, which he had taken with the tongs from off the altar: And he laid it upon my mouth, and said, Lo, this hath touched thy lips; and thine iniquity is taken away, and thy sin purged."}], [{"ref": "Isaiah 6:8", "text": "Also I heard the voice of the Lord, saying, Whom shall I send, and who will go for us? Then said I, Here am I; send me."}], [{"ref": "Isaiah 7:14", "text": "Therefore the Lord himself shall give you a sign; Behold, a virgin shall conceive, and bear a son, and shall call his name Immanuel."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jeremiah','whoami',24,1,5,6,'Jeremiah 1:5-6',3,'Who am I?','["God said He knew me before He formed me in the belly.", "I protested that I was only a child.", "I was let down into a dungeon full of mire.", "Baruch wrote my words on a roll."]'::jsonb,'["Jeremiah", "Daniel", "Isaiah", "Ezekiel"]'::jsonb,0,'God told Jeremiah, "Before I formed thee in the belly I knew thee." Tradition calls him the weeping prophet.','Look in the Major Prophets.',null,null,'KJV',array['jeremiah','Jeremiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations. Then said I, Ah, Lord GOD! behold, I cannot speak: for I am a child.','[[{"ref": "Jeremiah 1:5", "text": "Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations."}], [{"ref": "Jeremiah 1:6", "text": "Then said I, Ah, Lord GOD! behold, I cannot speak: for I am a child."}], [{"ref": "Jeremiah 38:6", "text": "Then took they Jeremiah, and cast him into the dungeon of Malchiah the son of Hammelech, that was in the court of the prison: and they let down Jeremiah with cords. And in the dungeon there was no water, but mire: so Jeremiah sunk in the mire."}], [{"ref": "Jeremiah 36:4", "text": "Then Jeremiah called Baruch the son of Neriah: and Baruch wrote from the mouth of Jeremiah all the words of the LORD, which he had spoken unto him, upon a roll of a book."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-mary','whoami',42,1,26,27,'Luke 1:26-27',1,'Who am I?','["I lived in Nazareth of Galilee.", "The angel Gabriel was sent to me.", "I was espoused to Joseph.", "I gave birth to Jesus in Bethlehem."]'::jsonb,'["Elisabeth", "Martha", "Anna", "Mary"]'::jsonb,3,'Gabriel was sent to a virgin espoused to Joseph, and her name was Mary.','Look in Luke.',null,null,'KJV',array['mary','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary.','[[{"ref": "Luke 1:26-27", "text": "And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 1:26-27", "text": "And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth, To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 1:27", "text": "To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin’s name was Mary."}], [{"ref": "Luke 2:4-7", "text": "And Joseph also went up from Galilee, out of the city of Nazareth, into Judæa, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:) To be taxed with Mary his espoused wife, being great with child. And so it was, that, while they were there, the days were accomplished that she should be delivered. And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn."}, {"ref": "Luke 2:21", "text": "And when eight days were accomplished for the circumcising of the child, his name was called JESUS, which was so named of the angel before he was conceived in the womb."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-john_baptist','whoami',40,3,4,4,'Matthew 3:4',1,'Who am I?','["My father Zacharias was a priest.", "I wore raiment of camel''s hair.", "I ate locusts and wild honey.", "I baptized Jesus in the Jordan."]'::jsonb,'["Peter", "Andrew", "John the Baptist", "Elijah"]'::jsonb,2,'John had raiment of camel''s hair and his meat was locusts and wild honey.','Look in Matthew.',null,null,'KJV',array['john_baptist','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey.','[[{"ref": "Luke 1:5", "text": "There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}, {"ref": "Luke 1:13", "text": "But the angel said unto him, Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John."}], [{"ref": "Matthew 3:4", "text": "And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey."}], [{"ref": "Matthew 3:4", "text": "And the same John had his raiment of camel’s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey."}], [{"ref": "Mark 1:9", "text": "And it came to pass in those days, that Jesus came from Nazareth of Galilee, and was baptized of John in Jordan."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-peter','whoami',40,26,75,75,'Matthew 26:75',1,'Who am I?','["I was a fisherman, the brother of Andrew.", "Jesus called me to become a fisher of men.", "I walked on the water toward Jesus.", "I denied Jesus three times before the cock crew."]'::jsonb,'["Peter", "John", "Andrew", "Thomas"]'::jsonb,0,'Peter remembered Jesus'' words, "Before the cock crow, thou shalt deny me thrice."','Look in Matthew.',null,null,'KJV',array['peter','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Peter remembered the word of Jesus, which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly.','[[{"ref": "Matthew 4:18", "text": "And Jesus, walking by the sea of Galilee, saw two brethren, Simon called Peter, and Andrew his brother, casting a net into the sea: for they were fishers."}], [{"ref": "Matthew 4:19", "text": "And he saith unto them, Follow me, and I will make you fishers of men."}], [{"ref": "Matthew 14:29", "text": "And he said, Come. And when Peter was come down out of the ship, he walked on the water, to go to Jesus."}], [{"ref": "Matthew 26:75", "text": "And Peter remembered the word of Jesus, which said unto him, Before the cock crow, thou shalt deny me thrice. And he went out, and wept bitterly."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-thomas','whoami',43,20,28,28,'John 20:28',2,'Who am I?','["I was one of the twelve, called Didymus.", "I was absent when Jesus first appeared to the disciples.", "I wanted to see the print of the nails.", "I said: My Lord and my God."]'::jsonb,'["Thomas", "Philip", "Bartholomew", "Matthew"]'::jsonb,0,'Thomas answered and said unto him, "My Lord and my God."','Look in John.',null,null,'KJV',array['thomas','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Thomas answered and said unto him, My Lord and my God.','[[{"ref": "John 20:24", "text": "But Thomas, one of the twelve, called Didymus, was not with them when Jesus came."}], [{"ref": "John 20:19", "text": "Then the same day at evening, being the first day of the week, when the doors were shut where the disciples were assembled for fear of the Jews, came Jesus and stood in the midst, and saith unto them, Peace be unto you."}, {"ref": "John 20:24", "text": "But Thomas, one of the twelve, called Didymus, was not with them when Jesus came."}], [{"ref": "John 20:25", "text": "The other disciples therefore said unto him, We have seen the Lord. But he said unto them, Except I shall see in his hands the print of the nails, and put my finger into the print of the nails, and thrust my hand into his side, I will not believe."}], [{"ref": "John 20:28", "text": "And Thomas answered and said unto him, My Lord and my God."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-zacchaeus','whoami',42,19,2,4,'Luke 19:2-4',1,'Who am I?','["I was chief among the publicans.", "I was rich.", "I was little of stature.", "I climbed a sycomore tree to see Jesus."]'::jsonb,'["Zacchaeus", "Matthew", "Bartimaeus", "Nicodemus"]'::jsonb,0,'Zacchaeus climbed up into a sycomore tree to see Jesus.','Look in Luke.',null,null,'KJV',array['zacchaeus','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich. And he sought to see Jesus who he was; and could not for the press, because he was little of stature. And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way.','[[{"ref": "Luke 19:2", "text": "And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich."}], [{"ref": "Luke 19:2", "text": "And, behold, there was a man named Zacchæus, which was the chief among the publicans, and he was rich."}], [{"ref": "Luke 19:3", "text": "And he sought to see Jesus who he was; and could not for the press, because he was little of stature."}], [{"ref": "Luke 19:4", "text": "And he ran before, and climbed up into a sycomore tree to see him: for he was to pass that way."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-nicodemus','whoami',43,3,1,3,'John 3:1-3',2,'Who am I?','["I was a Pharisee and a ruler of the Jews.", "I came to Jesus by night.", "Jesus told me I must be born again.", "I brought myrrh and aloes for Jesus'' burial."]'::jsonb,'["Joseph of Arimathaea", "Gamaliel", "Zacchaeus", "Nicodemus"]'::jsonb,3,'Jesus told Nicodemus, "Except a man be born again, he cannot see the kingdom of God."','Look in John.',null,null,'KJV',array['nicodemus','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'There was a man of the Pharisees, named Nicodemus, a ruler of the Jews: The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him. Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God.','[[{"ref": "John 3:1", "text": "There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:"}], [{"ref": "John 3:2", "text": "The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him."}], [{"ref": "John 3:7", "text": "Marvel not that I said unto thee, Ye must be born again."}], [{"ref": "John 19:39", "text": "And there came also Nicodemus, which at the first came to Jesus by night, and brought a mixture of myrrh and aloes, about an hundred pound weight."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-lazarus','whoami',43,11,43,44,'John 11:43-44',1,'Who am I?','["I lived in Bethany.", "My sisters were Mary and Martha.", "Jesus wept near my grave.", "Jesus called me out of the tomb."]'::jsonb,'["Bartimaeus", "Simon", "Jairus", "Lazarus"]'::jsonb,3,'Jesus cried with a loud voice, "Lazarus, come forth."','Look in John.',null,null,'KJV',array['lazarus','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And when he thus had spoken, he cried with a loud voice, Lazarus, come forth. And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go.','[[{"ref": "John 11:1", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha."}], [{"ref": "John 11:1-2", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}], [{"ref": "John 11:34-35", "text": "And said, Where have ye laid him? They said unto him, Lord, come and see. Jesus wept."}, {"ref": "John 11:38", "text": "Jesus therefore again groaning in himself cometh to the grave. It was a cave, and a stone lay upon it."}], [{"ref": "John 11:43-44", "text": "And when he thus had spoken, he cried with a loud voice, Lazarus, come forth. And he that was dead came forth, bound hand and foot with graveclothes: and his face was bound about with a napkin. Jesus saith unto them, Loose him, and let him go."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-martha','whoami',42,10,38,41,'Luke 10:38-41',3,'Who am I?','["I lived in Bethany with my sister and brother.", "I was cumbered about much serving.", "Jesus said my sister had chosen the good part.", "I welcomed Jesus into my house."]'::jsonb,'["Martha", "Mary Magdalene", "Salome", "Joanna"]'::jsonb,0,'"Martha was cumbered about much serving."','Look in Luke.',null,null,'KJV',array['martha','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house. And she had a sister called Mary, which also sat at Jesus’ feet, and heard his word. But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me. And Jesus answered and said unto her, Martha, Martha, thou art careful and troubled about many things:','[[{"ref": "John 11:1-2", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}], [{"ref": "Luke 10:40", "text": "But Martha was cumbered about much serving, and came to him, and said, Lord, dost thou not care that my sister hath left me to serve alone? bid her therefore that she help me."}], [{"ref": "Luke 10:42", "text": "But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her."}], [{"ref": "Luke 10:38", "text": "Now it came to pass, as they went, that he entered into a certain village: and a certain woman named Martha received him into her house."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-paul','whoami',44,9,3,4,'Acts 9:3-4',1,'Who am I?','["I was born in Tarsus.", "I once persecuted the church.", "A light from heaven blinded me near Damascus.", "I wrote many letters to the churches."]'::jsonb,'["Barnabas", "Stephen", "Silas", "Paul"]'::jsonb,3,'Near Damascus a voice said, "Saul, Saul, why persecutest thou me?" He is later called Paul.','Look in Acts.',null,null,'KJV',array['paul','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?','[[{"ref": "Acts 22:3", "text": "I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day."}], [{"ref": "Galatians 1:13", "text": "For ye have heard of my conversation in time past in the Jews’ religion, how that beyond measure I persecuted the church of God, and wasted it:"}], [{"ref": "Acts 9:3-8", "text": "And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven: And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me? And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks. And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord said unto him, Arise, and go into the city, and it shall be told thee what thou must do. And the men which journeyed with him stood speechless, hearing a voice, but seeing no man. And Saul arose from the earth; and when his eyes were opened, he saw no man: but they led him …"}, {"ref": "Acts 22:11", "text": "And when I could not see for the glory of that light, being led by the hand of them that were with me, I came into Damascus."}], [{"ref": "2 Peter 3:15-16", "text": "And account that the longsuffering of our Lord is salvation; even as our beloved brother Paul also according to the wisdom given unto him hath written unto you; As also in all his epistles, speaking in them of these things; in which are some things hard to be understood, which they that are unlearned and unstable wrest, as they do also the other scriptures, unto their own destruction."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-stephen','whoami',44,7,58,59,'Acts 7:58-59',2,'Who am I?','["I was one of seven chosen to serve the church.", "I was full of faith and power.", "As I spoke I saw the heavens opened.", "I was stoned while a young man named Saul watched."]'::jsonb,'["Barnabas", "Stephen", "James", "Philip"]'::jsonb,1,'The witnesses laid their clothes at Saul''s feet, and they stoned Stephen.','Look in Acts.',null,null,'KJV',array['stephen','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul. And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit.','[[{"ref": "Acts 6:2-5", "text": "Then the twelve called the multitude of the disciples unto them, and said, It is not reason that we should leave the word of God, and serve tables. Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business. But we will give ourselves continually to prayer, and to the ministry of the word. And the saying pleased the whole multitude: and they chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas a proselyte of Antioch:"}], [{"ref": "Acts 6:8", "text": "And Stephen, full of faith and power, did great wonders and miracles among the people."}], [{"ref": "Acts 7:56", "text": "And said, Behold, I see the heavens opened, and the Son of man standing on the right hand of God."}], [{"ref": "Acts 7:58", "text": "And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-barnabas','whoami',44,4,36,37,'Acts 4:36-37',3,'Who am I?','["My name is interpreted ''the son of consolation''.", "I sold land and laid the money at the apostles'' feet.", "I brought Saul to the apostles in Jerusalem.", "I travelled with Paul on his first missionary journey."]'::jsonb,'["Timothy", "Barnabas", "Mark", "Silas"]'::jsonb,1,'Joses was surnamed Barnabas, "the son of consolation."','Look in Acts.',null,null,'KJV',array['barnabas','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus, Having land, sold it, and brought the money, and laid it at the apostles’ feet.','[[{"ref": "Acts 4:36", "text": "And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, and of the country of Cyprus,"}], [{"ref": "Acts 4:37", "text": "Having land, sold it, and brought the money, and laid it at the apostles’ feet."}], [{"ref": "Acts 9:26-27", "text": "And when Saul was come to Jerusalem, he assayed to join himself to the disciples: but they were all afraid of him, and believed not that he was a disciple. But Barnabas took him, and brought him to the apostles, and declared unto them how he had seen the Lord in the way, and that he had spoken to him, and how he had preached boldly at Damascus in the name of Jesus."}], [{"ref": "Acts 13:2-4", "text": "As they ministered to the Lord, and fasted, the Holy Ghost said, Separate me Barnabas and Saul for the work whereunto I have called them. And when they had fasted and prayed, and laid their hands on them, they sent them away. So they, being sent forth by the Holy Ghost, departed unto Seleucia; and from thence they sailed to Cyprus."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-lydia','whoami',44,16,14,15,'Acts 16:14-15',3,'Who am I?','["I was a seller of purple.", "I came from the city of Thyatira.", "I heard Paul speak by a riverside at Philippi.", "My household was baptized."]'::jsonb,'["Dorcas", "Priscilla", "Lydia", "Phebe"]'::jsonb,2,'Lydia, a seller of purple, of the city of Thyatira, heard Paul.','Look in Acts.',null,null,'KJV',array['lydia','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul. And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us.','[[{"ref": "Acts 16:14", "text": "And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:14", "text": "And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:12-14", "text": "And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days. And on the sabbath we went out of the city by a river side, where prayer was wont to be made; and we sat down, and spake unto the women which resorted thither. And a certain woman named Lydia, a seller of purple, of the city of Thyatira, which worshipped God, heard us: whose heart the Lord opened, that she attended unto the things which were spoken of Paul."}], [{"ref": "Acts 16:15", "text": "And when she was baptized, and her household, she besought us, saying, If ye have judged me to be faithful to the Lord, come into my house, and abide there. And she constrained us."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-timothy','whoami',55,1,2,5,'2 Timothy 1:2-5',3,'Who am I?','["My grandmother Lois and mother Eunice shared unfeigned faith.", "I was Paul''s young companion.", "Paul called me his dearly beloved son.", "Two New Testament letters are addressed to me."]'::jsonb,'["Silas", "Titus", "Timothy", "Luke"]'::jsonb,2,'Paul remembered the faith in Lois and Eunice, and in Timothy.','Look in Paul''s letters.',null,null,'KJV',array['timothy','2 Timothy']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord. I thank God, whom I serve from my forefathers with pure conscience, that without ceasing I have remembrance of thee in my prayers night and day; Greatly desiring to see thee, being mindful of thy tears, that I may be filled with joy; When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also.','[[{"ref": "2 Timothy 1:5", "text": "When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also."}], [{"ref": "Acts 16:1-3", "text": "Then came he to Derbe and Lystra: and, behold, a certain disciple was there, named Timotheus, the son of a certain woman, which was a Jewess, and believed; but his father was a Greek: Which was well reported of by the brethren that were at Lystra and Iconium. Him would Paul have to go forth with him; and took and circumcised him because of the Jews which were in those quarters: for they knew all that his father was a Greek."}, {"ref": "1 Timothy 4:12", "text": "Let no man despise thy youth; but be thou an example of the believers, in word, in conversation, in charity, in spirit, in faith, in purity."}], [{"ref": "2 Timothy 1:2", "text": "To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord."}], [{"ref": "1 Timothy 1:2", "text": "Unto Timothy, my own son in the faith: Grace, mercy, and peace, from God our Father and Jesus Christ our Lord."}, {"ref": "2 Timothy 1:2", "text": "To Timothy, my dearly beloved son: Grace, mercy, and peace, from God the Father and Christ Jesus our Lord."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-adam','whoami',1,2,19,20,'Genesis 2:19-20',1,'Who am I?','["I was formed of the dust of the ground.", "I gave names to the animals.", "I lived in the garden of Eden.", "My wife was Eve."]'::jsonb,'["Enoch", "Cain", "Seth", "Adam"]'::jsonb,3,'"Adam gave names to all cattle, and to the fowl of the air."','Look in Genesis.',null,null,'KJV',array['adam','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And out of the ground the LORD God formed every beast of the field, and every fowl of the air; and brought them unto Adam to see what he would call them: and whatsoever Adam called every living creature, that was the name thereof. And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him.','[[{"ref": "Genesis 2:7", "text": "And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul."}], [{"ref": "Genesis 2:20", "text": "And Adam gave names to all cattle, and to the fowl of the air, and to every beast of the field; but for Adam there was not found an help meet for him."}], [{"ref": "Genesis 2:15", "text": "And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it."}], [{"ref": "Genesis 3:20", "text": "And Adam called his wife’s name Eve; because she was the mother of all living."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-cain','whoami',1,4,9,9,'Genesis 4:9',2,'Who am I?','["I was a tiller of the ground.", "God did not respect my offering.", "I asked: Am I my brother''s keeper?", "God set a mark upon me."]'::jsonb,'["Abel", "Seth", "Cain", "Lamech"]'::jsonb,2,'Cain answered, "I know not: Am I my brother''s keeper?"','Look in Genesis.',null,null,'KJV',array['cain','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And the LORD said unto Cain, Where is Abel thy brother? And he said, I know not: Am I my brother’s keeper?','[[{"ref": "Genesis 4:2", "text": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}], [{"ref": "Genesis 4:5", "text": "But unto Cain and to his offering he had not respect. And Cain was very wroth, and his countenance fell."}], [{"ref": "Genesis 4:9", "text": "And the LORD said unto Cain, Where is Abel thy brother? And he said, I know not: Am I my brother’s keeper?"}], [{"ref": "Genesis 4:15", "text": "And the LORD said unto him, Therefore whosoever slayeth Cain, vengeance shall be taken on him sevenfold. And the LORD set a mark upon Cain, lest any finding him should kill him."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-methuselah','whoami',1,5,27,27,'Genesis 5:27',4,'Who am I?','["My father was Enoch.", "My son was Lamech.", "I was Noah''s grandfather.", "I lived nine hundred sixty and nine years."]'::jsonb,'["Methuselah", "Mahalaleel", "Jared", "Enoch"]'::jsonb,0,'"All the days of Methuselah were nine hundred sixty and nine years."','Look in Genesis.',null,null,'KJV',array['methuselah','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And all the days of Methuselah were nine hundred sixty and nine years: and he died.','[[{"ref": "Genesis 5:21", "text": "And Enoch lived sixty and five years, and begat Methuselah:"}], [{"ref": "Genesis 5:25", "text": "And Methuselah lived an hundred eighty and seven years, and begat Lamech:"}], [{"ref": "Genesis 5:25", "text": "And Methuselah lived an hundred eighty and seven years, and begat Lamech:"}, {"ref": "Genesis 5:28-29", "text": "And Lamech lived an hundred eighty and two years, and begat a son: And he called his name Noah, saying, This same shall comfort us concerning our work and toil of our hands, because of the ground which the LORD hath cursed."}], [{"ref": "Genesis 5:27", "text": "And all the days of Methuselah were nine hundred sixty and nine years: and he died."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-enoch','whoami',1,5,24,24,'Genesis 5:24',3,'Who am I?','["I walked with God.", "I was the father of Methuselah.", "I was not, for God took me.", "Hebrews says I was translated so I should not see death."]'::jsonb,'["Elijah", "Noah", "Enoch", "Seth"]'::jsonb,2,'"Enoch walked with God: and he was not; for God took him."','Look in Genesis.',null,null,'KJV',array['enoch','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Enoch walked with God: and he was not; for God took him.','[[{"ref": "Genesis 5:22", "text": "And Enoch walked with God after he begat Methuselah three hundred years, and begat sons and daughters:"}], [{"ref": "Genesis 5:21", "text": "And Enoch lived sixty and five years, and begat Methuselah:"}], [{"ref": "Genesis 5:24", "text": "And Enoch walked with God: and he was not; for God took him."}], [{"ref": "Hebrews 11:5", "text": "By faith Enoch was translated that he should not see death; and was not found, because God had translated him: for before his translation he had this testimony, that he pleased God."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-melchizedek','whoami',1,14,18,20,'Genesis 14:18-20',4,'Who am I?','["I was king of Salem.", "I was priest of the most high God.", "I brought forth bread and wine to Abram.", "Abram gave me tithes of all."]'::jsonb,'["Abimelech", "Melchizedek", "Aaron", "Jethro"]'::jsonb,1,'Melchizedek king of Salem brought forth bread and wine.','Look in Genesis.',null,null,'KJV',array['melchizedek','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God. And he blessed him, and said, Blessed be Abram of the most high God, possessor of heaven and earth: And blessed be the most high God, which hath delivered thine enemies into thy hand. And he gave him tithes of all.','[[{"ref": "Genesis 14:18", "text": "And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Genesis 14:18", "text": "And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Genesis 14:17-18", "text": "And the king of Sodom went out to meet him after his return from the slaughter of Chedorlaomer, and of the kings that were with him, at the valley of Shaveh, which is the king’s dale. And Melchizedek king of Salem brought forth bread and wine: and he was the priest of the most high God."}], [{"ref": "Hebrews 7:2", "text": "To whom also Abraham gave a tenth part of all; first being by interpretation King of righteousness, and after that also King of Salem, which is, King of peace;"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-hannah','whoami',9,1,13,20,'1 Samuel 1:13-20',2,'Who am I?','["My husband was Elkanah.", "I prayed silently at Shiloh, and Eli thought I was drunk.", "I vowed to give my son to the LORD.", "I named my son Samuel."]'::jsonb,'["Sarah", "Elisabeth", "Peninnah", "Hannah"]'::jsonb,3,'Hannah bore a son and called his name Samuel.','Look in 1 Samuel.',null,null,'KJV',array['hannah','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Now Hannah, she spake in her heart; only her lips moved, but her voice was not heard: therefore Eli thought she had been drunken. And Eli said unto her, How long wilt thou be drunken? put away thy wine from thee. And Hannah answered and said, No, my lord, I am a woman of a sorrowful spirit: I have drunk neither wine nor strong drink, but have poured out my soul before the LORD. Count not thine handmaid for a daughter of Belial: for out of the abundance of my complaint and grief have I spoken hitherto. Then Eli answered and said, Go in peace: and the God of Israel grant thee thy petition that thou hast asked of him. And she said, Let thine handmaid find grace in thy sight. So the woman went …','[[{"ref": "1 Samuel 1:1-2", "text": "Now there was a certain man of Ramathaim-zophim, of mount Ephraim, and his name was Elkanah, the son of Jeroham, the son of Elihu, the son of Tohu, the son of Zuph, an Ephrathite: And he had two wives; the name of the one was Hannah, and the name of the other Peninnah: and Peninnah had children, but Hannah had no children."}], [{"ref": "1 Samuel 1:9-13", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD. And she was in bitterness of soul, and prayed unto the LORD, and wept sore. And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head. And it came to pass, as she continued praying before the LORD, that Eli marked her mouth. Now Hannah, she spake in her heart; only her lips moved, but her voice was …"}], [{"ref": "1 Samuel 1:11", "text": "And she vowed a vow, and said, O LORD of hosts, if thou wilt indeed look on the affliction of thine handmaid, and remember me, and not forget thine handmaid, but wilt give unto thine handmaid a man child, then I will give him unto the LORD all the days of his life, and there shall no razor come upon his head."}], [{"ref": "1 Samuel 1:20", "text": "Wherefore it came to pass, when the time was come about after Hannah had conceived, that she bare a son, and called his name Samuel, saying, Because I have asked him of the LORD."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-job','whoami',18,1,21,21,'Job 1:21',1,'Who am I?','["I lived in the land of Uz.", "I was perfect and upright.", "I lost my children and possessions in a single day.", "I said: The LORD gave, and the LORD hath taken away."]'::jsonb,'["Bildad", "Job", "Elihu", "Eliphaz"]'::jsonb,1,'"The LORD gave, and the LORD hath taken away; blessed be the name of the LORD."','Look in the books of poetry and wisdom.',null,null,'KJV',array['job','Job']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And said, Naked came I out of my mother’s womb, and naked shall I return thither: the LORD gave, and the LORD hath taken away; blessed be the name of the LORD.','[[{"ref": "Job 1:1", "text": "There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."}], [{"ref": "Job 1:1", "text": "There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."}], [{"ref": "Job 1:13-19", "text": "And there was a day when his sons and his daughters were eating and drinking wine in their eldest brother’s house: And there came a messenger unto Job, and said, The oxen were plowing, and the asses feeding beside them: And the Sabeans fell upon them, and took them away; yea, they have slain the servants with the edge of the sword; and I only am escaped alone to tell thee. While he was yet speaking, there came also another, and said, The fire of God is fallen from heaven, and hath burned up the sheep, and the servants, and consumed them; and I only am escaped alone to tell thee. While he was yet speaking, there came also another, and said, The Chaldeans made out three bands, and fell upon …"}], [{"ref": "Job 1:21", "text": "And said, Naked came I out of my mother’s womb, and naked shall I return thither: the LORD gave, and the LORD hath taken away; blessed be the name of the LORD."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-naaman','whoami',12,5,14,14,'2 Kings 5:14',3,'Who am I?','["I was captain of the host of the king of Syria.", "I was a leper.", "A captive little maid from Israel told of a prophet.", "I dipped myself seven times in the Jordan."]'::jsonb,'["Ben-hadad", "Hazael", "Naaman", "Gehazi"]'::jsonb,2,'He dipped himself seven times in Jordan and his flesh came again.','Look in 2 Kings.',null,null,'KJV',array['naaman','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean.','[[{"ref": "2 Kings 5:1", "text": "Now Naaman, captain of the host of the king of Syria, was a great man with his master, and honourable, because by him the LORD had given deliverance unto Syria: he was also a mighty man in valour, but he was a leper."}], [{"ref": "2 Kings 5:1", "text": "Now Naaman, captain of the host of the king of Syria, was a great man with his master, and honourable, because by him the LORD had given deliverance unto Syria: he was also a mighty man in valour, but he was a leper."}], [{"ref": "2 Kings 5:2-3", "text": "And the Syrians had gone out by companies, and had brought away captive out of the land of Israel a little maid; and she waited on Naaman’s wife. And she said unto her mistress, Would God my lord were with the prophet that is in Samaria! for he would recover him of his leprosy."}], [{"ref": "2 Kings 5:14", "text": "Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-caleb','whoami',6,14,6,13,'Joshua 14:6-13',4,'Who am I?','["I was one of the twelve spies.", "I brought back a good report with Joshua.", "I was eighty-five years old when I asked for my inheritance.", "I asked for the mountain and received Hebron."]'::jsonb,'["Othniel", "Joshua", "Caleb", "Phinehas"]'::jsonb,2,'Joshua blessed Caleb and gave him Hebron for an inheritance.','Look in the books of history.',null,null,'KJV',array['caleb','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Then the children of Judah came unto Joshua in Gilgal: and Caleb the son of Jephunneh the Kenezite said unto him, Thou knowest the thing that the LORD said unto Moses the man of God concerning me and thee in Kadesh-barnea. Forty years old was I when Moses the servant of the LORD sent me from Kadesh-barnea to espy out the land; and I brought him word again as it was in mine heart. Nevertheless my brethren that went up with me made the heart of the people melt: but I wholly followed the LORD my God. And Moses sware on that day, saying, Surely the land whereon thy feet have trodden shall be thine inheritance, and thy children’s for ever, because thou hast wholly followed the LORD my God. And …','[[{"ref": "Numbers 13:6", "text": "Of the tribe of Judah, Caleb the son of Jephunneh."}], [{"ref": "Numbers 14:6-9", "text": "And Joshua the son of Nun, and Caleb the son of Jephunneh, which were of them that searched the land, rent their clothes: And they spake unto all the company of the children of Israel, saying, The land, which we passed through to search it, is an exceeding good land. If the LORD delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey. Only rebel not ye against the LORD, neither fear ye the people of the land; for they are bread for us: their defence is departed from them, and the LORD is with us: fear them not."}], [{"ref": "Joshua 14:10", "text": "And now, behold, the LORD hath kept me alive, as he said, these forty and five years, even since the LORD spake this word unto Moses, while the children of Israel wandered in the wilderness: and now, lo, I am this day fourscore and five years old."}], [{"ref": "Joshua 14:12-13", "text": "Now therefore give me this mountain, whereof the LORD spake in that day; for thou heardest in that day how the Anakims were there, and that the cities were great and fenced: if so be the LORD will be with me, then I shall be able to drive them out, as the LORD said. And Joshua blessed him, and gave unto Caleb the son of Jephunneh Hebron for an inheritance."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-matthew','whoami',40,9,9,9,'Matthew 9:9',2,'Who am I?','["I was a publican.", "I sat at the receipt of custom.", "Jesus said to me: Follow me.", "After calling me, Jesus sat at meat in the house with many publicans and sinners."]'::jsonb,'["Simon", "Judas", "Matthew", "Zacchaeus"]'::jsonb,2,'Jesus saw a man named Matthew sitting at the receipt of custom.','Look in the Gospels.',null,null,'KJV',array['matthew','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him.','[[{"ref": "Matthew 10:3", "text": "Philip, and Bartholomew; Thomas, and Matthew the publican; James the son of Alphaeus, and Lebbaeus, whose surname was Thaddaeus;"}], [{"ref": "Matthew 9:9", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him."}], [{"ref": "Matthew 9:9", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him."}], [{"ref": "Matthew 9:9-10", "text": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him. And it came to pass, as Jesus sat at meat in the house, behold, many publicans and sinners came and sat down with him and his disciples."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-judas','whoami',40,26,14,15,'Matthew 26:14-15',1,'Who am I?','["I was one of the twelve.", "I had the bag.", "I agreed to betray Jesus for thirty pieces of silver.", "I betrayed Jesus with a kiss."]'::jsonb,'["Peter", "Thomas", "Judas Iscariot", "Andrew"]'::jsonb,2,'Judas Iscariot covenanted with the chief priests for thirty pieces of silver.','Look in Matthew.',null,null,'KJV',array['judas','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Then one of the twelve, called Judas Iscariot, went unto the chief priests, And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver.','[[{"ref": "Matthew 26:14", "text": "Then one of the twelve, called Judas Iscariot, went unto the chief priests,"}], [{"ref": "John 12:4-6", "text": "Then saith one of his disciples, Judas Iscariot, Simon’s son, which should betray him, Why was not this ointment sold for three hundred pence, and given to the poor? This he said, not that he cared for the poor; but because he was a thief, and had the bag, and bare what was put therein."}], [{"ref": "Matthew 26:15", "text": "And said unto them, What will ye give me, and I will deliver him unto you? And they covenanted with him for thirty pieces of silver."}], [{"ref": "Matthew 26:48-49", "text": "Now he that betrayed him gave them a sign, saying, Whomsoever I shall kiss, that same is he: hold him fast. And forthwith he came to Jesus, and said, Hail, master; and kissed him."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-mary_magdalene','whoami',43,20,15,16,'John 20:15-16',2,'Who am I?','["Seven devils had gone out of me.", "I stood by the cross.", "I came to the tomb while it was yet dark.", "At first I supposed the risen Jesus was the gardener."]'::jsonb,'["Martha", "Mary the mother of James", "Mary Magdalene", "Salome"]'::jsonb,2,'She, supposing him to be the gardener... Jesus saith unto her, Mary.','Look in John.',null,null,'KJV',array['mary_magdalene','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'Jesus saith unto her, Woman, why weepest thou? whom seekest thou? She, supposing him to be the gardener, saith unto him, Sir, if thou have borne him hence, tell me where thou hast laid him, and I will take him away. Jesus saith unto her, Mary. She turned herself, and saith unto him, Rabboni; which is to say, Master.','[[{"ref": "Luke 8:2", "text": "And certain women, which had been healed of evil spirits and infirmities, Mary called Magdalene, out of whom went seven devils,"}], [{"ref": "John 19:25", "text": "Now there stood by the cross of Jesus his mother, and his mother’s sister, Mary the wife of Cleophas, and Mary Magdalene."}], [{"ref": "John 20:1", "text": "The first day of the week cometh Mary Magdalene early, when it was yet dark, unto the sepulchre, and seeth the stone taken away from the sepulchre."}], [{"ref": "John 20:15", "text": "Jesus saith unto her, Woman, why weepest thou? whom seekest thou? She, supposing him to be the gardener, saith unto him, Sir, if thou have borne him hence, tell me where thou hast laid him, and I will take him away."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-john_apostle','whoami',66,1,9,9,'Revelation 1:9',2,'Who am I?','["I was a son of Zebedee.", "Jesus surnamed my brother and me Boanerges.", "Tradition identifies me as the disciple whom Jesus loved.", "I was on the isle of Patmos for the word of God."]'::jsonb,'["Andrew", "John", "Philip", "James"]'::jsonb,1,'"I John... was in the isle that is called Patmos." Identifying the Revelation author with the apostle is traditional.','Look in Revelation.',null,null,'KJV',array['john_apostle','Revelation']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ.','[[{"ref": "Matthew 4:21", "text": "And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them."}], [{"ref": "Mark 3:17", "text": "And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder:"}], [{"ref": "John 21:20", "text": "Then Peter, turning about, seeth the disciple whom Jesus loved following; which also leaned on his breast at supper, and said, Lord, which is he that betrayeth thee?"}], [{"ref": "Revelation 1:9", "text": "I John, who also am your brother, and companion in tribulation, and in the kingdom and patience of Jesus Christ, was in the isle that is called Patmos, for the word of God, and for the testimony of Jesus Christ."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-miriam','whoami',2,15,20,20,'Exodus 15:20',2,'Who am I?','["I watched over my baby brother at the river.", "I am called a prophetess.", "I led the women with a timbrel after the Red Sea crossing.", "I was briefly struck with leprosy."]'::jsonb,'["Jochebed", "Zipporah", "Deborah", "Miriam"]'::jsonb,3,'"Miriam the prophetess, the sister of Aaron, took a timbrel."','Look in Exodus.',null,null,'KJV',array['miriam','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances.','[[{"ref": "Exodus 2:3-4", "text": "And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink. And his sister stood afar off, to wit what would be done to him."}, {"ref": "Numbers 26:59", "text": "And the name of Amram’s wife was Jochebed, the daughter of Levi, whom her mother bare to Levi in Egypt: and she bare unto Amram Aaron and Moses, and Miriam their sister."}], [{"ref": "Exodus 15:20", "text": "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."}], [{"ref": "Exodus 15:20", "text": "And Miriam the prophetess, the sister of Aaron, took a timbrel in her hand; and all the women went out after her with timbrels and with dances."}], [{"ref": "Numbers 12:10", "text": "And the cloud departed from off the tabernacle; and, behold, Miriam became leprous, white as snow: and Aaron looked upon Miriam, and, behold, she was leprous."}, {"ref": "Numbers 12:14-15", "text": "And the LORD said unto Moses, If her father had but spit in her face, should she not be ashamed seven days? let her be shut out from the camp seven days, and after that let her be received in again. And Miriam was shut out from the camp seven days: and the people journeyed not till Miriam was brought in again."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-boaz','whoami',8,4,13,13,'Ruth 4:13',2,'Who am I?','["I was a mighty man of wealth in Bethlehem.", "I let a Moabite woman glean in my fields.", "I redeemed the inheritance of Elimelech.", "I married Ruth."]'::jsonb,'["Jesse", "Elimelech", "Obed", "Boaz"]'::jsonb,3,'"So Boaz took Ruth, and she was his wife."','Look in Ruth.',null,null,'KJV',array['boaz','Ruth']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'So Boaz took Ruth, and she was his wife: and when he went in unto her, the LORD gave her conception, and she bare a son.','[[{"ref": "Ruth 2:1", "text": "And Naomi had a kinsman of her husband’s, a mighty man of wealth, of the family of Elimelech; and his name was Boaz."}, {"ref": "Ruth 2:4", "text": "And, behold, Boaz came from Beth-lehem, and said unto the reapers, The LORD be with you. And they answered him, The LORD bless thee."}], [{"ref": "Ruth 2:6", "text": "And the servant that was set over the reapers answered and said, It is the Moabitish damsel that came back with Naomi out of the country of Moab:"}, {"ref": "Ruth 2:8", "text": "Then said Boaz unto Ruth, Hearest thou not, my daughter? Go not to glean in another field, neither go from hence, but abide here fast by my maidens:"}], [{"ref": "Ruth 4:9-10", "text": "And Boaz said unto the elders, and unto all the people, Ye are witnesses this day, that I have bought all that was Elimelech’s, and all that was Chilion’s and Mahlon’s, of the hand of Naomi. Moreover Ruth the Moabitess, the wife of Mahlon, have I purchased to be my wife, to raise up the name of the dead upon his inheritance, that the name of the dead be not cut off from among his brethren, and from the gate of his place: ye are witnesses this day."}], [{"ref": "Ruth 4:13", "text": "So Boaz took Ruth, and she was his wife: and when he went in unto her, the LORD gave her conception, and she bare a son."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-eve','whoami',1,3,20,20,'Genesis 3:20',1,'Who am I?','["I was the first woman.", "I was made from a rib taken from the man.", "The serpent spoke to me in the garden.", "I am called the mother of all living."]'::jsonb,'["Rachel", "Hannah", "Eve", "Sarah"]'::jsonb,2,'"Adam called his wife''s name Eve; because she was the mother of all living."','Look in Genesis.',null,null,'KJV',array['eve','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Adam called his wife’s name Eve; because she was the mother of all living.','[[{"ref": "Genesis 2:22", "text": "And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man."}], [{"ref": "Genesis 2:22", "text": "And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man."}], [{"ref": "Genesis 3:1", "text": "Now the serpent was more subtil than any beast of the field which the LORD God had made. And he said unto the woman, Yea, hath God said, Ye shall not eat of every tree of the garden?"}], [{"ref": "Genesis 3:20", "text": "And Adam called his wife’s name Eve; because she was the mother of all living."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-isaac','whoami',1,22,9,9,'Genesis 22:9',1,'Who am I?','["My mother laughed when my birth was promised.", "My father was a hundred years old when I was born.", "I was laid on an altar in the land of Moriah.", "My sons were Esau and Jacob."]'::jsonb,'["Joseph", "Ishmael", "Isaac", "Jacob"]'::jsonb,2,'Abraham bound Isaac his son and laid him on the altar upon the wood.','Look in Genesis.',null,null,'KJV',array['isaac','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And they came to the place which God had told him of; and Abraham built an altar there, and laid the wood in order, and bound Isaac his son, and laid him on the altar upon the wood.','[[{"ref": "Genesis 18:12", "text": "Therefore Sarah laughed within herself, saying, After I am waxed old shall I have pleasure, my lord being old also?"}], [{"ref": "Genesis 21:5", "text": "And Abraham was an hundred years old, when his son Isaac was born unto him."}], [{"ref": "Genesis 22:2", "text": "And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."}, {"ref": "Genesis 22:9", "text": "And they came to the place which God had told him of; and Abraham built an altar there, and laid the wood in order, and bound Isaac his son, and laid him on the altar upon the wood."}], [{"ref": "Genesis 25:25-26", "text": "And the first came out red, all over like an hairy garment; and they called his name Esau. And after that came his brother out, and his hand took hold on Esau’s heel; and his name was called Jacob: and Isaac was threescore years old when she bare them."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-rebekah','whoami',1,24,67,67,'Genesis 24:67',2,'Who am I?','["I drew water for a stranger''s camels at a well.", "I was the sister of Laban.", "I married Isaac.", "I helped my son Jacob receive his father''s blessing."]'::jsonb,'["Rebekah", "Rachel", "Leah", "Sarah"]'::jsonb,0,'Isaac brought Rebekah into his mother Sarah''s tent, and she became his wife.','Look in Genesis.',null,null,'KJV',array['rebekah','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Isaac brought her into his mother Sarah’s tent, and took Rebekah, and she became his wife; and he loved her: and Isaac was comforted after his mother’s death.','[[{"ref": "Genesis 24:19-20", "text": "And when she had done giving him drink, she said, I will draw water for thy camels also, until they have done drinking. And she hasted, and emptied her pitcher into the trough, and ran again unto the well to draw water, and drew for all his camels."}], [{"ref": "Genesis 24:29", "text": "And Rebekah had a brother, and his name was Laban: and Laban ran out unto the man, unto the well."}], [{"ref": "Genesis 24:67", "text": "And Isaac brought her into his mother Sarah’s tent, and took Rebekah, and she became his wife; and he loved her: and Isaac was comforted after his mother’s death."}], [{"ref": "Genesis 27:6-17", "text": "And Rebekah spake unto Jacob her son, saying, Behold, I heard thy father speak unto Esau thy brother, saying, Bring me venison, and make me savoury meat, that I may eat, and bless thee before the LORD before my death. Now therefore, my son, obey my voice according to that which I command thee. Go now to the flock, and fetch me from thence two good kids of the goats; and I will make them savoury meat for thy father, such as he loveth: And thou shalt bring it to thy father, that he may eat, and that he may bless thee before his death. And Jacob said to Rebekah his mother, Behold, Esau my brother is a hairy man, and I am a smooth man: …"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-rachel','whoami',1,29,20,20,'Genesis 29:20',2,'Who am I?','["My father was Laban.", "Jacob served seven years for me, and they seemed but a few days.", "I was the mother of Joseph and Benjamin.", "I died on the way to Bethlehem."]'::jsonb,'["Rachel", "Bilhah", "Rebekah", "Leah"]'::jsonb,0,'"Jacob served seven years for Rachel; and they seemed unto him but a few days."','Look in Genesis.',null,null,'KJV',array['rachel','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Jacob served seven years for Rachel; and they seemed unto him but a few days, for the love he had to her.','[[{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}], [{"ref": "Genesis 29:20", "text": "And Jacob served seven years for Rachel; and they seemed unto him but a few days, for the love he had to her."}], [{"ref": "Genesis 35:24", "text": "The sons of Rachel; Joseph, and Benjamin:"}], [{"ref": "Genesis 35:19", "text": "And Rachel died, and was buried in the way to Ephrath, which is Beth-lehem."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-lot','whoami',1,19,26,26,'Genesis 19:26',2,'Who am I?','["I was Abram''s nephew.", "I chose all the plain of Jordan.", "Two angels came to my house in Sodom.", "My wife looked back and became a pillar of salt."]'::jsonb,'["Terah", "Lot", "Laban", "Nahor"]'::jsonb,1,'Lot''s wife looked back from behind him, and she became a pillar of salt.','Look in Genesis.',null,null,'KJV',array['lot','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'But his wife looked back from behind him, and she became a pillar of salt.','[[{"ref": "Genesis 12:5", "text": "And Abram took Sarai his wife, and Lot his brother’s son, and all their substance that they had gathered, and the souls that they had gotten in Haran; and they went forth to go into the land of Canaan; and into the land of Canaan they came."}], [{"ref": "Genesis 13:11", "text": "Then Lot chose him all the plain of Jordan; and Lot journeyed east: and they separated themselves the one from the other."}], [{"ref": "Genesis 19:1-3", "text": "And there came two angels to Sodom at even; and Lot sat in the gate of Sodom: and Lot seeing them rose up to meet them; and he bowed himself with his face toward the ground; And he said, Behold now, my lords, turn in, I pray you, into your servant’s house, and tarry all night, and wash your feet, and ye shall rise up early, and go on your ways. And they said, Nay; but we will abide in the street all night. And he pressed upon them greatly; and they turned in unto him, and entered into his house; and he made them a feast, and did bake unleavened bread, and they did eat."}], [{"ref": "Genesis 19:26", "text": "But his wife looked back from behind him, and she became a pillar of salt."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-aaron','whoami',4,17,8,8,'Numbers 17:8',1,'Who am I?','["I was a Levite and the brother of Moses.", "I spoke to Pharaoh on Moses'' behalf.", "I made a golden calf when the people asked.", "My rod budded and yielded almonds."]'::jsonb,'["Joshua", "Eleazar", "Moses", "Aaron"]'::jsonb,3,'The rod of Aaron for the house of Levi budded, bloomed blossoms and yielded almonds.','Look in Numbers.',null,null,'KJV',array['aaron','Numbers']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it came to pass, that on the morrow Moses went into the tabernacle of witness; and, behold, the rod of Aaron for the house of Levi was budded, and brought forth buds, and bloomed blossoms, and yielded almonds.','[[{"ref": "Exodus 4:14", "text": "And the anger of the LORD was kindled against Moses, and he said, Is not Aaron the Levite thy brother? I know that he can speak well. And also, behold, he cometh forth to meet thee: and when he seeth thee, he will be glad in his heart."}], [{"ref": "Exodus 7:2", "text": "Thou shalt speak all that I command thee: and Aaron thy brother shall speak unto Pharaoh, that he send the children of Israel out of his land."}], [{"ref": "Exodus 32:1-4", "text": "And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for as for this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him. And Aaron said unto them, Break off the golden earrings, which are in the ears of your wives, of your sons, and of your daughters, and bring them unto me. And all the people brake off the golden earrings which were in their ears, and brought them unto Aaron. And he received them at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These be thy …"}], [{"ref": "Numbers 17:8", "text": "And it came to pass, that on the morrow Moses went into the tabernacle of witness; and, behold, the rod of Aaron for the house of Levi was budded, and brought forth buds, and bloomed blossoms, and yielded almonds."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-balaam','whoami',4,22,28,28,'Numbers 22:28',3,'Who am I?','["I am called a soothsayer.", "Balak, king of Moab, sent for me to curse Israel.", "An angel with a drawn sword stood in my way.", "My ass spoke to me."]'::jsonb,'["Balaam", "Jethro", "Balak", "Korah"]'::jsonb,0,'The LORD opened the mouth of the ass, and she said unto Balaam, "What have I done unto thee?"','Look in Numbers.',null,null,'KJV',array['balaam','Numbers']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?','[[{"ref": "Joshua 13:22", "text": "Balaam also the son of Beor, the soothsayer, did the children of Israel slay with the sword among them that were slain by them."}], [{"ref": "Numbers 22:4-6", "text": "And Moab said unto the elders of Midian, Now shall this company lick up all that are round about us, as the ox licketh up the grass of the field. And Balak the son of Zippor was king of the Moabites at that time. He sent messengers therefore unto Balaam the son of Beor to Pethor, which is by the river of the land of the children of his people, to call him, saying, Behold, there is a people come out from Egypt: behold, they cover the face of the earth, and they abide over against me: Come now therefore, I pray thee, curse me this people; for they are too mighty for me: peradventure I shall prevail, that we may smite them, and that I may drive them out of the land: for I wot that he whom thou …"}], [{"ref": "Numbers 22:31", "text": "Then the LORD opened the eyes of Balaam, and he saw the angel of the LORD standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face."}], [{"ref": "Numbers 22:28", "text": "And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jethro','whoami',2,3,1,1,'Exodus 3:1',3,'Who am I?','["I was a priest of Midian.", "I was Moses'' father-in-law.", "Moses kept my flock near Horeb.", "I advised Moses to appoint rulers to judge the people."]'::jsonb,'["Balak", "Laban", "Aaron", "Jethro"]'::jsonb,3,'Moses kept the flock of Jethro his father in law, the priest of Midian.','Look in Exodus.',null,null,'KJV',array['jethro','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb.','[[{"ref": "Exodus 3:1", "text": "Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb."}], [{"ref": "Exodus 18:1", "text": "When Jethro, the priest of Midian, Moses’ father in law, heard of all that God had done for Moses, and for Israel his people, and that the LORD had brought Israel out of Egypt;"}], [{"ref": "Exodus 3:1", "text": "Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, even to Horeb."}], [{"ref": "Exodus 18:17-22", "text": "And Moses’ father in law said unto him, The thing that thou doest is not good. Thou wilt surely wear away, both thou, and this people that is with thee: for this thing is too heavy for thee; thou art not able to perform it thyself alone. Hearken now unto my voice, I will give thee counsel, and God shall be with thee: Be thou for the people to God-ward, that thou mayest bring the causes unto God: And thou shalt teach them ordinances and laws, and shalt shew them the way wherein they must walk, and the work that they must do. Moreover thou shalt provide out of all the people able men, such as fear God, men of truth, hating covetousness; and place such over them, to be rulers of thousands, and …"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-eli','whoami',9,4,18,18,'1 Samuel 4:18',2,'Who am I?','["I was a priest at Shiloh.", "I thought Hannah was drunken as she prayed.", "My sons Hophni and Phinehas were wicked.", "I fell backward and died when I heard the ark was taken."]'::jsonb,'["Ahimelech", "Samuel", "Eli", "Zadok"]'::jsonb,2,'When the ark of God was mentioned, Eli fell from off the seat backward, and he died.','Look in the books of history.',null,null,'KJV',array['eli','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it came to pass, when he made mention of the ark of God, that he fell from off the seat backward by the side of the gate, and his neck brake, and he died: for he was an old man, and heavy. And he had judged Israel forty years.','[[{"ref": "1 Samuel 1:9", "text": "So Hannah rose up after they had eaten in Shiloh, and after they had drunk. Now Eli the priest sat upon a seat by a post of the temple of the LORD."}], [{"ref": "1 Samuel 1:13-14", "text": "Now Hannah, she spake in her heart; only her lips moved, but her voice was not heard: therefore Eli thought she had been drunken. And Eli said unto her, How long wilt thou be drunken? put away thy wine from thee."}], [{"ref": "1 Samuel 1:3", "text": "And this man went up out of his city yearly to worship and to sacrifice unto the LORD of hosts in Shiloh. And the two sons of Eli, Hophni and Phinehas, the priests of the LORD, were there."}, {"ref": "1 Samuel 2:12", "text": "Now the sons of Eli were sons of Belial; they knew not the LORD."}], [{"ref": "1 Samuel 4:17-18", "text": "And the messenger answered and said, Israel is fled before the Philistines, and there hath been also a great slaughter among the people, and thy two sons also, Hophni and Phinehas, are dead, and the ark of God is taken. And it came to pass, when he made mention of the ark of God, that he fell from off the seat backward by the side of the gate, and his neck brake, and he died: for he was an old man, and heavy. And he had judged Israel forty years."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jonathan','whoami',9,18,1,1,'1 Samuel 18:1',2,'Who am I?','["I was the son of King Saul.", "I climbed up to a Philistine garrison with my armourbearer.", "My soul was knit with the soul of David.", "I warned David by shooting arrows."]'::jsonb,'["Jonathan", "Absalom", "Ishbosheth", "Abner"]'::jsonb,0,'The soul of Jonathan was knit with the soul of David.','Look in 1 Samuel.',null,null,'KJV',array['jonathan','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it came to pass, when he had made an end of speaking unto Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul.','[[{"ref": "1 Samuel 14:1", "text": "Now it came to pass upon a day, that Jonathan the son of Saul said unto the young man that bare his armour, Come, and let us go over to the Philistines’ garrison, that is on the other side. But he told not his father."}], [{"ref": "1 Samuel 14:13", "text": "And Jonathan climbed up upon his hands and upon his feet, and his armourbearer after him: and they fell before Jonathan; and his armourbearer slew after him."}], [{"ref": "1 Samuel 18:1", "text": "And it came to pass, when he had made an end of speaking unto Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul."}], [{"ref": "1 Samuel 20:20-22", "text": "And I will shoot three arrows on the side thereof, as though I shot at a mark. And, behold, I will send a lad, saying, Go, find out the arrows. If I expressly say unto the lad, Behold, the arrows are on this side of thee, take them; then come thou: for there is peace to thee, and no hurt; as the LORD liveth. But if I say thus unto the young man, Behold, the arrows are beyond thee; go thy way: for the LORD hath sent thee away."}, {"ref": "1 Samuel 20:36-37", "text": "And he said unto his lad, Run, find out now the arrows which I shoot. And as the lad ran, he shot an arrow beyond him. And when the lad was come to the place of the arrow which Jonathan had shot, Jonathan cried after the lad, and said, Is not the arrow beyond thee?"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-goliath','whoami',9,17,4,4,'1 Samuel 17:4',1,'Who am I?','["I was a champion of the Philistines.", "I came from Gath.", "My height was six cubits and a span.", "A shepherd boy struck me down with a sling and a stone."]'::jsonb,'["Sisera", "Og", "Achish", "Goliath"]'::jsonb,3,'Goliath of Gath stood six cubits and a span.','Look in 1 Samuel.',null,null,'KJV',array['goliath','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span.','[[{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:4", "text": "And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."}], [{"ref": "1 Samuel 17:15", "text": "But David went and returned from Saul to feed his father’s sheep at Beth-lehem."}, {"ref": "1 Samuel 17:49-50", "text": "And David put his hand in his bag, and took thence a stone, and slang it, and smote the Philistine in his forehead, that the stone sunk into his forehead; and he fell upon his face to the earth. So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but there was no sword in the hand of David."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-bathsheba','whoami',10,11,3,3,'2 Samuel 11:3',3,'Who am I?','["I was the wife of Uriah the Hittite.", "King David saw me washing as he walked on his roof.", "I became the mother of Solomon.", "My son King Solomon set a seat for me at his right hand."]'::jsonb,'["Michal", "Tamar", "Bathsheba", "Abigail"]'::jsonb,2,'David was told she was the daughter of Eliam, the wife of Uriah the Hittite.','Look in 2 Samuel.',null,null,'KJV',array['bathsheba','2 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And David sent and enquired after the woman. And one said, Is not this Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite?','[[{"ref": "2 Samuel 11:3", "text": "And David sent and enquired after the woman. And one said, Is not this Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite?"}], [{"ref": "2 Samuel 11:2", "text": "And it came to pass in an eveningtide, that David arose from off his bed, and walked upon the roof of the king’s house: and from the roof he saw a woman washing herself; and the woman was very beautiful to look upon."}], [{"ref": "2 Samuel 12:24", "text": "And David comforted Bath-sheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him."}], [{"ref": "1 Kings 2:19", "text": "Bath-sheba therefore went unto king Solomon, to speak unto him for Adonijah. And the king rose up to meet her, and bowed himself unto her, and sat down on his throne, and caused a seat to be set for the king’s mother; and she sat on his right hand."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-nathan','whoami',10,12,7,7,'2 Samuel 12:7',3,'Who am I?','["I was a prophet in David''s court.", "I told David his son would build God''s house.", "I told David a parable about a poor man''s ewe lamb.", "I said to David, Thou art the man."]'::jsonb,'["Samuel", "Gad", "Ahijah", "Nathan"]'::jsonb,3,'Nathan said to David, "Thou art the man."','Look in the books of history.',null,null,'KJV',array['nathan','2 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;','[[{"ref": "2 Samuel 7:2", "text": "That the king said unto Nathan the prophet, See now, I dwell in an house of cedar, but the ark of God dwelleth within curtains."}], [{"ref": "2 Samuel 7:4-5", "text": "And it came to pass that night, that the word of the LORD came unto Nathan, saying, Go and tell my servant David, Thus saith the LORD, Shalt thou build me an house for me to dwell in?"}, {"ref": "2 Samuel 7:12-13", "text": "And when thy days be fulfilled, and thou shalt sleep with thy fathers, I will set up thy seed after thee, which shall proceed out of thy bowels, and I will establish his kingdom. He shall build an house for my name, and I will stablish the throne of his kingdom for ever."}], [{"ref": "2 Samuel 12:1-4", "text": "And the LORD sent Nathan unto David. And he came unto him, and said unto him, There were two men in one city; the one rich, and the other poor. The rich man had exceeding many flocks and herds: But the poor man had nothing, save one little ewe lamb, which he had bought and nourished up: and it grew up together with him, and with his children; it did eat of his own meat, and drank of his own cup, and lay in his bosom, and was unto him as a daughter. And there came a traveller unto the rich man, and he spared to take of his own flock and of his own herd, to dress for the wayfaring man that was come unto him; but took the poor man’s lamb, and dressed it for the man that was come to him."}], [{"ref": "2 Samuel 12:7", "text": "And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-absalom','whoami',10,18,9,9,'2 Samuel 18:9',3,'Who am I?','["I was a son of King David.", "I stole the hearts of the men of Israel.", "I led a rebellion against my father.", "My head caught in an oak as my mule went on."]'::jsonb,'["Amnon", "Absalom", "Adonijah", "Solomon"]'::jsonb,1,'Absalom''s mule went under the thick boughs of a great oak, and his head caught hold of the oak.','Look in 2 Samuel.',null,null,'KJV',array['absalom','2 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away.','[[{"ref": "2 Samuel 3:3", "text": "And his second, Chileab, of Abigail the wife of Nabal the Carmelite; and the third, Absalom the son of Maacah the daughter of Talmai king of Geshur;"}], [{"ref": "2 Samuel 15:6", "text": "And on this manner did Absalom to all Israel that came to the king for judgment: so Absalom stole the hearts of the men of Israel."}], [{"ref": "2 Samuel 15:10-12", "text": "But Absalom sent spies throughout all the tribes of Israel, saying, As soon as ye hear the sound of the trumpet, then ye shall say, Absalom reigneth in Hebron. And with Absalom went two hundred men out of Jerusalem, that were called; and they went in their simplicity, and they knew not any thing. And Absalom sent for Ahithophel the Gilonite, David’s counsellor, from his city, even from Giloh, while he offered sacrifices. And the conspiracy was strong; for the people increased continually with Absalom."}], [{"ref": "2 Samuel 18:9", "text": "And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jezebel','whoami',11,19,2,2,'1 Kings 19:2',2,'Who am I?','["I was the daughter of the king of the Zidonians.", "I was the wife of King Ahab.", "I threatened Elijah''s life after Mount Carmel.", "I arranged Naboth''s death to take his vineyard."]'::jsonb,'["Delilah", "Jezebel", "Vashti", "Athaliah"]'::jsonb,1,'Jezebel sent a messenger unto Elijah, threatening his life.','Look in 1 Kings.',null,null,'KJV',array['jezebel','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then Jezebel sent a messenger unto Elijah, saying, So let the gods do to me, and more also, if I make not thy life as the life of one of them by to morrow about this time.','[[{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 19:1-2", "text": "And Ahab told Jezebel all that Elijah had done, and withal how he had slain all the prophets with the sword. Then Jezebel sent a messenger unto Elijah, saying, So let the gods do to me, and more also, if I make not thy life as the life of one of them by to morrow about this time."}], [{"ref": "1 Kings 21:7-15", "text": "And Jezebel his wife said unto him, Dost thou now govern the kingdom of Israel? arise, and eat bread, and let thine heart be merry: I will give thee the vineyard of Naboth the Jezreelite. So she wrote letters in Ahab’s name, and sealed them with his seal, and sent the letters unto the elders and to the nobles that were in his city, dwelling with Naboth. And she wrote in the letters, saying, Proclaim a fast, and set Naboth on high among the people: And set two men, sons of Belial, before him, to bear witness against him, saying, Thou didst blaspheme God and the king. And then carry him out, and stone him, that he may die. And the men of his city, even the elders and the nobles who were the …"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-ahab','whoami',11,21,2,2,'1 Kings 21:2',2,'Who am I?','["I was a king of Israel.", "I married Jezebel.", "I asked Elijah, Art thou he that troubleth Israel?", "I wanted Naboth''s vineyard for a garden of herbs."]'::jsonb,'["Ahab", "Jeroboam", "Omri", "Jehu"]'::jsonb,0,'Ahab said to Naboth, "Give me thy vineyard."','Look in 1 Kings.',null,null,'KJV',array['ahab','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Ahab spake unto Naboth, saying, Give me thy vineyard, that I may have it for a garden of herbs, because it is near unto my house: and I will give thee for it a better vineyard than it; or, if it seem good to thee, I will give thee the worth of it in money.','[[{"ref": "1 Kings 16:29", "text": "And in the thirty and eighth year of Asa king of Judah began Ahab the son of Omri to reign over Israel: and Ahab the son of Omri reigned over Israel in Samaria twenty and two years."}], [{"ref": "1 Kings 16:31", "text": "And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him."}], [{"ref": "1 Kings 18:17", "text": "And it came to pass, when Ahab saw Elijah, that Ahab said unto him, Art thou he that troubleth Israel?"}], [{"ref": "1 Kings 21:2", "text": "And Ahab spake unto Naboth, saying, Give me thy vineyard, that I may have it for a garden of herbs, because it is near unto my house: and I will give thee for it a better vineyard than it; or, if it seem good to thee, I will give thee the worth of it in money."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-hezekiah','whoami',23,38,5,5,'Isaiah 38:5',3,'Who am I?','["I was a king of Judah.", "I broke in pieces the brasen serpent that Moses had made.", "Isaiah told me to set my house in order.", "God added fifteen years to my life."]'::jsonb,'["Hezekiah", "Josiah", "Manasseh", "Uzziah"]'::jsonb,0,'God said through Isaiah, "I will add unto thy days fifteen years."','Look in Isaiah.',null,null,'KJV',array['hezekiah','Isaiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Go, and say to Hezekiah, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years.','[[{"ref": "2 Kings 18:1", "text": "Now it came to pass in the third year of Hoshea son of Elah king of Israel, that Hezekiah the son of Ahaz king of Judah began to reign."}], [{"ref": "2 Kings 18:4", "text": "He removed the high places, and brake the images, and cut down the groves, and brake in pieces the brasen serpent that Moses had made: for unto those days the children of Israel did burn incense to it: and he called it Nehushtan."}], [{"ref": "Isaiah 38:1", "text": "In those days was Hezekiah sick unto death. And Isaiah the prophet the son of Amoz came unto him, and said unto him, Thus saith the LORD, Set thine house in order: for thou shalt die, and not live."}], [{"ref": "Isaiah 38:5", "text": "Go, and say to Hezekiah, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will add unto thy days fifteen years."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-josiah','whoami',12,22,1,1,'2 Kings 22:1',4,'Who am I?','["I became king of Judah at eight years old.", "The book of the law was found in the temple in my reign.", "I rent my clothes when it was read to me.", "I kept a great passover."]'::jsonb,'["Joash", "Josiah", "Hezekiah", "Jehoiakim"]'::jsonb,1,'"Josiah was eight years old when he began to reign."','Look in 2 Kings.',null,null,'KJV',array['josiah','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his mother’s name was Jedidah, the daughter of Adaiah of Boscath.','[[{"ref": "2 Kings 22:1", "text": "Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his mother’s name was Jedidah, the daughter of Adaiah of Boscath."}], [{"ref": "2 Kings 22:8", "text": "And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah gave the book to Shaphan, and he read it."}], [{"ref": "2 Kings 22:11", "text": "And it came to pass, when the king had heard the words of the book of the law, that he rent his clothes."}], [{"ref": "2 Kings 23:21-23", "text": "And the king commanded all the people, saying, Keep the passover unto the LORD your God, as it is written in the book of this covenant. Surely there was not holden such a passover from the days of the judges that judged Israel, nor in all the days of the kings of Israel, nor of the kings of Judah; But in the eighteenth year of king Josiah, wherein this passover was holden to the LORD in Jerusalem."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-ezra','whoami',16,8,4,4,'Nehemiah 8:4',3,'Who am I?','["I was a priest and a ready scribe in the law of Moses.", "I went up from Babylon in the reign of Artaxerxes.", "I read the book of the law to the people.", "I stood upon a pulpit of wood."]'::jsonb,'["Ezra", "Zerubbabel", "Nehemiah", "Haggai"]'::jsonb,0,'Ezra the scribe stood upon a pulpit of wood.','Look in the books of history.',null,null,'KJV',array['ezra','Nehemiah']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam.','[[{"ref": "Ezra 7:6", "text": "This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him."}, {"ref": "Ezra 7:11", "text": "Now this is the copy of the letter that the king Artaxerxes gave unto Ezra the priest, the scribe, even a scribe of the words of the commandments of the LORD, and of his statutes to Israel."}], [{"ref": "Ezra 7:1-6", "text": "Now after these things, in the reign of Artaxerxes king of Persia, Ezra the son of Seraiah, the son of Azariah, the son of Hilkiah, The son of Shallum, the son of Zadok, the son of Ahitub, The son of Amariah, the son of Azariah, the son of Meraioth, The son of Zerahiah, the son of Uzzi, the son of Bukki, The son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest: This Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him."}], [{"ref": "Nehemiah 8:2-3", "text": "And Ezra the priest brought the law before the congregation both of men and women, and all that could hear with understanding, upon the first day of the seventh month. And he read therein before the street that was before the water gate from the morning until midday, before the men and the women, and those that could understand; and the ears of all the people were attentive unto the book of the law."}], [{"ref": "Nehemiah 8:4", "text": "And Ezra the scribe stood upon a pulpit of wood, which they had made for the purpose; and beside him stood Mattithiah, and Shema, and Anaiah, and Urijah, and Hilkiah, and Maaseiah, on his right hand; and on his left hand, Pedaiah, and Mishael, and Malchiah, and Hashum, and Hashbadana, Zechariah, and Meshullam."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-ezekiel','whoami',26,37,4,4,'Ezekiel 37:4',3,'Who am I?','["I was a priest among the captives by the river Chebar.", "I saw wheels whose rings were full of eyes.", "I lay on my side for many days as a sign.", "I prophesied to a valley of dry bones."]'::jsonb,'["Jeremiah", "Daniel", "Ezekiel", "Zechariah"]'::jsonb,2,'God said, "Prophesy upon these bones, and say unto them, O ye dry bones, hear the word of the LORD."','Look in the Major Prophets.',null,null,'KJV',array['ezekiel','Ezekiel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Again he said unto me, Prophesy upon these bones, and say unto them, O ye dry bones, hear the word of the LORD.','[[{"ref": "Ezekiel 1:1-3", "text": "Now it came to pass in the thirtieth year, in the fourth month, in the fifth day of the month, as I was among the captives by the river of Chebar, that the heavens were opened, and I saw visions of God. In the fifth day of the month, which was the fifth year of king Jehoiachin’s captivity, The word of the LORD came expressly unto Ezekiel the priest, the son of Buzi, in the land of the Chaldeans by the river Chebar; and the hand of the LORD was there upon him."}], [{"ref": "Ezekiel 1:18", "text": "As for their rings, they were so high that they were dreadful; and their rings were full of eyes round about them four."}], [{"ref": "Ezekiel 4:4-6", "text": "Lie thou also upon thy left side, and lay the iniquity of the house of Israel upon it: according to the number of the days that thou shalt lie upon it thou shalt bear their iniquity. For I have laid upon thee the years of their iniquity, according to the number of the days, three hundred and ninety days: so shalt thou bear the iniquity of the house of Israel. And when thou hast accomplished them, lie again on thy right side, and thou shalt bear the iniquity of the house of Judah forty days: I have appointed thee each day for a year."}], [{"ref": "Ezekiel 37:4", "text": "Again he said unto me, Prophesy upon these bones, and say unto them, O ye dry bones, hear the word of the LORD."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-hosea','whoami',28,1,3,3,'Hosea 1:3',4,'Who am I?','["I was a prophet to Israel.", "I obeyed God and took Gomer as my wife.", "I named a son Loammi.", "I bought a woman for fifteen pieces of silver and barley."]'::jsonb,'["Hosea", "Amos", "Joel", "Micah"]'::jsonb,0,'Hosea took Gomer the daughter of Diblaim.','Look in the Minor Prophets.',null,null,'KJV',array['hosea','Hosea']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'So he went and took Gomer the daughter of Diblaim; which conceived, and bare him a son.','[[{"ref": "Hosea 1:1", "text": "The word of the LORD that came unto Hosea, the son of Beeri, in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah, and in the days of Jeroboam the son of Joash, king of Israel."}], [{"ref": "Hosea 1:3", "text": "So he went and took Gomer the daughter of Diblaim; which conceived, and bare him a son."}], [{"ref": "Hosea 1:8-9", "text": "Now when she had weaned Lo-ruhamah, she conceived, and bare a son. Then said God, Call his name Lo-ammi: for ye are not my people, and I will not be your God."}], [{"ref": "Hosea 3:2", "text": "So I bought her to me for fifteen pieces of silver, and for an homer of barley, and an half homer of barley:"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-amos','whoami',30,7,14,14,'Amos 7:14',4,'Who am I?','["I was among the herdmen of Tekoa.", "I was a gatherer of sycomore fruit.", "I said I was no prophet, neither a prophet''s son.", "I cried: let judgment run down as waters."]'::jsonb,'["Amos", "Micah", "Obadiah", "Hosea"]'::jsonb,0,'Amos said, "I was no prophet... but I was an herdman, and a gatherer of sycomore fruit."','Look in the Minor Prophets.',null,null,'KJV',array['amos','Amos']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:','[[{"ref": "Amos 1:1", "text": "The words of Amos, who was among the herdmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah, and in the days of Jeroboam the son of Joash king of Israel, two years before the earthquake."}], [{"ref": "Amos 7:14", "text": "Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"}], [{"ref": "Amos 7:14", "text": "Then answered Amos, and said to Amaziah, I was no prophet, neither was I a prophet’s son; but I was an herdman, and a gatherer of sycomore fruit:"}], [{"ref": "Amos 5:24", "text": "But let judgment run down as waters, and righteousness as a mighty stream."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-zacharias','whoami',42,1,63,63,'Luke 1:63',2,'Who am I?','["I was a priest of the course of Abia.", "An angel appeared to me by the altar of incense.", "I was struck dumb because I did not believe.", "I wrote: His name is John."]'::jsonb,'["Joseph", "Annas", "Zacharias", "Simeon"]'::jsonb,2,'Zacharias asked for a writing table and wrote, "His name is John."','Look in Luke.',null,null,'KJV',array['zacharias','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he asked for a writing table, and wrote, saying, His name is John. And they marvelled all.','[[{"ref": "Luke 1:5", "text": "There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}], [{"ref": "Luke 1:11", "text": "And there appeared unto him an angel of the Lord standing on the right side of the altar of incense."}], [{"ref": "Luke 1:20", "text": "And, behold, thou shalt be dumb, and not able to speak, until the day that these things shall be performed, because thou believest not my words, which shall be fulfilled in their season."}], [{"ref": "Luke 1:63", "text": "And he asked for a writing table, and wrote, saying, His name is John. And they marvelled all."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-elisabeth','whoami',42,1,41,41,'Luke 1:41',2,'Who am I?','["I was of the daughters of Aaron.", "I was barren and well stricken in years.", "My babe leaped in my womb when Mary greeted me.", "I was the mother of John the Baptist."]'::jsonb,'["Elisabeth", "Anna", "Salome", "Mary"]'::jsonb,0,'When Elisabeth heard Mary''s greeting, the babe leaped in her womb.','Look in Luke.',null,null,'KJV',array['elisabeth','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it came to pass, that, when Elisabeth heard the salutation of Mary, the babe leaped in her womb; and Elisabeth was filled with the Holy Ghost:','[[{"ref": "Luke 1:5", "text": "There was in the days of Herod, the king of Judæa, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}], [{"ref": "Luke 1:7", "text": "And they had no child, because that Elisabeth was barren, and they both were now well stricken in years."}], [{"ref": "Luke 1:41", "text": "And it came to pass, that, when Elisabeth heard the salutation of Mary, the babe leaped in her womb; and Elisabeth was filled with the Holy Ghost:"}], [{"ref": "Luke 1:57-60", "text": "Now Elisabeth’s full time came that she should be delivered; and she brought forth a son. And her neighbours and her cousins heard how the Lord had shewed great mercy upon her; and they rejoiced with her. And it came to pass, that on the eighth day they came to circumcise the child; and they called him Zacharias, after the name of his father. And his mother answered and said, Not so; but he shall be called John."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-simeon','whoami',42,2,29,29,'Luke 2:29',3,'Who am I?','["I was a just and devout man in Jerusalem.", "The Holy Ghost revealed I would not die before seeing the Lord''s Christ.", "I took the child Jesus up in my arms in the temple.", "I said: Lord, now lettest thou thy servant depart in peace."]'::jsonb,'["Simeon", "Joseph of Arimathaea", "Zacharias", "Nicodemus"]'::jsonb,0,'Simeon said, "Lord, now lettest thou thy servant depart in peace, according to thy word."','Look in Luke.',null,null,'KJV',array['simeon','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Lord, now lettest thou thy servant depart in peace, according to thy word:','[[{"ref": "Luke 2:25", "text": "And, behold, there was a man in Jerusalem, whose name was Simeon; and the same man was just and devout, waiting for the consolation of Israel: and the Holy Ghost was upon him."}], [{"ref": "Luke 2:26", "text": "And it was revealed unto him by the Holy Ghost, that he should not see death, before he had seen the Lord’s Christ."}], [{"ref": "Luke 2:27-28", "text": "And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law, Then took he him up in his arms, and blessed God, and said,"}], [{"ref": "Luke 2:29", "text": "Lord, now lettest thou thy servant depart in peace, according to thy word:"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-anna','whoami',42,2,36,36,'Luke 2:36',3,'Who am I?','["I was a prophetess of the tribe of Aser.", "I was a widow of about fourscore and four years.", "I served God with fastings and prayers night and day.", "I gave thanks when the child Jesus was brought to the temple."]'::jsonb,'["Elisabeth", "Anna", "Phebe", "Dorcas"]'::jsonb,1,'"There was one Anna, a prophetess... of the tribe of Aser."','Look in Luke.',null,null,'KJV',array['anna','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity;','[[{"ref": "Luke 2:36", "text": "And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity;"}], [{"ref": "Luke 2:37", "text": "And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day."}], [{"ref": "Luke 2:37", "text": "And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day."}], [{"ref": "Luke 2:27", "text": "And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law,"}, {"ref": "Luke 2:36-38", "text": "And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity; And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day. And she coming in that instant gave thanks likewise unto the Lord, and spake of him to all them that looked for redemption in Jerusalem."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-joseph_husband','whoami',40,1,20,20,'Matthew 1:20',2,'Who am I?','["I was of the house and lineage of David.", "An angel told me in a dream not to fear to take Mary as my wife.", "I took the young child and his mother into Egypt by night.", "People called Jesus the carpenter''s son."]'::jsonb,'["Joseph of Arimathaea", "Zacharias", "Simeon", "Joseph, husband of Mary"]'::jsonb,3,'The angel said, "Joseph, thou son of David, fear not to take unto thee Mary thy wife."','Look in Matthew.',null,null,'KJV',array['joseph_husband','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'But while he thought on these things, behold, the angel of the Lord appeared unto him in a dream, saying, Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost.','[[{"ref": "Luke 2:4", "text": "And Joseph also went up from Galilee, out of the city of Nazareth, into Judæa, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:)"}], [{"ref": "Matthew 1:20", "text": "But while he thought on these things, behold, the angel of the Lord appeared unto him in a dream, saying, Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost."}], [{"ref": "Matthew 2:14", "text": "When he arose, he took the young child and his mother by night, and departed into Egypt:"}], [{"ref": "Matthew 13:55", "text": "Is not this the carpenter’s son? is not his mother called Mary? and his brethren, James, and Joses, and Simon, and Judas?"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-andrew','whoami',43,1,40,42,'John 1:40-42',2,'Who am I?','["I was from Bethsaida.", "I was one of two who heard John the Baptist speak and followed Jesus.", "I brought my brother Simon to Jesus.", "I told Jesus of a lad with five barley loaves."]'::jsonb,'["James", "Andrew", "Nathanael", "Philip"]'::jsonb,1,'Andrew first found his own brother Simon and brought him to Jesus.','Look in John.',null,null,'KJV',array['andrew','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'One of the two which heard John speak, and followed him, was Andrew, Simon Peter’s brother. He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ. And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone.','[[{"ref": "John 1:44", "text": "Now Philip was of Bethsaida, the city of Andrew and Peter."}], [{"ref": "John 1:40", "text": "One of the two which heard John speak, and followed him, was Andrew, Simon Peter’s brother."}], [{"ref": "John 1:41-42", "text": "He first findeth his own brother Simon, and saith unto him, We have found the Messias, which is, being interpreted, the Christ. And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone."}], [{"ref": "John 6:8-9", "text": "One of his disciples, Andrew, Simon Peter’s brother, saith unto him, There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-philip_apostle','whoami',43,14,8,8,'John 14:8',3,'Who am I?','["I was from Bethsaida.", "Jesus said to me, Follow me.", "I told Nathanael: Come and see.", "I asked Jesus: Lord, shew us the Father."]'::jsonb,'["Thomas", "Bartholomew", "Andrew", "Philip"]'::jsonb,3,'Philip said, "Lord, shew us the Father, and it sufficeth us."','Look in John.',null,null,'KJV',array['philip_apostle','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Philip saith unto him, Lord, shew us the Father, and it sufficeth us.','[[{"ref": "John 1:44", "text": "Now Philip was of Bethsaida, the city of Andrew and Peter."}], [{"ref": "John 1:43", "text": "The day following Jesus would go forth into Galilee, and findeth Philip, and saith unto him, Follow me."}], [{"ref": "John 1:46", "text": "And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see."}], [{"ref": "John 14:8", "text": "Philip saith unto him, Lord, shew us the Father, and it sufficeth us."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-nathanael','whoami',43,1,47,47,'John 1:47',3,'Who am I?','["I was from Cana of Galilee.", "I asked: Can there any good thing come out of Nazareth?", "Jesus saw me under the fig tree.", "Jesus called me an Israelite indeed, in whom is no guile."]'::jsonb,'["Thomas", "Nicodemus", "Nathanael", "Philip"]'::jsonb,2,'Jesus said of Nathanael, "Behold an Israelite indeed, in whom is no guile!"','Look in John.',null,null,'KJV',array['nathanael','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!','[[{"ref": "John 21:2", "text": "There were together Simon Peter, and Thomas called Didymus, and Nathanael of Cana in Galilee, and the sons of Zebedee, and two other of his disciples."}], [{"ref": "John 1:46", "text": "And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see."}], [{"ref": "John 1:48", "text": "Nathanael saith unto him, Whence knowest thou me? Jesus answered and said unto him, Before that Philip called thee, when thou wast under the fig tree, I saw thee."}], [{"ref": "John 1:47", "text": "Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-pilate','whoami',40,27,24,24,'Matthew 27:24',1,'Who am I?','["I was the Roman governor of Judaea.", "My wife sent word about a dream concerning a just man.", "I asked: What is truth?", "I washed my hands before the multitude."]'::jsonb,'["Caiaphas", "Herod", "Felix", "Pontius Pilate"]'::jsonb,3,'Pilate took water and washed his hands before the multitude.','Look in Matthew.',null,null,'KJV',array['pilate','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'When Pilate saw that he could prevail nothing, but that rather a tumult was made, he took water, and washed his hands before the multitude, saying, I am innocent of the blood of this just person: see ye to it.','[[{"ref": "Luke 3:1", "text": "Now in the fifteenth year of the reign of Tiberius Cæsar, Pontius Pilate being governor of Judæa, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of Ituraea and of the region of Trachonitis, and Lysanias the tetrarch of Abilene,"}], [{"ref": "Matthew 27:19", "text": "When he was set down on the judgment seat, his wife sent unto him, saying, Have thou nothing to do with that just man: for I have suffered many things this day in a dream because of him."}], [{"ref": "John 18:38", "text": "Pilate saith unto him, What is truth? And when he had said this, he went out again unto the Jews, and saith unto them, I find in him no fault at all."}], [{"ref": "Matthew 27:24", "text": "When Pilate saw that he could prevail nothing, but that rather a tumult was made, he took water, and washed his hands before the multitude, saying, I am innocent of the blood of this just person: see ye to it."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-caiaphas','whoami',43,11,49,50,'John 11:49-50',3,'Who am I?','["I was high priest that same year.", "I said it was expedient that one man should die for the people.", "Annas was my father-in-law.", "Annas sent Jesus to me bound."]'::jsonb,'["Annas", "Caiaphas", "Nicodemus", "Gamaliel"]'::jsonb,1,'Caiaphas, the high priest that same year, said it was expedient that one man should die for the people.','Look in John.',null,null,'KJV',array['caiaphas','John']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And one of them, named Caiaphas, being the high priest that same year, said unto them, Ye know nothing at all, Nor consider that it is expedient for us, that one man should die for the people, and that the whole nation perish not.','[[{"ref": "John 11:49", "text": "And one of them, named Caiaphas, being the high priest that same year, said unto them, Ye know nothing at all,"}], [{"ref": "John 11:50", "text": "Nor consider that it is expedient for us, that one man should die for the people, and that the whole nation perish not."}], [{"ref": "John 18:13", "text": "And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year."}], [{"ref": "John 18:24", "text": "Now Annas had sent him bound unto Caiaphas the high priest."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-gamaliel','whoami',44,5,34,34,'Acts 5:34',4,'Who am I?','["I was a Pharisee and a doctor of the law.", "I was had in reputation among all the people.", "I told the council to let the apostles alone.", "Paul was brought up at my feet."]'::jsonb,'["Caiaphas", "Ananias", "Gamaliel", "Nicodemus"]'::jsonb,2,'A Pharisee named Gamaliel, a doctor of the law, stood up in the council.','Look in Acts.',null,null,'KJV',array['gamaliel','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;','[[{"ref": "Acts 5:34", "text": "Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;"}], [{"ref": "Acts 5:34", "text": "Then stood there up one in the council, a Pharisee, named Gamaliel, a doctor of the law, had in reputation among all the people, and commanded to put the apostles forth a little space;"}], [{"ref": "Acts 5:38", "text": "And now I say unto you, Refrain from these men, and let them alone: for if this counsel or this work be of men, it will come to nought:"}], [{"ref": "Acts 22:3", "text": "I am verily a man which am a Jew, born in Tarsus, a city in Cilicia, yet brought up in this city at the feet of Gamaliel, and taught according to the perfect manner of the law of the fathers, and was zealous toward God, as ye all are this day."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-dorcas','whoami',44,9,40,40,'Acts 9:40',3,'Who am I?','["I lived in Joppa.", "I was full of good works and almsdeeds.", "I made coats and garments that the widows showed.", "Peter said to me, arise, and I opened my eyes."]'::jsonb,'["Lydia", "Tabitha (Dorcas)", "Priscilla", "Phebe"]'::jsonb,1,'Peter turned to the body and said, "Tabitha, arise." And she opened her eyes.','Look in Acts.',null,null,'KJV',array['dorcas','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'But Peter put them all forth, and kneeled down, and prayed; and turning him to the body said, Tabitha, arise. And she opened her eyes: and when she saw Peter, she sat up.','[[{"ref": "Acts 9:36", "text": "Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did."}], [{"ref": "Acts 9:36", "text": "Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did."}], [{"ref": "Acts 9:39", "text": "Then Peter arose and went with them. When he was come, they brought him into the upper chamber: and all the widows stood by him weeping, and shewing the coats and garments which Dorcas made, while she was with them."}], [{"ref": "Acts 9:40", "text": "But Peter put them all forth, and kneeled down, and prayed; and turning him to the body said, Tabitha, arise. And she opened her eyes: and when she saw Peter, she sat up."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-cornelius','whoami',44,10,1,1,'Acts 10:1',3,'Who am I?','["I was a centurion of the Italian band.", "I was a devout man who prayed to God alway.", "An angel told me to send to Joppa for Peter.", "The Holy Ghost fell on all who heard Peter speak in my house."]'::jsonb,'["Claudius Lysias", "Sergius Paulus", "Cornelius", "Julius"]'::jsonb,2,'Cornelius was a centurion of the band called the Italian band, in Caesarea.','Look in Acts.',null,null,'KJV',array['cornelius','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'There was a certain man in Cæsarea called Cornelius, a centurion of the band called the Italian band,','[[{"ref": "Acts 10:1", "text": "There was a certain man in Cæsarea called Cornelius, a centurion of the band called the Italian band,"}], [{"ref": "Acts 10:2", "text": "A devout man, and one that feared God with all his house, which gave much alms to the people, and prayed to God alway."}], [{"ref": "Acts 10:3-5", "text": "He saw in a vision evidently about the ninth hour of the day an angel of God coming in to him, and saying unto him, Cornelius. And when he looked on him, he was afraid, and said, What is it, Lord? And he said unto him, Thy prayers and thine alms are come up for a memorial before God. And now send men to Joppa, and call for one Simon, whose surname is Peter:"}], [{"ref": "Acts 10:24", "text": "And the morrow after they entered into Cæsarea. And Cornelius waited for them, and had called together his kinsmen and near friends."}, {"ref": "Acts 10:44", "text": "While Peter yet spake these words, the Holy Ghost fell on all them which heard the word."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-priscilla','whoami',44,18,26,26,'Acts 18:26',3,'Who am I?','["My husband Aquila and I were tentmakers.", "We came from Italy when Claudius commanded the Jews to leave Rome.", "Paul stayed and worked with us in Corinth.", "We expounded the way of God more perfectly to Apollos."]'::jsonb,'["Dorcas", "Priscilla", "Lydia", "Phebe"]'::jsonb,1,'Aquila and Priscilla took Apollos aside and expounded unto him the way of God more perfectly.','Look in Acts.',null,null,'KJV',array['priscilla','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly.','[[{"ref": "Acts 18:3", "text": "And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers."}], [{"ref": "Acts 18:2", "text": "And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them."}], [{"ref": "Acts 18:1-3", "text": "After these things Paul departed from Athens, and came to Corinth; And found a certain Jew named Aquila, born in Pontus, lately come from Italy, with his wife Priscilla; (because that Claudius had commanded all Jews to depart from Rome:) and came unto them. And because he was of the same craft, he abode with them, and wrought: for by their occupation they were tentmakers."}], [{"ref": "Acts 18:26", "text": "And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-silas','whoami',44,16,25,25,'Acts 16:25',3,'Who am I?','["I was a chief man among the brethren.", "I travelled with Paul after he parted from Barnabas.", "I was beaten and put in the stocks with Paul at Philippi.", "At midnight Paul and I prayed and sang praises."]'::jsonb,'["Luke", "Barnabas", "Silas", "Timothy"]'::jsonb,2,'At midnight Paul and Silas prayed, and sang praises unto God.','Look in Acts.',null,null,'KJV',array['silas','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them.','[[{"ref": "Acts 15:22", "text": "Then pleased it the apostles and elders, with the whole church, to send chosen men of their own company to Antioch with Paul and Barnabas; namely, Judas surnamed Barsabas, and Silas, chief men among the brethren:"}], [{"ref": "Acts 15:39-40", "text": "And the contention was so sharp between them, that they departed asunder one from the other: and so Barnabas took Mark, and sailed unto Cyprus; And Paul chose Silas, and departed, being recommended by the brethren unto the grace of God."}], [{"ref": "Acts 16:12", "text": "And from thence to Philippi, which is the chief city of that part of Macedonia, and a colony: and we were in that city abiding certain days."}, {"ref": "Acts 16:19", "text": "And when her masters saw that the hope of their gains was gone, they caught Paul and Silas, and drew them into the marketplace unto the rulers,"}, {"ref": "Acts 16:22-25", "text": "And the multitude rose up together against them: and the magistrates rent off their clothes, and commanded to beat them. And when they had laid many stripes upon them, they cast them into prison, charging the jailor to keep them safely: Who, having received such a charge, thrust them into the inner prison, and made their feet fast in the stocks. And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."}], [{"ref": "Acts 16:25", "text": "And at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-apollos','whoami',44,18,24,24,'Acts 18:24',4,'Who am I?','["I was a Jew born at Alexandria.", "I was an eloquent man, mighty in the scriptures.", "Aquila and Priscilla taught me the way of God more perfectly.", "Paul wrote that he planted and I watered."]'::jsonb,'["Titus", "Apollos", "Silas", "Aquila"]'::jsonb,1,'A Jew named Apollos, born at Alexandria, was an eloquent man, mighty in the scriptures.','Look in Acts.',null,null,'KJV',array['apollos','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus.','[[{"ref": "Acts 18:24", "text": "And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus."}], [{"ref": "Acts 18:24", "text": "And a certain Jew named Apollos, born at Alexandria, an eloquent man, and mighty in the scriptures, came to Ephesus."}], [{"ref": "Acts 18:26", "text": "And he began to speak boldly in the synagogue: whom when Aquila and Priscilla had heard, they took him unto them, and expounded unto him the way of God more perfectly."}], [{"ref": "1 Corinthians 3:6", "text": "I have planted, Apollos watered; but God gave the increase."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-abigail','whoami',9,25,3,3,'1 Samuel 25:3',3,'Who am I?','["My husband Nabal was churlish.", "I brought bread, wine and figs to David''s men.", "I persuaded David not to shed blood.", "After Nabal died, I became David''s wife."]'::jsonb,'["Abigail", "Bathsheba", "Michal", "Ahinoam"]'::jsonb,0,'The man''s name was Nabal and the name of his wife Abigail.','Look in 1 Samuel.',null,null,'KJV',array['abigail','1 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Now the name of the man was Nabal; and the name of his wife Abigail: and she was a woman of good understanding, and of a beautiful countenance: but the man was churlish and evil in his doings; and he was of the house of Caleb.','[[{"ref": "1 Samuel 25:3", "text": "Now the name of the man was Nabal; and the name of his wife Abigail: and she was a woman of good understanding, and of a beautiful countenance: but the man was churlish and evil in his doings; and he was of the house of Caleb."}], [{"ref": "1 Samuel 25:18", "text": "Then Abigail made haste, and took two hundred loaves, and two bottles of wine, and five sheep ready dressed, and five measures of parched corn, and an hundred clusters of raisins, and two hundred cakes of figs, and laid them on asses."}], [{"ref": "1 Samuel 25:33", "text": "And blessed be thy advice, and blessed be thou, which hast kept me this day from coming to shed blood, and from avenging myself with mine own hand."}], [{"ref": "1 Samuel 25:38-39", "text": "And it came to pass about ten days after, that the LORD smote Nabal, that he died. And when David heard that Nabal was dead, he said, Blessed be the LORD, that hath pleaded the cause of my reproach from the hand of Nabal, and hath kept his servant from evil: for the LORD hath returned the wickedness of Nabal upon his own head. And David sent and communed with Abigail, to take her to him to wife."}, {"ref": "1 Samuel 25:42", "text": "And Abigail hasted, and arose, and rode upon an ass, with five damsels of hers that went after her; and she went after the messengers of David, and became his wife."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-herod','whoami',40,2,16,16,'Matthew 2:16',2,'Who am I?','["I was king in Judaea when Jesus was born.", "I was troubled when wise men asked for the King of the Jews.", "I told the wise men to bring me word again.", "I ordered the children in Bethlehem slain."]'::jsonb,'["Herod", "Pontius Pilate", "Archelaus", "Caesar Augustus"]'::jsonb,0,'Herod sent forth and slew all the children that were in Bethlehem.','Look in Matthew.',null,null,'KJV',array['herod','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then Herod, when he saw that he was mocked of the wise men, was exceeding wroth, and sent forth, and slew all the children that were in Bethlehem, and in all the coasts thereof, from two years old and under, according to the time which he had diligently enquired of the wise men.','[[{"ref": "Matthew 2:1", "text": "Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king, behold, there came wise men from the east to Jerusalem,"}], [{"ref": "Matthew 2:2-3", "text": "Saying, Where is he that is born King of the Jews? for we have seen his star in the east, and are come to worship him. When Herod the king had heard these things, he was troubled, and all Jerusalem with him."}], [{"ref": "Matthew 2:8", "text": "And he sent them to Bethlehem, and said, Go and search diligently for the young child; and when ye have found him, bring me word again, that I may come and worship him also."}], [{"ref": "Matthew 2:16", "text": "Then Herod, when he saw that he was mocked of the wise men, was exceeding wroth, and sent forth, and slew all the children that were in Bethlehem, and in all the coasts thereof, from two years old and under, according to the time which he had diligently enquired of the wise men."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jael','whoami',7,4,21,21,'Judges 4:21',4,'Who am I?','["I was the wife of Heber the Kenite.", "Sisera fled to my tent.", "I gave him milk when he asked for water.", "I drove a nail of the tent into his temples."]'::jsonb,'["Rahab", "Jael", "Delilah", "Deborah"]'::jsonb,1,'Jael, Heber''s wife, took a nail of the tent and smote it into Sisera''s temples.','Look in Judges.',null,null,'KJV',array['jael','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'Then Jael Heber’s wife took a nail of the tent, and took an hammer in her hand, and went softly unto him, and smote the nail into his temples, and fastened it into the ground: for he was fast asleep and weary. So he died.','[[{"ref": "Judges 4:17", "text": "Howbeit Sisera fled away on his feet to the tent of Jael the wife of Heber the Kenite: for there was peace between Jabin the king of Hazor and the house of Heber the Kenite."}], [{"ref": "Judges 4:17", "text": "Howbeit Sisera fled away on his feet to the tent of Jael the wife of Heber the Kenite: for there was peace between Jabin the king of Hazor and the house of Heber the Kenite."}], [{"ref": "Judges 4:19", "text": "And he said unto her, Give me, I pray thee, a little water to drink; for I am thirsty. And she opened a bottle of milk, and gave him drink, and covered him."}], [{"ref": "Judges 4:21", "text": "Then Jael Heber’s wife took a nail of the tent, and took an hammer in her hand, and went softly unto him, and smote the nail into his temples, and fastened it into the ground: for he was fast asleep and weary. So he died."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-delilah','whoami',7,16,4,4,'Judges 16:4',1,'Who am I?','["I lived in the valley of Sorek.", "The lords of the Philistines offered me silver.", "I asked a strong man the secret of his strength.", "I had his seven locks shaved while he slept."]'::jsonb,'["Jezebel", "Delilah", "Jael", "Michal"]'::jsonb,1,'Samson loved a woman in the valley of Sorek, whose name was Delilah.','Look in Judges.',null,null,'KJV',array['delilah','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-22", "review_method": "Approved by the project owner on the basis of the automated checks: KJV reference and keyword check for every question, plus AI review (Claude Opus 5.5) against the KJV text; the 13 AI-flagged picture questions were fixed and re-checked first. Not read individually in Quick review. See tests/review/exp1/REPORT.md and tests/review/pic92."}'::jsonb,'And it came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah.','[[{"ref": "Judges 16:4", "text": "And it came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah."}], [{"ref": "Judges 16:5", "text": "And the lords of the Philistines came up unto her, and said unto her, Entice him, and see wherein his great strength lieth, and by what means we may prevail against him, that we may bind him to afflict him: and we will give thee every one of us eleven hundred pieces of silver."}], [{"ref": "Judges 16:6", "text": "And Delilah said to Samson, Tell me, I pray thee, wherein thy great strength lieth, and wherewith thou mightest be bound to afflict thee."}], [{"ref": "Judges 16:19", "text": "And she made him sleep upon her knees; and she called for a man, and she caused him to shave off the seven locks of his head; and she began to afflict him, and his strength went from him."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-abel','whoami',1,4,8,8,'Genesis 4:8',1,'Who am I?','["My older brother was a tiller of the ground.", "I was a keeper of sheep.", "The LORD had respect unto my offering from the firstlings of my flock.", "My brother rose up against me in the field."]'::jsonb,'["Enoch", "Cain", "Seth", "Abel"]'::jsonb,3,'Cain rose up against Abel his brother in the field and slew him (Genesis 4:8).','Look in Genesis.',null,null,'KJV',array['abel','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And Cain talked with Abel his brother: and it came to pass, when they were in the field, that Cain rose up against Abel his brother, and slew him.','[[{"ref": "Genesis 4:2", "text": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}], [{"ref": "Genesis 4:2", "text": "And she again bare his brother Abel. And Abel was a keeper of sheep, but Cain was a tiller of the ground."}], [{"ref": "Genesis 4:4", "text": "And Abel, he also brought of the firstlings of his flock and of the fat thereof. And the LORD had respect unto Abel and to his offering:"}], [{"ref": "Genesis 4:8", "text": "And Cain talked with Abel his brother: and it came to pass, when they were in the field, that Cain rose up against Abel his brother, and slew him."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-ishmael','whoami',1,16,11,11,'Genesis 16:11',2,'Who am I?','["My mother was an Egyptian handmaid.", "An angel told my mother my name before I was born.", "My name was given because the LORD had heard my mother''s affliction.", "My father was Abraham, but I was not the son of the promise."]'::jsonb,'["Isaac", "Lot", "Ishmael", "Esau"]'::jsonb,2,'The angel told Hagar to call her son Ishmael, because the LORD had heard her affliction (Genesis 16:11).','Look in Genesis.',null,null,'KJV',array['ishmael','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And the angel of the LORD said unto her, Behold, thou art with child, and shalt bear a son, and shalt call his name Ishmael; because the LORD hath heard thy affliction.','[[{"ref": "Genesis 16:1", "text": "Now Sarai Abram’s wife bare him no children: and she had an handmaid, an Egyptian, whose name was Hagar."}], [{"ref": "Genesis 16:11", "text": "And the angel of the LORD said unto her, Behold, thou art with child, and shalt bear a son, and shalt call his name Ishmael; because the LORD hath heard thy affliction."}], [{"ref": "Genesis 16:11", "text": "And the angel of the LORD said unto her, Behold, thou art with child, and shalt bear a son, and shalt call his name Ishmael; because the LORD hath heard thy affliction."}], [{"ref": "Galatians 4:22-23", "text": "For it is written, that Abraham had two sons, the one by a bondmaid, the other by a freewoman. But he who was of the bondwoman was born after the flesh; but he of the freewoman was by promise."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-hagar','whoami',1,16,13,13,'Genesis 16:13',2,'Who am I?','["I was an Egyptian handmaid of Sarai.", "I fled into the wilderness, and an angel found me by a fountain of water.", "I called the LORD who spoke to me, Thou God seest me.", "My son was Ishmael."]'::jsonb,'["Keturah", "Zilpah", "Bilhah", "Hagar"]'::jsonb,3,'Hagar called the name of the LORD that spoke to her, Thou God seest me (Genesis 16:13).','Look in Genesis.',null,null,'KJV',array['hagar','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And she called the name of the LORD that spake unto her, Thou God seest me: for she said, Have I also here looked after him that seeth me?','[[{"ref": "Genesis 16:1", "text": "Now Sarai Abram’s wife bare him no children: and she had an handmaid, an Egyptian, whose name was Hagar."}], [{"ref": "Genesis 16:6-7", "text": "But Abram said unto Sarai, Behold, thy maid is in thy hand; do to her as it pleaseth thee. And when Sarai dealt hardly with her, she fled from her face. And the angel of the LORD found her by a fountain of water in the wilderness, by the fountain in the way to Shur."}], [{"ref": "Genesis 16:13", "text": "And she called the name of the LORD that spake unto her, Thou God seest me: for she said, Have I also here looked after him that seeth me?"}], [{"ref": "Genesis 16:15", "text": "And Hagar bare Abram a son: and Abram called his son’s name, which Hagar bare, Ishmael."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-laban','whoami',1,29,25,25,'Genesis 29:25',2,'Who am I?','["I was the brother of Rebekah.", "My nephew served me seven years for my younger daughter.", "On the wedding night I gave him my older daughter instead.", "My daughters were Leah and Rachel."]'::jsonb,'["Nahor", "Laban", "Jethro", "Bethuel"]'::jsonb,1,'In the morning Jacob found it was Leah and asked Laban why he had beguiled him (Genesis 29:25).','Look in Genesis.',null,null,'KJV',array['laban','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And it came to pass, that in the morning, behold, it was Leah: and he said to Laban, What is this thou hast done unto me? did not I serve with thee for Rachel? wherefore then hast thou beguiled me?','[[{"ref": "Genesis 24:29", "text": "And Rebekah had a brother, and his name was Laban: and Laban ran out unto the man, unto the well."}], [{"ref": "Genesis 29:10", "text": "And it came to pass, when Jacob saw Rachel the daughter of Laban his mother’s brother, and the sheep of Laban his mother’s brother, that Jacob went near, and rolled the stone from the well’s mouth, and watered the flock of Laban his mother’s brother."}, {"ref": "Genesis 29:18", "text": "And Jacob loved Rachel; and said, I will serve thee seven years for Rachel thy younger daughter."}], [{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}, {"ref": "Genesis 29:22-23", "text": "And Laban gathered together all the men of the place, and made a feast. And it came to pass in the evening, that he took Leah his daughter, and brought her to him; and he went in unto her."}], [{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-leah','whoami',1,29,17,17,'Genesis 29:17',2,'Who am I?','["My eyes are described as tender.", "My father gave me to Jacob in place of my younger sister.", "I was the mother of Reuben, Levi and Judah.", "My younger sister was Rachel."]'::jsonb,'["Rachel", "Bilhah", "Dinah", "Leah"]'::jsonb,3,'Leah was tender eyed, but Rachel was beautiful and well favoured (Genesis 29:17).','Look in Genesis.',null,null,'KJV',array['leah','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'Leah was tender eyed; but Rachel was beautiful and well favoured.','[[{"ref": "Genesis 29:17", "text": "Leah was tender eyed; but Rachel was beautiful and well favoured."}], [{"ref": "Genesis 29:23-26", "text": "And it came to pass in the evening, that he took Leah his daughter, and brought her to him; and he went in unto her. And Laban gave unto his daughter Leah Zilpah his maid for an handmaid. And it came to pass, that in the morning, behold, it was Leah: and he said to Laban, What is this thou hast done unto me? did not I serve with thee for Rachel? wherefore then hast thou beguiled me? And Laban said, It must not be so done in our country, to give the younger before the firstborn."}], [{"ref": "Genesis 29:32-35", "text": "And Leah conceived, and bare a son, and she called his name Reuben: for she said, Surely the LORD hath looked upon my affliction; now therefore my husband will love me. And she conceived again, and bare a son; and said, Because the LORD hath heard that I was hated, he hath therefore given me this son also: and she called his name Simeon. And she conceived again, and bare a son; and said, Now this time will my husband be joined unto me, because I have born him three sons: therefore was his name called Levi. And she conceived again, and bare a son: and she said, Now will I praise the LORD: therefore she called his name Judah; and left bearing."}], [{"ref": "Genesis 29:16", "text": "And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-judah','whoami',1,49,10,10,'Genesis 49:10',3,'Who am I?','["I was the fourth son of Leah.", "I said, let us sell our brother rather than kill him.", "In Egypt I offered to stay as a bondman in place of my youngest brother.", "Jacob said the sceptre would not depart from me."]'::jsonb,'["Judah", "Levi", "Simeon", "Reuben"]'::jsonb,0,'Jacob blessed his son: The sceptre shall not depart from Judah (Genesis 49:10).','Look in Genesis.',null,null,'KJV',array['judah','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'The sceptre shall not depart from Judah, nor a lawgiver from between his feet, until Shiloh come; and unto him shall the gathering of the people be.','[[{"ref": "Genesis 29:32-35", "text": "And Leah conceived, and bare a son, and she called his name Reuben: for she said, Surely the LORD hath looked upon my affliction; now therefore my husband will love me. And she conceived again, and bare a son; and said, Because the LORD hath heard that I was hated, he hath therefore given me this son also: and she called his name Simeon. And she conceived again, and bare a son; and said, Now this time will my husband be joined unto me, because I have born him three sons: therefore was his name called Levi. And she conceived again, and bare a son: and she said, Now will I praise the LORD: therefore she called his name Judah; and left bearing."}], [{"ref": "Genesis 37:26-27", "text": "And Judah said unto his brethren, What profit is it if we slay our brother, and conceal his blood? Come, and let us sell him to the Ishmeelites, and let not our hand be upon him; for he is our brother and our flesh. And his brethren were content."}], [{"ref": "Genesis 44:18", "text": "Then Judah came near unto him, and said, Oh my lord, let thy servant, I pray thee, speak a word in my lord’s ears, and let not thine anger burn against thy servant: for thou art even as Pharaoh."}, {"ref": "Genesis 44:33", "text": "Now therefore, I pray thee, let thy servant abide instead of the lad a bondman to my lord; and let the lad go up with his brethren."}], [{"ref": "Genesis 49:10", "text": "The sceptre shall not depart from Judah, nor a lawgiver from between his feet, until Shiloh come; and unto him shall the gathering of the people be."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-benjamin','whoami',1,44,12,12,'Genesis 44:12',2,'Who am I?','["I was the youngest son of Jacob.", "My mother died as I was born, and she called me Benoni.", "Joseph''s silver cup was found in my sack.", "My full brother was Joseph."]'::jsonb,'["Joseph", "Judah", "Dan", "Benjamin"]'::jsonb,3,'The steward searched from the eldest to the youngest, and the cup was found in Benjamin''s sack (Genesis 44:12).','Look in Genesis.',null,null,'KJV',array['benjamin','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And he searched, and began at the eldest, and left at the youngest: and the cup was found in Benjamin’s sack.','[[{"ref": "Genesis 42:4", "text": "But Benjamin, Joseph’s brother, Jacob sent not with his brethren; for he said, Lest peradventure mischief befall him."}, {"ref": "Genesis 42:13", "text": "And they said, Thy servants are twelve brethren, the sons of one man in the land of Canaan; and, behold, the youngest is this day with our father, and one is not."}], [{"ref": "Genesis 35:18", "text": "And it came to pass, as her soul was in departing, (for she died) that she called his name Ben-oni: but his father called him Benjamin."}], [{"ref": "Genesis 44:2", "text": "And put my cup, the silver cup, in the sack’s mouth of the youngest, and his corn money. And he did according to the word that Joseph had spoken."}, {"ref": "Genesis 44:12", "text": "And he searched, and began at the eldest, and left at the youngest: and the cup was found in Benjamin’s sack."}], [{"ref": "Genesis 35:24", "text": "The sons of Rachel; Joseph, and Benjamin:"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-reuben','whoami',1,37,22,22,'Genesis 37:22',3,'Who am I?','["I was Jacob''s firstborn son.", "I found mandrakes in the field and brought them to my mother.", "I persuaded my brothers to cast Joseph into a pit instead of killing him.", "I planned to rescue Joseph and bring him back to our father."]'::jsonb,'["Levi", "Reuben", "Judah", "Simeon"]'::jsonb,1,'Reuben said, Shed no blood, but cast him into this pit, so that he might deliver him to his father again (Genesis 37:22).','Look in Genesis.',null,null,'KJV',array['reuben','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again.','[[{"ref": "Genesis 35:23", "text": "The sons of Leah; Reuben, Jacob’s firstborn, and Simeon, and Levi, and Judah, and Issachar, and Zebulun:"}], [{"ref": "Genesis 30:14", "text": "And Reuben went in the days of wheat harvest, and found mandrakes in the field, and brought them unto his mother Leah. Then Rachel said to Leah, Give me, I pray thee, of thy son’s mandrakes."}], [{"ref": "Genesis 37:21-22", "text": "And Reuben heard it, and he delivered him out of their hands; and said, Let us not kill him. And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again."}], [{"ref": "Genesis 37:22", "text": "And Reuben said unto them, Shed no blood, but cast him into this pit that is in the wilderness, and lay no hand upon him; that he might rid him out of their hands, to deliver him to his father again."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-zipporah','whoami',2,2,21,21,'Exodus 2:21',3,'Who am I?','["My father was a priest of Midian.", "I met my husband when he helped my sisters and me water our flock.", "God sent my husband to bring Israel out of Egypt.", "I circumcised my son with a sharp stone."]'::jsonb,'["Jochebed", "Miriam", "Zipporah", "Rahab"]'::jsonb,2,'Moses was content to dwell with the priest of Midian, who gave Moses Zipporah his daughter (Exodus 2:21).','Look in Exodus.',null,null,'KJV',array['zipporah','Exodus']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And Moses was content to dwell with the man: and he gave Moses Zipporah his daughter.','[[{"ref": "Exodus 2:16", "text": "Now the priest of Midian had seven daughters: and they came and drew water, and filled the troughs to water their father’s flock."}, {"ref": "Exodus 2:21", "text": "And Moses was content to dwell with the man: and he gave Moses Zipporah his daughter."}], [{"ref": "Exodus 2:17", "text": "And the shepherds came and drove them away: but Moses stood up and helped them, and watered their flock."}, {"ref": "Exodus 2:21", "text": "And Moses was content to dwell with the man: and he gave Moses Zipporah his daughter."}], [{"ref": "Exodus 3:10", "text": "Come now therefore, and I will send thee unto Pharaoh, that thou mayest bring forth my people the children of Israel out of Egypt."}], [{"ref": "Exodus 4:25", "text": "Then Zipporah took a sharp stone, and cut off the foreskin of her son, and cast it at his feet, and said, Surely a bloody husband art thou to me."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-achan','whoami',6,7,21,21,'Joshua 7:21',3,'Who am I?','["I took a Babylonish garment, silver and a wedge of gold from Jericho.", "I hid them in the earth in the middle of my tent.", "Because of my sin, Israel was defeated at Ai.", "I was the son of Carmi, of the tribe of Judah."]'::jsonb,'["Korah", "Balaam", "Achan", "Gehazi"]'::jsonb,2,'Achan confessed that he coveted a Babylonish garment, silver and gold, and hid them in his tent (Joshua 7:21).','Look in Joshua.',null,null,'KJV',array['achan','Joshua']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they are hid in the earth in the midst of my tent, and the silver under it.','[[{"ref": "Joshua 7:1", "text": "But the children of Israel committed a trespass in the accursed thing: for Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, took of the accursed thing: and the anger of the LORD was kindled against the children of Israel."}, {"ref": "Joshua 7:21", "text": "When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they are hid in the earth in the midst of my tent, and the silver under it."}], [{"ref": "Joshua 7:21", "text": "When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they are hid in the earth in the midst of my tent, and the silver under it."}], [{"ref": "Joshua 7:4-5", "text": "So there went up thither of the people about three thousand men: and they fled before the men of Ai. And the men of Ai smote of them about thirty and six men: for they chased them from before the gate even unto Shebarim, and smote them in the going down: wherefore the hearts of the people melted, and became as water."}, {"ref": "Joshua 7:11-12", "text": "Israel hath sinned, and they have also transgressed my covenant which I commanded them: for they have even taken of the accursed thing, and have also stolen, and dissembled also, and they have put it even among their own stuff. Therefore the children of Israel could not stand before their enemies, but turned their backs before their enemies, because they were accursed: neither will I be with you any more, except ye destroy the accursed from among you."}], [{"ref": "Joshua 7:1", "text": "But the children of Israel committed a trespass in the accursed thing: for Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, took of the accursed thing: and the anger of the LORD was kindled against the children of Israel."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-ehud','whoami',7,3,15,15,'Judges 3:15',4,'Who am I?','["The LORD raised me up as a deliverer of Israel; I was a Benjamite.", "I was left-handed.", "I made a dagger with two edges, a cubit long.", "I killed Eglon, the king of Moab."]'::jsonb,'["Othniel", "Ehud", "Shamgar", "Gideon"]'::jsonb,1,'The LORD raised up a deliverer, Ehud the son of Gera, a Benjamite, a man lefthanded (Judges 3:15).','Look in Judges.',null,null,'KJV',array['ehud','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'But when the children of Israel cried unto the LORD, the LORD raised them up a deliverer, Ehud the son of Gera, a Benjamite, a man lefthanded: and by him the children of Israel sent a present unto Eglon the king of Moab.','[[{"ref": "Judges 3:15", "text": "But when the children of Israel cried unto the LORD, the LORD raised them up a deliverer, Ehud the son of Gera, a Benjamite, a man lefthanded: and by him the children of Israel sent a present unto Eglon the king of Moab."}], [{"ref": "Judges 3:15", "text": "But when the children of Israel cried unto the LORD, the LORD raised them up a deliverer, Ehud the son of Gera, a Benjamite, a man lefthanded: and by him the children of Israel sent a present unto Eglon the king of Moab."}], [{"ref": "Judges 3:16", "text": "But Ehud made him a dagger which had two edges, of a cubit length; and he did gird it under his raiment upon his right thigh."}], [{"ref": "Judges 3:17", "text": "And he brought the present unto Eglon king of Moab: and Eglon was a very fat man."}, {"ref": "Judges 3:21", "text": "And Ehud put forth his left hand, and took the dagger from his right thigh, and thrust it into his belly:"}, {"ref": "Judges 3:25", "text": "And they tarried till they were ashamed: and, behold, he opened not the doors of the parlour; therefore they took a key, and opened them: and, behold, their lord was fallen down dead on the earth."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-barak','whoami',7,4,8,8,'Judges 4:8',3,'Who am I?','["The prophetess Deborah called me to fight.", "I would not go to battle unless Deborah went with me.", "I led ten thousand men down from mount Tabor.", "I fought against Sisera, captain of Jabin''s army."]'::jsonb,'["Barak", "Gideon", "Joshua", "Jephthah"]'::jsonb,0,'Barak said to Deborah, If thou wilt go with me, then I will go (Judges 4:8).','Look in Judges.',null,null,'KJV',array['barak','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And Barak said unto her, If thou wilt go with me, then I will go: but if thou wilt not go with me, then I will not go.','[[{"ref": "Judges 4:6", "text": "And she sent and called Barak the son of Abinoam out of Kedesh-naphtali, and said unto him, Hath not the LORD God of Israel commanded, saying, Go and draw toward mount Tabor, and take with thee ten thousand men of the children of Naphtali and of the children of Zebulun?"}], [{"ref": "Judges 4:8", "text": "And Barak said unto her, If thou wilt go with me, then I will go: but if thou wilt not go with me, then I will not go."}], [{"ref": "Judges 4:14", "text": "And Deborah said unto Barak, Up; for this is the day in which the LORD hath delivered Sisera into thine hand: is not the LORD gone out before thee? So Barak went down from mount Tabor, and ten thousand men after him."}], [{"ref": "Judges 4:7", "text": "And I will draw unto thee to the river Kishon Sisera, the captain of Jabin’s army, with his chariots and his multitude; and I will deliver him into thine hand."}, {"ref": "Judges 4:15", "text": "And the LORD discomfited Sisera, and all his chariots, and all his host, with the edge of the sword before Barak; so that Sisera lighted down off his chariot, and fled away on his feet."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jephthah','whoami',7,11,34,34,'Judges 11:34',3,'Who am I?','["I was a Gileadite and a mighty man of valour.", "My brothers drove me out, and I lived in the land of Tob.", "I made a vow to the LORD before fighting the children of Ammon.", "My daughter came out to meet me with timbrels and dances."]'::jsonb,'["Ehud", "Samson", "Jephthah", "Gideon"]'::jsonb,2,'When Jephthah came home to Mizpeh, his daughter came out to meet him with timbrels and dances (Judges 11:34).','Look in Judges.',null,null,'KJV',array['jephthah','Judges']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And Jephthah came to Mizpeh unto his house, and, behold, his daughter came out to meet him with timbrels and with dances: and she was his only child; beside her he had neither son nor daughter.','[[{"ref": "Judges 11:1", "text": "Now Jephthah the Gileadite was a mighty man of valour, and he was the son of an harlot: and Gilead begat Jephthah."}], [{"ref": "Judges 11:2-3", "text": "And Gilead’s wife bare him sons; and his wife’s sons grew up, and they thrust out Jephthah, and said unto him, Thou shalt not inherit in our father’s house; for thou art the son of a strange woman. Then Jephthah fled from his brethren, and dwelt in the land of Tob: and there were gathered vain men to Jephthah, and went out with him."}], [{"ref": "Judges 11:30-31", "text": "And Jephthah vowed a vow unto the LORD, and said, If thou shalt without fail deliver the children of Ammon into mine hands, Then it shall be, that whatsoever cometh forth of the doors of my house to meet me, when I return in peace from the children of Ammon, shall surely be the LORD’s, and I will offer it up for a burnt offering."}], [{"ref": "Judges 11:34", "text": "And Jephthah came to Mizpeh unto his house, and, behold, his daughter came out to meet him with timbrels and with dances: and she was his only child; beside her he had neither son nor daughter."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-naomi','whoami',8,1,20,20,'Ruth 1:20',1,'Who am I?','["My husband Elimelech and I moved to Moab during a famine.", "My husband and both my sons died in Moab.", "I asked to be called Mara, because the Almighty had dealt very bitterly with me.", "My daughter-in-law Ruth would not leave me."]'::jsonb,'["Elisabeth", "Hannah", "Naomi", "Orpah"]'::jsonb,2,'She said, Call me not Naomi, call me Mara: for the Almighty hath dealt very bitterly with me (Ruth 1:20).','Look in Ruth.',null,null,'KJV',array['naomi','Ruth']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And she said unto them, Call me not Naomi, call me Mara: for the Almighty hath dealt very bitterly with me.','[[{"ref": "Ruth 1:1-2", "text": "Now it came to pass in the days when the judges ruled, that there was a famine in the land. And a certain man of Beth-lehem-judah went to sojourn in the country of Moab, he, and his wife, and his two sons. And the name of the man was Elimelech, and the name of his wife Naomi, and the name of his two sons Mahlon and Chilion, Ephrathites of Beth-lehem-judah. And they came into the country of Moab, and continued there."}], [{"ref": "Ruth 1:3-5", "text": "And Elimelech Naomi’s husband died; and she was left, and her two sons. And they took them wives of the women of Moab; the name of the one was Orpah, and the name of the other Ruth: and they dwelled there about ten years. And Mahlon and Chilion died also both of them; and the woman was left of her two sons and her husband."}], [{"ref": "Ruth 1:20", "text": "And she said unto them, Call me not Naomi, call me Mara: for the Almighty hath dealt very bitterly with me."}], [{"ref": "Ruth 1:16", "text": "And Ruth said, Intreat me not to leave thee, or to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people shall be my people, and thy God my God:"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-mephibosheth','whoami',10,9,13,13,'2 Samuel 9:13',3,'Who am I?','["I was the son of Jonathan.", "I became lame when my nurse fled with me and I fell.", "King David restored to me all the land of Saul.", "I ate continually at the king''s table."]'::jsonb,'["Ishbosheth", "Mephibosheth", "Absalom", "Ziba"]'::jsonb,1,'Mephibosheth dwelt in Jerusalem and ate continually at the king''s table, and was lame on both his feet (2 Samuel 9:13).','Look in 2 Samuel.',null,null,'KJV',array['mephibosheth','2 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'So Mephibosheth dwelt in Jerusalem: for he did eat continually at the king’s table; and was lame on both his feet.','[[{"ref": "2 Samuel 4:4", "text": "And Jonathan, Saul’s son, had a son that was lame of his feet. He was five years old when the tidings came of Saul and Jonathan out of Jezreel, and his nurse took him up, and fled: and it came to pass, as she made haste to flee, that he fell, and became lame. And his name was Mephibosheth."}], [{"ref": "2 Samuel 4:4", "text": "And Jonathan, Saul’s son, had a son that was lame of his feet. He was five years old when the tidings came of Saul and Jonathan out of Jezreel, and his nurse took him up, and fled: and it came to pass, as she made haste to flee, that he fell, and became lame. And his name was Mephibosheth."}], [{"ref": "2 Samuel 9:7", "text": "And David said unto him, Fear not: for I will surely shew thee kindness for Jonathan thy father’s sake, and will restore thee all the land of Saul thy father; and thou shalt eat bread at my table continually."}, {"ref": "2 Samuel 9:9", "text": "Then the king called to Ziba, Saul’s servant, and said unto him, I have given unto thy master’s son all that pertained to Saul and to all his house."}], [{"ref": "2 Samuel 9:13", "text": "So Mephibosheth dwelt in Jerusalem: for he did eat continually at the king’s table; and was lame on both his feet."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-joab','whoami',10,18,14,14,'2 Samuel 18:14',3,'Who am I?','["I was the captain of King David''s army.", "My mother was Zeruiah.", "I killed Abner at the gate of Hebron.", "I thrust three darts through Absalom''s heart as he hung in an oak."]'::jsonb,'["Joab", "Uriah", "Benaiah", "Abner"]'::jsonb,0,'Joab took three darts and thrust them through the heart of Absalom while he was alive in the oak (2 Samuel 18:14).','Look in 2 Samuel.',null,null,'KJV',array['joab','2 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'Then said Joab, I may not tarry thus with thee. And he took three darts in his hand, and thrust them through the heart of Absalom, while he was yet alive in the midst of the oak.','[[{"ref": "2 Samuel 8:16", "text": "And Joab the son of Zeruiah was over the host; and Jehoshaphat the son of Ahilud was recorder;"}], [{"ref": "2 Samuel 2:18", "text": "And there were three sons of Zeruiah there, Joab, and Abishai, and Asahel: and Asahel was as light of foot as a wild roe."}], [{"ref": "2 Samuel 3:27", "text": "And when Abner was returned to Hebron, Joab took him aside in the gate to speak with him quietly, and smote him there under the fifth rib, that he died, for the blood of Asahel his brother."}], [{"ref": "2 Samuel 18:14", "text": "Then said Joab, I may not tarry thus with thee. And he took three darts in his hand, and thrust them through the heart of Absalom, while he was yet alive in the midst of the oak."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-uriah','whoami',10,11,15,15,'2 Samuel 11:15',2,'Who am I?','["I was a Hittite and one of David''s mighty men.", "I would not go down to my house while the ark and the army stayed in tents.", "I carried a letter to Joab that arranged my own death.", "My wife was Bathsheba."]'::jsonb,'["Nathan", "Uriah", "Joab", "Abner"]'::jsonb,1,'David wrote, Set ye Uriah in the forefront of the hottest battle (2 Samuel 11:15).','Look in 2 Samuel.',null,null,'KJV',array['uriah','2 Samuel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And he wrote in the letter, saying, Set ye Uriah in the forefront of the hottest battle, and retire ye from him, that he may be smitten, and die.','[[{"ref": "2 Samuel 11:3", "text": "And David sent and enquired after the woman. And one said, Is not this Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite?"}, {"ref": "2 Samuel 23:8", "text": "These be the names of the mighty men whom David had: The Tachmonite that sat in the seat, chief among the captains; the same was Adino the Eznite: he lift up his spear against eight hundred, whom he slew at one time."}, {"ref": "2 Samuel 23:39", "text": "Uriah the Hittite: thirty and seven in all."}], [{"ref": "2 Samuel 11:11", "text": "And Uriah said unto David, The ark, and Israel, and Judah, abide in tents; and my lord Joab, and the servants of my lord, are encamped in the open fields; shall I then go into mine house, to eat and to drink, and to lie with my wife? as thou livest, and as thy soul liveth, I will not do this thing."}], [{"ref": "2 Samuel 11:14-15", "text": "And it came to pass in the morning, that David wrote a letter to Joab, and sent it by the hand of Uriah. And he wrote in the letter, saying, Set ye Uriah in the forefront of the hottest battle, and retire ye from him, that he may be smitten, and die."}], [{"ref": "2 Samuel 11:3", "text": "And David sent and enquired after the woman. And one said, Is not this Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite?"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-rehoboam','whoami',11,12,14,14,'1 Kings 12:14',3,'Who am I?','["I was the son of Solomon.", "I rejected the counsel of the old men and followed the young men.", "I told the people, my father chastised you with whips, but I will chastise you with scorpions.", "The ten tribes of Israel rebelled against me."]'::jsonb,'["Abijah", "Rehoboam", "Asa", "Jeroboam"]'::jsonb,1,'Rehoboam answered after the counsel of the young men: I will chastise you with scorpions (1 Kings 12:14).','Look in 1 Kings.',null,null,'KJV',array['rehoboam','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And spake to them after the counsel of the young men, saying, My father made your yoke heavy, and I will add to your yoke: my father also chastised you with whips, but I will chastise you with scorpions.','[[{"ref": "1 Kings 11:43", "text": "And Solomon slept with his fathers, and was buried in the city of David his father: and Rehoboam his son reigned in his stead."}], [{"ref": "1 Kings 12:8", "text": "But he forsook the counsel of the old men, which they had given him, and consulted with the young men that were grown up with him, and which stood before him:"}], [{"ref": "1 Kings 12:14", "text": "And spake to them after the counsel of the young men, saying, My father made your yoke heavy, and I will add to your yoke: my father also chastised you with whips, but I will chastise you with scorpions."}], [{"ref": "1 Kings 11:31", "text": "And he said to Jeroboam, Take thee ten pieces: for thus saith the LORD, the God of Israel, Behold, I will rend the kingdom out of the hand of Solomon, and will give ten tribes to thee:"}, {"ref": "1 Kings 12:16", "text": "So when all Israel saw that the king hearkened not unto them, the people answered the king, saying, What portion have we in David? neither have we inheritance in the son of Jesse: to your tents, O Israel: now see to thine own house, David. So Israel departed unto their tents."}, {"ref": "1 Kings 12:19", "text": "So Israel rebelled against the house of David unto this day."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jeroboam','whoami',11,12,28,29,'1 Kings 12:28-29',3,'Who am I?','["I was a servant of Solomon, from the tribe of Ephraim.", "The prophet Ahijah tore a new garment into twelve pieces and gave me ten.", "I became king over the ten northern tribes.", "I set up calves of gold in Beth-el and in Dan."]'::jsonb,'["Ahab", "Omri", "Jeroboam", "Rehoboam"]'::jsonb,2,'Jeroboam made two calves of gold and set one in Beth-el and the other in Dan (1 Kings 12:28-29).','Look in 1 Kings.',null,null,'KJV',array['jeroboam','1 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'Whereupon the king took counsel, and made two calves of gold, and said unto them, It is too much for you to go up to Jerusalem: behold thy gods, O Israel, which brought thee up out of the land of Egypt. And he set the one in Beth-el, and the other put he in Dan.','[[{"ref": "1 Kings 11:26", "text": "And Jeroboam the son of Nebat, an Ephrathite of Zereda, Solomon’s servant, whose mother’s name was Zeruah, a widow woman, even he lifted up his hand against the king."}], [{"ref": "1 Kings 11:29-31", "text": "And it came to pass at that time when Jeroboam went out of Jerusalem, that the prophet Ahijah the Shilonite found him in the way; and he had clad himself with a new garment; and they two were alone in the field: And Ahijah caught the new garment that was on him, and rent it in twelve pieces: And he said to Jeroboam, Take thee ten pieces: for thus saith the LORD, the God of Israel, Behold, I will rend the kingdom out of the hand of Solomon, and will give ten tribes to thee:"}], [{"ref": "1 Kings 12:20", "text": "And it came to pass, when all Israel heard that Jeroboam was come again, that they sent and called him unto the congregation, and made him king over all Israel: there was none that followed the house of David, but the tribe of Judah only."}], [{"ref": "1 Kings 12:28-29", "text": "Whereupon the king took counsel, and made two calves of gold, and said unto them, It is too much for you to go up to Jerusalem: behold thy gods, O Israel, which brought thee up out of the land of Egypt. And he set the one in Beth-el, and the other put he in Dan."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-gehazi','whoami',12,5,27,27,'2 Kings 5:27',3,'Who am I?','["I was the servant of the prophet Elisha.", "I told my master that the Shunammite woman had no child.", "I ran after Naaman and took silver and garments from him.", "The leprosy of Naaman clung to me."]'::jsonb,'["Elisha", "Ziba", "Gehazi", "Baruch"]'::jsonb,2,'Elisha told Gehazi that the leprosy of Naaman would cleave to him, and he went out a leper as white as snow (2 Kings 5:27).','Look in 2 Kings.',null,null,'KJV',array['gehazi','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'The leprosy therefore of Naaman shall cleave unto thee, and unto thy seed for ever. And he went out from his presence a leper as white as snow.','[[{"ref": "2 Kings 4:12", "text": "And he said to Gehazi his servant, Call this Shunammite. And when he had called her, she stood before him."}], [{"ref": "2 Kings 4:14", "text": "And he said, What then is to be done for her? And Gehazi answered, Verily she hath no child, and her husband is old."}], [{"ref": "2 Kings 5:20-23", "text": "But Gehazi, the servant of Elisha the man of God, said, Behold, my master hath spared Naaman this Syrian, in not receiving at his hands that which he brought: but, as the LORD liveth, I will run after him, and take somewhat of him. So Gehazi followed after Naaman. And when Naaman saw him running after him, he lighted down from the chariot to meet him, and said, Is all well? And he said, All is well. My master hath sent me, saying, Behold, even now there be come to me from mount Ephraim two young men of the sons of the prophets: give them, I pray thee, a talent of silver, and two changes of garments. And Naaman said, Be content, take two talents. And he urged him, and bound two talents of …"}], [{"ref": "2 Kings 5:27", "text": "The leprosy therefore of Naaman shall cleave unto thee, and unto thy seed for ever. And he went out from his presence a leper as white as snow."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jehu','whoami',12,9,20,20,'2 Kings 9:20',3,'Who am I?','["A young prophet anointed me king over Israel.", "The watchman knew me because I drove furiously.", "I had Jezebel thrown down from a window.", "I destroyed the worship of Baal out of Israel."]'::jsonb,'["Elisha", "Joram", "Jehu", "Ahab"]'::jsonb,2,'The watchman said the driving is like the driving of Jehu the son of Nimshi, for he driveth furiously (2 Kings 9:20).','Look in 2 Kings.',null,null,'KJV',array['jehu','2 Kings']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And the watchman told, saying, He came even unto them, and cometh not again: and the driving is like the driving of Jehu the son of Nimshi; for he driveth furiously.','[[{"ref": "2 Kings 9:4-6", "text": "So the young man, even the young man the prophet, went to Ramoth-gilead. And when he came, behold, the captains of the host were sitting; and he said, I have an errand to thee, O captain. And Jehu said, Unto which of all us? And he said, To thee, O captain. And he arose, and went into the house; and he poured the oil on his head, and said unto him, Thus saith the LORD God of Israel, I have anointed thee king over the people of the LORD, even over Israel."}], [{"ref": "2 Kings 9:20", "text": "And the watchman told, saying, He came even unto them, and cometh not again: and the driving is like the driving of Jehu the son of Nimshi; for he driveth furiously."}], [{"ref": "2 Kings 9:30", "text": "And when Jehu was come to Jezreel, Jezebel heard of it; and she painted her face, and tired her head, and looked out at a window."}, {"ref": "2 Kings 9:33", "text": "And he said, Throw her down. So they threw her down: and some of her blood was sprinkled on the wall, and on the horses: and he trode her under foot."}], [{"ref": "2 Kings 10:28", "text": "Thus Jehu destroyed Baal out of Israel."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-nebuchadnezzar','whoami',27,4,33,33,'Daniel 4:33',2,'Who am I?','["I was king of Babylon.", "I dreamed of a great image with a head of gold.", "I set up a golden image and commanded everyone to worship it.", "I ate grass as oxen until I knew that the most High rules."]'::jsonb,'["Nebuchadnezzar", "Belshazzar", "Darius", "Cyrus"]'::jsonb,0,'The word was fulfilled upon Nebuchadnezzar: he was driven from men and did eat grass as oxen (Daniel 4:33).','Look in Daniel.',null,null,'KJV',array['nebuchadnezzar','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'The same hour was the thing fulfilled upon Nebuchadnezzar: and he was driven from men, and did eat grass as oxen, and his body was wet with the dew of heaven, till his hairs were grown like eagles’ feathers, and his nails like birds’ claws.','[[{"ref": "Daniel 1:1", "text": "In the third year of the reign of Jehoiakim king of Judah came Nebuchadnezzar king of Babylon unto Jerusalem, and besieged it."}], [{"ref": "Daniel 2:1", "text": "And in the second year of the reign of Nebuchadnezzar Nebuchadnezzar dreamed dreams, wherewith his spirit was troubled, and his sleep brake from him."}, {"ref": "Daniel 2:31-32", "text": "Thou, O king, sawest, and behold a great image. This great image, whose brightness was excellent, stood before thee; and the form thereof was terrible. This image’s head was of fine gold, his breast and his arms of silver, his belly and his thighs of brass,"}], [{"ref": "Daniel 3:1", "text": "Nebuchadnezzar the king made an image of gold, whose height was threescore cubits, and the breadth thereof six cubits: he set it up in the plain of Dura, in the province of Babylon."}, {"ref": "Daniel 3:4-5", "text": "Then an herald cried aloud, To you it is commanded, O people, nations, and languages, That at what time ye hear the sound of the cornet, flute, harp, sackbut, psaltery, dulcimer, and all kinds of musick, ye fall down and worship the golden image that Nebuchadnezzar the king hath set up:"}], [{"ref": "Daniel 4:32-33", "text": "And they shall drive thee from men, and thy dwelling shall be with the beasts of the field: they shall make thee to eat grass as oxen, and seven times shall pass over thee, until thou know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will. The same hour was the thing fulfilled upon Nebuchadnezzar: and he was driven from men, and did eat grass as oxen, and his body was wet with the dew of heaven, till his hairs were grown like eagles’ feathers, and his nails like birds’ claws."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-belshazzar','whoami',27,5,30,30,'Daniel 5:30',3,'Who am I?','["I was a king of the Chaldeans in Babylon.", "I drank wine from the golden vessels taken from the temple in Jerusalem.", "The fingers of a man''s hand wrote on the wall of my palace.", "I was slain that same night."]'::jsonb,'["Ahasuerus", "Belshazzar", "Darius", "Nebuchadnezzar"]'::jsonb,1,'In that night was Belshazzar the king of the Chaldeans slain (Daniel 5:30).','Look in Daniel.',null,null,'KJV',array['belshazzar','Daniel']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'In that night was Belshazzar the king of the Chaldeans slain.','[[{"ref": "Daniel 5:1", "text": "Belshazzar the king made a great feast to a thousand of his lords, and drank wine before the thousand."}, {"ref": "Daniel 5:30", "text": "In that night was Belshazzar the king of the Chaldeans slain."}], [{"ref": "Daniel 5:3", "text": "Then they brought the golden vessels that were taken out of the temple of the house of God which was at Jerusalem; and the king, and his princes, his wives, and his concubines, drank in them."}], [{"ref": "Daniel 5:5", "text": "In the same hour came forth fingers of a man’s hand, and wrote over against the candlestick upon the plaister of the wall of the king’s palace: and the king saw the part of the hand that wrote."}], [{"ref": "Daniel 5:30", "text": "In that night was Belshazzar the king of the Chaldeans slain."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-cyrus','whoami',15,1,2,2,'Ezra 1:2',3,'Who am I?','["I was king of Persia.", "The LORD stirred up my spirit to make a proclamation.", "I declared that a house should be built for the LORD at Jerusalem.", "Isaiah calls me the LORD''s anointed."]'::jsonb,'["Darius", "Artaxerxes", "Nebuchadnezzar", "Cyrus"]'::jsonb,3,'Thus saith Cyrus king of Persia: the LORD God of heaven hath charged me to build him an house at Jerusalem (Ezra 1:2).','Look in Ezra.',null,null,'KJV',array['cyrus','Ezra']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'Thus saith Cyrus king of Persia, The LORD God of heaven hath given me all the kingdoms of the earth; and he hath charged me to build him an house at Jerusalem, which is in Judah.','[[{"ref": "Ezra 1:1", "text": "Now in the first year of Cyrus king of Persia, that the word of the LORD by the mouth of Jeremiah might be fulfilled, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"}], [{"ref": "Ezra 1:1", "text": "Now in the first year of Cyrus king of Persia, that the word of the LORD by the mouth of Jeremiah might be fulfilled, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"}], [{"ref": "Ezra 1:2-3", "text": "Thus saith Cyrus king of Persia, The LORD God of heaven hath given me all the kingdoms of the earth; and he hath charged me to build him an house at Jerusalem, which is in Judah. Who is there among you of all his people? his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of the LORD God of Israel, (he is the God,) which is in Jerusalem."}], [{"ref": "Isaiah 45:1", "text": "Thus saith the LORD to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him; and I will loose the loins of kings, to open before him the two leaved gates; and the gates shall not be shut;"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-mordecai','whoami',17,3,2,2,'Esther 3:2',2,'Who am I?','["I was a Jew who sat in the king''s gate in Shushan.", "I reported a plot by two chamberlains to kill the king.", "I would not bow down to Haman.", "I raised my cousin Esther as my own daughter."]'::jsonb,'["Nehemiah", "Mordecai", "Daniel", "Haman"]'::jsonb,1,'All the king''s servants bowed to Haman, but Mordecai bowed not, nor did him reverence (Esther 3:2).','Look in Esther.',null,null,'KJV',array['mordecai','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And all the king’s servants, that were in the king’s gate, bowed, and reverenced Haman: for the king had so commanded concerning him. But Mordecai bowed not, nor did him reverence.','[[{"ref": "Esther 2:5", "text": "Now in Shushan the palace there was a certain Jew, whose name was Mordecai, the son of Jair, the son of Shimei, the son of Kish, a Benjamite;"}, {"ref": "Esther 2:21", "text": "In those days, while Mordecai sat in the king’s gate, two of the king’s chamberlains, Bigthan and Teresh, of those which kept the door, were wroth, and sought to lay hand on the king Ahasuerus."}], [{"ref": "Esther 2:21-22", "text": "In those days, while Mordecai sat in the king’s gate, two of the king’s chamberlains, Bigthan and Teresh, of those which kept the door, were wroth, and sought to lay hand on the king Ahasuerus. And the thing was known to Mordecai, who told it unto Esther the queen; and Esther certified the king thereof in Mordecai’s name."}], [{"ref": "Esther 3:2", "text": "And all the king’s servants, that were in the king’s gate, bowed, and reverenced Haman: for the king had so commanded concerning him. But Mordecai bowed not, nor did him reverence."}], [{"ref": "Esther 2:7", "text": "And he brought up Hadassah, that is, Esther, his uncle’s daughter: for she had neither father nor mother, and the maid was fair and beautiful; whom Mordecai, when her father and mother were dead, took for his own daughter."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-haman','whoami',17,7,10,10,'Esther 7:10',2,'Who am I?','["King Ahasuerus set me above all the princes.", "I was full of wrath because a Jew would not bow to me.", "Pur, that is, the lot, was cast before me to choose a day to destroy the Jews.", "I was hanged on the gallows I had prepared for another man."]'::jsonb,'["Haman", "Darius", "Mordecai", "Ahasuerus"]'::jsonb,0,'They hanged Haman on the gallows that he had prepared for Mordecai (Esther 7:10).','Look in Esther.',null,null,'KJV',array['haman','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king’s wrath pacified.','[[{"ref": "Esther 3:1", "text": "After these things did king Ahasuerus promote Haman the son of Hammedatha the Agagite, and advanced him, and set his seat above all the princes that were with him."}], [{"ref": "Esther 3:5", "text": "And when Haman saw that Mordecai bowed not, nor did him reverence, then was Haman full of wrath."}], [{"ref": "Esther 3:6-7", "text": "And he thought scorn to lay hands on Mordecai alone; for they had shewed him the people of Mordecai: wherefore Haman sought to destroy all the Jews that were throughout the whole kingdom of Ahasuerus, even the people of Mordecai. In the first month, that is, the month Nisan, in the twelfth year of king Ahasuerus, they cast Pur, that is, the lot, before Haman from day to day, and from month to month, to the twelfth month, that is, the month Adar."}], [{"ref": "Esther 7:10", "text": "So they hanged Haman on the gallows that he had prepared for Mordecai. Then was the king’s wrath pacified."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-vashti','whoami',17,1,12,12,'Esther 1:12',3,'Who am I?','["I was queen to King Ahasuerus.", "I made a feast for the women in the royal house.", "I refused to come when the king sent his chamberlains for me.", "My royal estate was given to another who was better than I."]'::jsonb,'["Esther", "Michal", "Vashti", "Jezebel"]'::jsonb,2,'The queen Vashti refused to come at the king''s commandment by his chamberlains (Esther 1:12).','Look in the books of history.',null,null,'KJV',array['vashti','Esther']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'But the queen Vashti refused to come at the king’s commandment by his chamberlains: therefore was the king very wroth, and his anger burned in him.','[[{"ref": "Esther 1:9", "text": "Also Vashti the queen made a feast for the women in the royal house which belonged to king Ahasuerus."}], [{"ref": "Esther 1:9", "text": "Also Vashti the queen made a feast for the women in the royal house which belonged to king Ahasuerus."}], [{"ref": "Esther 1:12", "text": "But the queen Vashti refused to come at the king’s commandment by his chamberlains: therefore was the king very wroth, and his anger burned in him."}], [{"ref": "Esther 1:19", "text": "If it please the king, let there go a royal commandment from him, and let it be written among the laws of the Persians and the Medes, that it be not altered, That Vashti come no more before king Ahasuerus; and let the king give her royal estate unto another that is better than she."}, {"ref": "Esther 2:17", "text": "And the king loved Esther above all the women, and she obtained grace and favour in his sight more than all the virgins; so that he set the royal crown upon her head, and made her queen instead of Vashti."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-james_zebedee','whoami',44,12,2,2,'Acts 12:2',3,'Who am I?','["My father was Zebedee.", "I was mending nets in a ship when Jesus called me.", "Jesus called my brother and me Boanerges, the sons of thunder.", "King Herod killed me with the sword."]'::jsonb,'["Peter", "James", "Philip", "Andrew"]'::jsonb,1,'Herod killed James the brother of John with the sword (Acts 12:2).','Look in Acts.',null,null,'KJV',array['james_zebedee','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And he killed James the brother of John with the sword.','[[{"ref": "Matthew 4:21", "text": "And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them."}], [{"ref": "Matthew 4:21", "text": "And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them."}], [{"ref": "Mark 3:17", "text": "And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder:"}], [{"ref": "Acts 12:1-2", "text": "Now about that time Herod the king stretched forth his hands to vex certain of the church. And he killed James the brother of John with the sword."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-bartimaeus','whoami',41,10,46,46,'Mark 10:46',2,'Who am I?','["I was a blind beggar sitting by the highway near Jericho.", "I cried out, Jesus, thou son of David, have mercy on me.", "When many told me to be quiet, I cried all the more.", "I cast away my garment, came to Jesus and received my sight."]'::jsonb,'["Lazarus", "Zacchaeus", "Bartimaeus", "Malchus"]'::jsonb,2,'Blind Bartimaeus, the son of Timaeus, sat by the highway side begging as Jesus left Jericho (Mark 10:46).','Look in Mark.',null,null,'KJV',array['bartimaeus','Mark']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And they came to Jericho: and as he went out of Jericho with his disciples and a great number of people, blind Bartimæus, the son of Timæus, sat by the highway side begging.','[[{"ref": "Mark 10:46", "text": "And they came to Jericho: and as he went out of Jericho with his disciples and a great number of people, blind Bartimæus, the son of Timæus, sat by the highway side begging."}], [{"ref": "Mark 10:47", "text": "And when he heard that it was Jesus of Nazareth, he began to cry out, and say, Jesus, thou Son of David, have mercy on me."}], [{"ref": "Mark 10:48", "text": "And many charged him that he should hold his peace: but he cried the more a great deal, Thou Son of David, have mercy on me."}], [{"ref": "Mark 10:50-52", "text": "And he, casting away his garment, rose, and came to Jesus. And Jesus answered and said unto him, What wilt thou that I should do unto thee? The blind man said unto him, Lord, that I might receive my sight. And Jesus said unto him, Go thy way; thy faith hath made thee whole. And immediately he received his sight, and followed Jesus in the way."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-jairus','whoami',41,5,22,22,'Mark 5:22',2,'Who am I?','["I was a ruler of the synagogue.", "I fell at Jesus'' feet and begged him to come to my house.", "My little daughter lay at the point of death.", "Jesus took her by the hand and said, Talitha cumi."]'::jsonb,'["Nicodemus", "Zacharias", "Jairus", "Cornelius"]'::jsonb,2,'One of the rulers of the synagogue, Jairus by name, fell at Jesus'' feet (Mark 5:22).','Look in Mark.',null,null,'KJV',array['jairus','Mark']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And, behold, there cometh one of the rulers of the synagogue, Jairus by name; and when he saw him, he fell at his feet,','[[{"ref": "Mark 5:22", "text": "And, behold, there cometh one of the rulers of the synagogue, Jairus by name; and when he saw him, he fell at his feet,"}], [{"ref": "Luke 8:41", "text": "And, behold, there came a man named Jairus, and he was a ruler of the synagogue: and he fell down at Jesus’ feet, and besought him that he would come into his house:"}], [{"ref": "Mark 5:23", "text": "And besought him greatly, saying, My little daughter lieth at the point of death: I pray thee, come and lay thy hands on her, that she may be healed; and she shall live."}], [{"ref": "Mark 5:41", "text": "And he took the damsel by the hand, and said unto her, Talitha cumi; which is, being interpreted, Damsel, I say unto thee, arise."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-mary_bethany','whoami',42,10,39,39,'Luke 10:39',2,'Who am I?','["My sister was Martha and my brother was Lazarus.", "I sat at Jesus'' feet and heard his word.", "Jesus said I had chosen that good part.", "I anointed Jesus'' feet with costly spikenard and wiped them with my hair."]'::jsonb,'["Mary Magdalene", "Martha", "Salome", "Mary of Bethany"]'::jsonb,3,'Martha had a sister called Mary, which also sat at Jesus'' feet, and heard his word (Luke 10:39).','Look in Luke.',null,null,'KJV',array['mary_bethany','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And she had a sister called Mary, which also sat at Jesus’ feet, and heard his word.','[[{"ref": "John 11:1-2", "text": "Now a certain man was sick, named Lazarus, of Bethany, the town of Mary and her sister Martha. (It was that Mary which anointed the Lord with ointment, and wiped his feet with her hair, whose brother Lazarus was sick.)"}], [{"ref": "Luke 10:39", "text": "And she had a sister called Mary, which also sat at Jesus’ feet, and heard his word."}], [{"ref": "Luke 10:42", "text": "But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her."}], [{"ref": "John 12:3", "text": "Then took Mary a pound of ointment of spikenard, very costly, and anointed the feet of Jesus, and wiped his feet with her hair: and the house was filled with the odour of the ointment."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-simon_cyrene','whoami',41,15,21,21,'Mark 15:21',2,'Who am I?','["I was passing by, coming out of the country.", "I was compelled to bear a cross.", "The cross I carried was the cross of Jesus.", "I came from Cyrene and was the father of Alexander and Rufus."]'::jsonb,'["Nicodemus", "Simon of Cyrene", "Barabbas", "Joseph of Arimathea"]'::jsonb,1,'They compelled Simon a Cyrenian, coming out of the country, the father of Alexander and Rufus, to bear his cross (Mark 15:21).','Look in Mark.',null,null,'KJV',array['simon_cyrene','Mark']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross.','[[{"ref": "Mark 15:21", "text": "And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross."}], [{"ref": "Matthew 27:32", "text": "And as they came out, they found a man of Cyrene, Simon by name: him they compelled to bear his cross."}], [{"ref": "Luke 23:26", "text": "And as they led him away, they laid hold upon one Simon, a Cyrenian, coming out of the country, and on him they laid the cross, that he might bear it after Jesus."}], [{"ref": "Mark 15:21", "text": "And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-barabbas','whoami',41,15,15,15,'Mark 15:15',2,'Who am I?','["I was a prisoner in Jerusalem.", "I had been bound with others who had made insurrection and committed murder.", "Pilate offered the crowd a choice between Jesus and me.", "The people asked for me to be released."]'::jsonb,'["Judas", "Simon of Cyrene", "Malchus", "Barabbas"]'::jsonb,3,'Pilate, willing to content the people, released Barabbas unto them (Mark 15:15).','Look in Mark.',null,null,'KJV',array['barabbas','Mark']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And so Pilate, willing to content the people, released Barabbas unto them, and delivered Jesus, when he had scourged him, to be crucified.','[[{"ref": "Matthew 27:15-16", "text": "Now at that feast the governor was wont to release unto the people a prisoner, whom they would. And they had then a notable prisoner, called Barabbas."}], [{"ref": "Mark 15:7", "text": "And there was one named Barabbas, which lay bound with them that had made insurrection with him, who had committed murder in the insurrection."}], [{"ref": "Matthew 27:17", "text": "Therefore when they were gathered together, Pilate said unto them, Whom will ye that I release unto you? Barabbas, or Jesus which is called Christ?"}], [{"ref": "Mark 15:11", "text": "But the chief priests moved the people, that he should rather release Barabbas unto them."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-joseph_arimathea','whoami',40,27,59,60,'Matthew 27:59-60',3,'Who am I?','["I was an honourable counsellor who waited for the kingdom of God.", "I was a disciple of Jesus, but secretly, for fear of the Jews.", "I went to Pilate and begged the body of Jesus.", "I laid Jesus in my own new tomb, hewn out in the rock."]'::jsonb,'["Joseph of Arimathea", "Lazarus", "Nicodemus", "Gamaliel"]'::jsonb,0,'Joseph wrapped the body in clean linen and laid it in his own new tomb, hewn out in the rock (Matthew 27:59-60).','Look in Matthew.',null,null,'KJV',array['joseph_arimathea','Matthew']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And when Joseph had taken the body, he wrapped it in a clean linen cloth, And laid it in his own new tomb, which he had hewn out in the rock: and he rolled a great stone to the door of the sepulchre, and departed.','[[{"ref": "Mark 15:43", "text": "Joseph of Arimathaea, an honourable counsellor, which also waited for the kingdom of God, came, and went in boldly unto Pilate, and craved the body of Jesus."}], [{"ref": "John 19:38", "text": "And after this Joseph of Arimathaea, being a disciple of Jesus, but secretly for fear of the Jews, besought Pilate that he might take away the body of Jesus: and Pilate gave him leave. He came therefore, and took the body of Jesus."}], [{"ref": "Mark 15:43", "text": "Joseph of Arimathaea, an honourable counsellor, which also waited for the kingdom of God, came, and went in boldly unto Pilate, and craved the body of Jesus."}], [{"ref": "Matthew 27:60", "text": "And laid it in his own new tomb, which he had hewn out in the rock: and he rolled a great stone to the door of the sepulchre, and departed."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-matthias','whoami',44,1,26,26,'Acts 1:26',3,'Who am I?','["I followed Jesus from the baptism of John until he was taken up.", "My name was put forward together with Joseph called Barsabas.", "The disciples prayed and gave forth their lots.", "I was numbered with the eleven apostles in the place of Judas."]'::jsonb,'["Barnabas", "Stephen", "Silas", "Matthias"]'::jsonb,3,'The lot fell upon Matthias, and he was numbered with the eleven apostles (Acts 1:26).','Look in Acts.',null,null,'KJV',array['matthias','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And they gave forth their lots; and the lot fell upon Matthias; and he was numbered with the eleven apostles.','[[{"ref": "Acts 1:21-23", "text": "Wherefore of these men which have companied with us all the time that the Lord Jesus went in and out among us, Beginning from the baptism of John, unto that same day that he was taken up from us, must one be ordained to be a witness with us of his resurrection. And they appointed two, Joseph called Barsabas, who was surnamed Justus, and Matthias."}], [{"ref": "Acts 1:23", "text": "And they appointed two, Joseph called Barsabas, who was surnamed Justus, and Matthias."}], [{"ref": "Acts 1:24-26", "text": "And they prayed, and said, Thou, Lord, which knowest the hearts of all men, shew whether of these two thou hast chosen, That he may take part of this ministry and apostleship, from which Judas by transgression fell, that he might go to his own place. And they gave forth their lots; and the lot fell upon Matthias; and he was numbered with the eleven apostles."}], [{"ref": "Acts 1:25-26", "text": "That he may take part of this ministry and apostleship, from which Judas by transgression fell, that he might go to his own place. And they gave forth their lots; and the lot fell upon Matthias; and he was numbered with the eleven apostles."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-ananias','whoami',44,9,17,17,'Acts 9:17',3,'Who am I?','["I was a disciple living in Damascus.", "The Lord spoke to me in a vision about a man named Saul.", "I told the Lord I had heard how much evil Saul had done to the saints.", "I put my hands on Saul so that he might receive his sight."]'::jsonb,'["Ananias", "Barnabas", "Philip", "Silas"]'::jsonb,0,'Ananias entered the house and, putting his hands on him, said, Brother Saul (Acts 9:17).','Look in Acts.',null,null,'KJV',array['ananias','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, even Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost.','[[{"ref": "Acts 9:10", "text": "And there was a certain disciple at Damascus, named Ananias; and to him said the Lord in a vision, Ananias. And he said, Behold, I am here, Lord."}], [{"ref": "Acts 9:10-12", "text": "And there was a certain disciple at Damascus, named Ananias; and to him said the Lord in a vision, Ananias. And he said, Behold, I am here, Lord. And the Lord said unto him, Arise, and go into the street which is called Straight, and enquire in the house of Judas for one called Saul, of Tarsus: for, behold, he prayeth, And hath seen in a vision a man named Ananias coming in, and putting his hand on him, that he might receive his sight."}], [{"ref": "Acts 9:13", "text": "Then Ananias answered, Lord, I have heard by many of this man, how much evil he hath done to thy saints at Jerusalem:"}], [{"ref": "Acts 9:17", "text": "And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, even Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-eutychus','whoami',44,20,9,9,'Acts 20:9',3,'Who am I?','["I was a young man in Troas.", "I sat in a window while Paul preached until midnight.", "I fell into a deep sleep and fell down from the third loft.", "Paul embraced me, and I was brought alive."]'::jsonb,'["Eutychus", "Tychicus", "Onesimus", "Timothy"]'::jsonb,0,'A young man named Eutychus sank down with sleep and fell from the third loft (Acts 20:9).','Look in Acts.',null,null,'KJV',array['eutychus','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead.','[[{"ref": "Acts 20:6", "text": "And we sailed away from Philippi after the days of unleavened bread, and came unto them to Troas in five days; where we abode seven days."}, {"ref": "Acts 20:9", "text": "And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead."}], [{"ref": "Acts 20:7-9", "text": "And upon the first day of the week, when the disciples came together to break bread, Paul preached unto them, ready to depart on the morrow; and continued his speech until midnight. And there were many lights in the upper chamber, where they were gathered together. And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead."}], [{"ref": "Acts 20:9", "text": "And there sat in a window a certain young man named Eutychus, being fallen into a deep sleep: and as Paul was long preaching, he sunk down with sleep, and fell down from the third loft, and was taken up dead."}], [{"ref": "Acts 20:10-12", "text": "And Paul went down, and fell on him, and embracing him said, Trouble not yourselves; for his life is in him. When he therefore was come up again, and had broken bread, and eaten, and talked a long while, even till break of day, so he departed. And they brought the young man alive, and were not a little comforted."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-agrippa','whoami',44,26,28,28,'Acts 26:28',4,'Who am I?','["I was a king who came to Caesarea with Bernice to greet Festus.", "Festus told me about a prisoner named Paul.", "Paul made his defence before me.", "I said to Paul, Almost thou persuadest me to be a Christian."]'::jsonb,'["Festus", "Gallio", "Felix", "Agrippa"]'::jsonb,3,'Agrippa said unto Paul, Almost thou persuadest me to be a Christian (Acts 26:28).','Look in Acts.',null,null,'KJV',array['agrippa','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'Then Agrippa said unto Paul, Almost thou persuadest me to be a Christian.','[[{"ref": "Acts 25:13", "text": "And after certain days king Agrippa and Bernice came unto Cæsarea to salute Festus."}], [{"ref": "Acts 25:14", "text": "And when they had been there many days, Festus declared Paul’s cause unto the king, saying, There is a certain man left in bonds by Felix:"}], [{"ref": "Acts 26:1-2", "text": "Then Agrippa said unto Paul, Thou art permitted to speak for thyself. Then Paul stretched forth the hand, and answered for himself: I think myself happy, king Agrippa, because I shall answer for myself this day before thee touching all the things whereof I am accused of the Jews:"}], [{"ref": "Acts 26:28", "text": "Then Agrippa said unto Paul, Almost thou persuadest me to be a Christian."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-onesimus','whoami',57,1,10,10,'Philemon 1:10',4,'Who am I?','["I departed from my master for a season.", "Paul begat me while he was in bonds.", "I was once unprofitable to my master, but now profitable.", "Paul sent me back to Philemon as a brother beloved."]'::jsonb,'["Tychicus", "Titus", "Onesimus", "Epaphras"]'::jsonb,2,'Paul wrote, I beseech thee for my son Onesimus, whom I have begotten in my bonds (Philemon 1:10).','Look in Philemon.',null,null,'KJV',array['onesimus','Philemon']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'I beseech thee for my son Onesimus, whom I have begotten in my bonds:','[[{"ref": "Philemon 1:15", "text": "For perhaps he therefore departed for a season, that thou shouldest receive him for ever;"}], [{"ref": "Philemon 1:10", "text": "I beseech thee for my son Onesimus, whom I have begotten in my bonds:"}], [{"ref": "Philemon 1:11", "text": "Which in time past was to thee unprofitable, but now profitable to thee and to me:"}], [{"ref": "Philemon 1:12-16", "text": "Whom I have sent again: thou therefore receive him, that is, mine own bowels: Whom I would have retained with me, that in thy stead he might have ministered unto me in the bonds of the gospel: But without thy mind would I do nothing; that thy benefit should not be as it were of necessity, but willingly. For perhaps he therefore departed for a season, that thou shouldest receive him for ever; Not now as a servant, but above a servant, a brother beloved, specially to me, but how much more unto thee, both in the flesh, and in the Lord?"}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('who-john_mark','whoami',44,15,39,39,'Acts 15:39',3,'Who am I?','["Many gathered to pray at my mother Mary''s house in Jerusalem.", "I went with Barnabas and Saul but left them in Pamphylia.", "Paul and Barnabas parted over whether to take me again.", "Paul later wrote that I was profitable to him for the ministry."]'::jsonb,'["Mark", "Luke", "Timothy", "Silas"]'::jsonb,0,'The contention was so sharp that they parted, and Barnabas took Mark and sailed to Cyprus (Acts 15:39).','Look in Acts.',null,null,'KJV',array['john_mark','Acts']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'And the contention was so sharp between them, that they departed asunder one from the other: and so Barnabas took Mark, and sailed unto Cyprus;','[[{"ref": "Acts 12:12", "text": "And when he had considered the thing, he came to the house of Mary the mother of John, whose surname was Mark; where many were gathered together praying."}], [{"ref": "Acts 12:25", "text": "And Barnabas and Saul returned from Jerusalem, when they had fulfilled their ministry, and took with them John, whose surname was Mark."}, {"ref": "Acts 13:13", "text": "Now when Paul and his company loosed from Paphos, they came to Perga in Pamphylia: and John departing from them returned to Jerusalem."}], [{"ref": "Acts 15:37-39", "text": "And Barnabas determined to take with them John, whose surname was Mark. But Paul thought not good to take him with them, who departed from them from Pamphylia, and went not with them to the work. And the contention was so sharp between them, that they departed asunder one from the other: and so Barnabas took Mark, and sailed unto Cyprus;"}], [{"ref": "2 Timothy 4:11", "text": "Only Luke is with me. Take Mark, and bring him with thee: for he is profitable to me for the ministry."}]]'::jsonb) on conflict (id) do nothing;
insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('scr-cv-genesis-1-1','scripture',1,1,1,1,'Genesis 1:1',1,'Complete the verse: “In the beginning God created the _____ and the earth.”',null,'["world", "light", "heaven", "sea"]'::jsonb,2,'Genesis 1:1 (KJV): “In the beginning God created the heaven and the earth.”','The missing word appears 1 time(s).',null,null,'KJV',array['complete-verse','Genesis']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "approved", "reviewed_at": "2026-11-21", "review_method": "KJV accuracy check: exact text match for Scripture Quiz; AI-assisted clue/event check against KJV text with every flag read; see tests/review/REPORT.md"}'::jsonb,'In the beginning God created the heaven and the earth.',null) on conflict (id) do nothing;
