insert into public.questions (id, game_mode, book_id, chapter, verse_start, verse_end, reference_label, difficulty, prompt, clues, options, correct_index, explanation, hint, image_id, image_alt, translation_id, tags, status, verification, verse_text, clue_refs) values ('seq-peter_denial','sequence',42,22,33,33,'Luke 22:33-62',2,'Put these events in order: Peter''s Denial',null,'["Peter says he is ready to go to prison and to death", "Peter follows afar off", "Peter says, Woman, I know him not", "The Lord turns and looks upon Peter", "Peter goes out and weeps bitterly"]'::jsonb,0,'Peter says he is ready to go to prison and to death (Luke 22:33) → Peter follows afar off (Luke 22:54) → Peter says, Woman, I know him not (Luke 22:57) → The Lord turns and looks upon Peter (Luke 22:61) → Peter goes out and weeps bitterly (Luke 22:62)','The first event is in Luke 22:33.',null,null,'KJV',array['peter_denial','Luke']::text[],'review','{"reference_exists": true, "keywords_found": true, "checked_against": "KJV (thiagobodruk/bible en_kjv.json)", "checked_at": "2026-11-22", "human_review": "pending"}'::jsonb,'Luke 22:33: And he said unto him, Lord, I am ready to go with thee, both into prison, and to death.
